package com.thebirdhouse.plugin;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.widgets.WidgetID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Detects collection log additions, quest completions, level-ups,
 * and other achievements that might match board tiles.
 */
@Slf4j
@Singleton
public class AchievementTracker {

    private static final Pattern COLLECTION_LOG_PATTERN =
        Pattern.compile("New item added to your collection log: (.+)");
    private static final Pattern QUEST_COMPLETE_PATTERN =
        Pattern.compile("Congratulations, you've completed a quest: (.+)");
    private static final Pattern LEVEL_UP_PATTERN =
        Pattern.compile("Congratulations, you've reached (\\w+) level (\\d+)");
    private static final Pattern PET_PATTERN =
        Pattern.compile("You have a funny feeling like you're being followed");

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private BirdhouseConfig config;

    @Inject
    private BirdhouseApiClient apiClient;

    @Inject
    private ScreenshotHelper screenshotHelper;

    private String activeRoomCode;
    private BoardData activeBoard;

    public void setActiveBoard(String roomCode, BoardData board) {
        this.activeRoomCode = roomCode;
        this.activeBoard = board;
    }

    /**
     * Whether there is a live event to submit against. Collection-log entries, quests and
     * pets keep arriving long after a bingo ends, and the configured room code outlives
     * the event, so without this every one of them would be uploaded and rejected for as
     * long as the plugin stays installed. Absent flags mean live, to stay compatible with
     * a server that predates them.
     */
    private boolean eventLive() {
        BoardData board = activeBoard;
        if (board == null) return false;
        return !Boolean.FALSE.equals(board.getActive())
            && !Boolean.FALSE.equals(board.getStarted());
    }

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        if (!config.autoSubmitDrops() || !eventLive()) return;

        String message = event.getMessage();
        if (message == null) return;

        // Strip colour/formatting tags
        String clean = message.replaceAll("<[^>]+>", "").trim();

        // Collection log
        Matcher collLogMatcher = COLLECTION_LOG_PATTERN.matcher(clean);
        if (collLogMatcher.find()) {
            String itemName = collLogMatcher.group(1);
            tryMatchAndSubmit(itemName, "collection_log");
            return;
        }

        // Quest completion
        Matcher questMatcher = QUEST_COMPLETE_PATTERN.matcher(clean);
        if (questMatcher.find()) {
            String questName = questMatcher.group(1);
            tryMatchAndSubmit(questName, "quest");
            return;
        }

        // Pet drop
        if (PET_PATTERN.matcher(clean).find()) {
            tryMatchAndSubmit("Pet drop", "pet");
            return;
        }
    }

    @Subscribe
    public void onStatChanged(StatChanged event) {
        if (!config.autoSubmitDrops() || !eventLive()) return;

        int level = event.getLevel();
        String skillName = event.getSkill().getName();

        // Check for milestone levels that might match tiles
        // Common milestones: 99, base levels, specific level thresholds
        String milestone = skillName + " level " + level;
        String milestone99 = level == 99 ? "99 " + skillName : null;

        tryMatchAndSubmit(milestone, "level_up");
        if (milestone99 != null) {
            tryMatchAndSubmit(milestone99, "level_up");
            tryMatchAndSubmit("99 in any skill", "level_up");
        }
    }

    private void tryMatchAndSubmit(String achievementName, String achievementType) {
        if (activeBoard == null || activeBoard.getTiles() == null) return;

        String search = achievementName.toLowerCase();
        // Collection-log unlocks are concrete items: match them strictly against the
        // tile's accepted item list (or an exact matchName). Loose substring matching
        // caused false positives (e.g. "Vorkath's head" matching a "Vorkath" visage
        // tile). Quests/pets/levels stay on the looser label match.
        boolean strict = "collection_log".equals(achievementType);

        for (BoardTile tile : activeBoard.getTiles()) {
            if (tile.isCompleted()) continue;

            if (strict) {
                if (collectionItemMatchesTile(tile, search)) {
                    submitAchievement(tile, achievementName, achievementType);
                    break;
                }
                continue;
            }

            String matchName = tile.getMatchName();
            if (matchName == null || matchName.isEmpty()) continue;

            if (matchName.toLowerCase().equals(search) ||
                matchName.toLowerCase().contains(search) ||
                search.contains(matchName.toLowerCase())) {

                submitAchievement(tile, achievementName, achievementType);
                break;
            }
        }
    }

    // Strict collection-log matching: the unlocked item must be one of the tile's
    // explicit accepted items (matchItems), or exactly equal the tile's matchName.
    // No substring matching — that produced cross-tile false positives.
    private boolean collectionItemMatchesTile(BoardTile tile, String itemLower) {
        List<String> matchItems = tile.getMatchItems();
        if (matchItems != null && !matchItems.isEmpty()) {
            for (String acc : matchItems) {
                if (acc != null && acc.toLowerCase().equals(itemLower)) return true;
            }
            return false;
        }
        String matchName = tile.getMatchName();
        if (matchName == null || matchName.isEmpty()) return false;
        return matchName.toLowerCase().equals(itemLower);
    }

    private void submitAchievement(BoardTile tile, String achievementName, String achievementType) {
        String playerName = client.getLocalPlayer().getName();

        ProofPayload payload = new ProofPayload();
        payload.setRoomCode(activeRoomCode);
        payload.setPlayerName(playerName);
        payload.setTileKey(tile.getKey());
        payload.setTileName(tile.getName());
        payload.setGameType(tile.getGameType());
        payload.setItemName(achievementName);
        payload.setNpcName(achievementType);
        payload.setQuantity(1);
        payload.setTimestamp(System.currentTimeMillis());

        String confirmation = "[Birdhouse] Achievement matched: " + tile.getName()
            + " (" + achievementName + ")";

        if (config.includeScreenshot()) {
            screenshotHelper.captureAsync(screenshot -> {
                apiClient.submitProof(payload, screenshot).thenAccept(result -> {
                    if (result.isOk() && !result.isDuplicate()) {
                        notifyInGame(confirmation);
                    }
                });
            });
        } else {
            apiClient.submitProof(payload, null).thenAccept(result -> {
                if (result.isOk() && !result.isDuplicate()) {
                    notifyInGame(confirmation);
                }
            });
        }

        log.info("Achievement matched tile '{}': {} ({})", tile.getName(), achievementName, achievementType);
    }

    /**
     * Confirmation in the game chat that an achievement went in.
     *
     * Handed to the client thread because this runs in the submit callback, on an HTTP
     * thread, and addChatMessage does nothing from off the client thread.
     */
    private void notifyInGame(String message) {
        if (!config.notifyOnSubmit()) {
            return;
        }
        clientThread.invoke(() -> client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, ""));
    }
}

package com.thebirdhouse.plugin;

import lombok.Data;

/**
 * Represents an active room the player is in.
 */
@Data
public class ActiveRoom {
    private String code;
    private String gameType;
}

package com.thebirdhouse.plugin;

import lombok.Data;

import java.util.Map;

/**
 * A compact, batched activity delta sent to POST /loot (with batch=true).
 *
 * The plugin accumulates these values locally and flushes one payload on each
 * session heartbeat + logout, so leaderboard stats cost a single request per flush
 * rather than one per kill. The server folds each field into a running per-room,
 * per-player total, so every payload is a DELTA since the last flush.
 */
@Data
public class ActivityPayload {
    /** Marks this as the batched-activity variant of the /loot endpoint. */
    private boolean batch = true;
    /** Explicit event room; may be null, in which case the server attributes the
     *  delta to whatever event rooms the player is currently active in. */
    private String roomCode;
    /** Active (non-AFK) playtime in ms since the last flush. */
    private long activeMs;
    /** Total GE value of all loot since the last flush (no minimum). */
    private long lootGp;
    /** Number of NPC kills (loot events) since the last flush. */
    private int kills;
    /** Value of the single biggest item stack seen this event (running max). */
    private long biggest;
    /** Source NPC of the biggest stack. */
    private String biggestSource;
    /** Per-NPC kill counts since the last flush: { npcName: count }. */
    private Map<String, Integer> npcKills;
}

package com.thebirdhouse.plugin;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Accumulates leaderboard activity locally and flushes a compact delta on each
 * session heartbeat + logout. Tracks:
 *   - active time: only game ticks where XP or a kill happened recently (anti-AFK),
 *   - NPC kills: one per NPC loot event, tallied per monster, except for the handful of
 *     sources that pay out on failure (see KC_CONFIRMED_SOURCES),
 *   - loot GP: GE value of every drop, no minimum.
 *
 * Every flush is a DELTA — the server folds it into a running per-room total — so
 * accumulators reset after each flush. Event handlers run on the client thread while
 * flush() runs on the session scheduler thread, so shared accumulators are guarded.
 */
@Slf4j
@Singleton
public class ActivityTracker {

    // Treat the player as "active" if XP or a kill happened within this window.
    private static final long ACTIVE_IDLE_MS = 60_000;
    // Clamp a single tick's contribution so a paused/laggy client can't over-count.
    private static final long MAX_TICK_MS = 1_200;

    /**
     * Sources whose loot is NOT proof of a kill, keyed by the name the game announces in
     * the killcount message to the name the loot event arrives under.
     *
     * The Gauntlet hands you a consolation chest when you die, and RuneLite books that
     * chest against whichever boss you last fought — so a failed run looks exactly like a
     * completed one to a loot listener. That matters well beyond the leaderboard now that
     * The Delve pays supplies per kill: a death was earning the full Hunllef rate.
     *
     * These are credited from the game's own completion count instead, which only ever
     * fires on a win. Note the two names genuinely differ: the Gauntlet reports a
     * completion count for the minigame while the loot is booked against the boss.
     */
    private static final Map<String, String> KC_CONFIRMED_SOURCES = Map.of(
        "Corrupted Gauntlet", "Corrupted Hunllef",
        "Gauntlet", "Crystalline Hunllef"
    );

    @Inject
    private Client client;

    @Inject
    private ItemManager itemManager;

    @Inject
    private BirdhouseConfig config;

    @Inject
    private BirdhouseApiClient apiClient;

    @Inject
    private DropMatcher dropMatcher;

    private volatile String activeRoomCode;

    // Accumulators (guarded by 'this').
    private long activeMsAccum = 0;
    private long lootGpAccum = 0;
    private int killsAccum = 0;
    private long biggestDrop = 0;
    private String biggestSource = null;
    private final Map<String, Integer> npcKills = new HashMap<>();

    // Client-thread-only activity clock.
    private long lastActivityMs = 0;
    private long lastTickMs = 0;

    public void setActiveRoom(String roomCode) {
        this.activeRoomCode = roomCode;
    }

    /** Clears all local state — used when a new session starts. */
    public void reset() {
        clearAccumulators();
        lastActivityMs = 0;
        lastTickMs = 0;
    }

    private void clearAccumulators() {
        synchronized (this) {
            activeMsAccum = 0;
            lootGpAccum = 0;
            killsAccum = 0;
            biggestDrop = 0;
            biggestSource = null;
            npcKills.clear();
        }
    }

    private void markActive() {
        lastActivityMs = System.currentTimeMillis();
    }

    @Subscribe
    public void onStatChanged(StatChanged event) {
        // Any XP gain counts as activity (covers cannon / afk-combat / skilling that
        // WOM's EHP/EHB largely miss).
        markActive();
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        if (!config.contributeActivityStats()) return;
        long now = System.currentTimeMillis();
        long prev = lastTickMs;
        lastTickMs = now;
        if (prev == 0) return;
        if (now - lastActivityMs <= ACTIVE_IDLE_MS) {
            long delta = Math.min(now - prev, MAX_TICK_MS);
            if (delta > 0) {
                synchronized (this) { activeMsAccum += delta; }
            }
        }
    }

    @Subscribe
    public void onLootReceived(LootReceived event) {
        if (!config.contributeActivityStats()) return;
        // Only monster kills (NPC loot) count — not player kills, clues, or events.
        // Compared by name to avoid a version-specific enum import.
        if (!"NPC".equals(String.valueOf(event.getType()))) return;

        markActive();

        String source = event.getName();
        long eventValue = 0;
        long topStack = 0;
        for (ItemStack stack : event.getItems()) {
            long price = 0;
            try {
                price = itemManager.getItemPrice(stack.getId());
            } catch (Exception ignored) {
                // Untradeable / unknown item — worth 0.
            }
            long stackVal = Math.max(0L, price) * Math.max(0, stack.getQuantity());
            eventValue += stackVal;
            if (stackVal > topStack) topStack = stackVal;
        }

        // The GP is real whether or not the run was won, so it is banked either way; only
        // the kill waits for confirmation from the killcount message.
        boolean awaitKillcount = source != null && KC_CONFIRMED_SOURCES.containsValue(source);

        synchronized (this) {
            lootGpAccum += eventValue;
            if (!awaitKillcount) {
                killsAccum += 1;
                if (source != null && !source.isEmpty()) {
                    npcKills.merge(source, 1, Integer::sum);
                }
            }
            if (topStack > biggestDrop) {
                biggestDrop = topStack;
                biggestSource = source;
            }
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        if (!config.contributeActivityStats()) return;
        if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM) return;

        String boss = KillCounts.bossFrom(event.getMessage());
        if (boss == null) return;

        // Only the sources held back in onLootReceived are credited here. Every other boss
        // was already counted from its loot, and counting it again would double it.
        String source = KC_CONFIRMED_SOURCES.get(boss);
        if (source == null) return;

        markActive();
        synchronized (this) {
            killsAccum += 1;
            npcKills.merge(source, 1, Integer::sum);
        }
    }

    /**
     * Send the accumulated delta and reset. Called from the session heartbeat and on
     * logout. No-ops when tracking is disabled or there's nothing to report.
     */
    public void flush() {
        if (!config.contributeActivityStats()) {
            reset();
            return;
        }

        // Once the event is over the server discards the delta, so sending it buys nothing
        // and would repeat every flush interval for as long as the plugin stays installed.
        // The accumulators are dropped rather than held: keeping them would bank hours of
        // unrelated play and dump the lot into whichever event the player joins next.
        if (dropMatcher.isEventOver()) {
            clearAccumulators();
            return;
        }

        ActivityPayload payload;
        synchronized (this) {
            if (activeMsAccum == 0 && killsAccum == 0 && lootGpAccum == 0) {
                return;
            }
            payload = new ActivityPayload();
            payload.setBatch(true);
            payload.setRoomCode(activeRoomCode);
            payload.setActiveMs(activeMsAccum);
            payload.setLootGp(lootGpAccum);
            payload.setKills(killsAccum);
            payload.setBiggest(biggestDrop);
            payload.setBiggestSource(biggestSource);
            payload.setNpcKills(new HashMap<>(npcKills));

            // Reset the delta accumulators; the server keeps the running total. We
            // intentionally keep biggestDrop as a session-local max reference reset
            // here too, since the server tracks the running max independently.
            activeMsAccum = 0;
            lootGpAccum = 0;
            killsAccum = 0;
            biggestDrop = 0;
            biggestSource = null;
            npcKills.clear();
        }

        apiClient.reportActivity(payload);
    }
}

package com.thebirdhouse.plugin;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.util.concurrent.CompletableFuture;

/**
 * HTTP client for communicating with The Birdhouse backend.
 * All requests are async to avoid blocking the game thread.
 */
@Slf4j
@Singleton
public class BirdhouseApiClient {

    private static final String BASE_URL = "https://thebirdhouse.games/api/plugin";
    // Dedicated always-on cache host for the high-frequency board poll. This is a
    // read-only mirror that serves byte-identical /board responses far more cheaply
    // than Cloud Functions. Only fetchBoard() uses it; if it is ever unreachable or
    // errors, fetchBoard() transparently falls back to BASE_URL, so boards keep
    // working even if this host is down.
    private static final String BOARD_BASE_URL = "https://api.thebirdhouse.games";
    private static final MediaType JSON_TYPE = MediaType.parse("application/json; charset=utf-8");
    private static final MediaType IMAGE_TYPE = MediaType.parse("image/jpeg");

    private final OkHttpClient httpClient;
    private final Gson gson;
    private String authToken = "";

    /** Names the build on every request, so a log line can be read without guesswork. */
    static final String VERSION_HEADER = "X-Birdhouse-Version";

    @Inject
    public BirdhouseApiClient(OkHttpClient httpClient, Gson gson) {
        // Derived rather than added to the injected client, which RuneLite shares with
        // every other plugin. An interceptor rather than a header on each call: there are
        // nine of those and the one that gets forgotten is always the one a bug report
        // turns out to hinge on.
        this.httpClient = httpClient.newBuilder()
            .addInterceptor(chain -> chain.proceed(
                chain.request().newBuilder()
                    .header(VERSION_HEADER, PluginVersion.VERSION)
                    .build()))
            .build();
        this.gson = gson;
    }

    public void setAuthToken(String token) {
        this.authToken = token != null ? token : "";
    }

    /**
     * Whether a usable token is configured. The server trims the bearer value before
     * looking it up, so a whitespace-only token is rejected there exactly as an empty
     * one is; treating both as absent here keeps us from firing a request that cannot
     * succeed. A fresh install has no token until the player pastes one, and the
     * timer-driven reporters would otherwise call on regardless.
     */
    private boolean hasAuthToken() {
        return authToken != null && !authToken.trim().isEmpty();
    }

    /**
     * Submit a drop proof to The Birdhouse.
     */
    public CompletableFuture<ProofResult> submitProof(ProofPayload payload, byte[] screenshot) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                MultipartBody.Builder builder = new MultipartBody.Builder()
                    .setType(MultipartBody.FORM)
                    .addFormDataPart("payload", gson.toJson(payload));

                if (screenshot != null && screenshot.length > 0) {
                    builder.addFormDataPart("screenshot", "proof.jpg",
                        RequestBody.create(IMAGE_TYPE, screenshot));
                }

                Request request = new Request.Builder()
                    .url(BASE_URL + "/submit-proof")
                    .header("Authorization", "Bearer " + authToken)
                    .post(builder.build())
                    .build();

                try (Response response = httpClient.newCall(request).execute()) {
                    String body = response.body() != null ? response.body().string() : "";
                    ProofResult result = interpretProofResponse(response.code(), body);
                    if (result.isOk()) {
                        log.info("Proof submitted successfully for tile: {}", payload.getTileName());
                    } else {
                        log.warn("Proof submission failed for tile {}: {} ({})",
                            payload.getTileName(), result.getMessage(), response.code());
                    }
                    return result;
                }
            } catch (IOException e) {
                log.error("Failed to submit proof", e);
                return ProofResult.rejected("Couldn't reach The Birdhouse");
            }
        });
    }

    /**
     * A refused proof still comes back as HTTP 200 with {@code success:false} and a
     * reason, because the request itself was well-formed — the drop just didn't qualify.
     * Treating any 2xx as acceptance would tell a player their manual submission landed
     * when the server actually threw it away.
     */
    ProofResult interpretProofResponse(int code, String body) {
        JsonObject json = null;
        try {
            if (body != null && !body.isEmpty()) {
                json = gson.fromJson(body, JsonObject.class);
            }
        } catch (RuntimeException e) {
            log.debug("Unparseable submit-proof body: {}", e.getMessage());
        }

        String reason = null;
        if (json != null) {
            if (json.has("reason")) {
                reason = json.get("reason").getAsString();
            } else if (json.has("error")) {
                reason = json.get("error").getAsString();
            } else if (json.has("message")) {
                reason = json.get("message").getAsString();
            }
        }

        if (code < 200 || code >= 300) {
            return ProofResult.rejected(reason != null ? reason : "Server returned " + code);
        }
        if (json != null && json.has("duplicate") && json.get("duplicate").getAsBoolean()) {
            return ProofResult.duplicate(reason != null ? reason : "Already submitted");
        }
        if (json != null && json.has("success") && !json.get("success").getAsBoolean()) {
            return ProofResult.rejected(reason != null ? reason : "The server rejected this proof");
        }
        int kills = 0;
        if (json != null && json.has("kills")) {
            try {
                kills = json.get("kills").getAsInt();
            } catch (RuntimeException e) {
                // An older or stranger server; the tile just keeps screenshotting.
                kills = 0;
            }
        }
        return ProofResult.accepted(kills);
    }

    /**
     * Fetch the active board tiles for a room so we can match drops locally.
     *
     * Tries the dedicated cache host first (cheap, always-on) and falls back to the
     * primary backend only when the cache host itself is unhealthy, so a cache-host
     * outage never breaks board loading.
     *
     * A 4xx is NOT a reason to fall back: both hosts read the same database, so an
     * unknown room code or a non-member token gets the identical answer from either
     * one. Retrying would just double every poll, forever, for anyone sitting on a
     * stale room code.
     */
    public CompletableFuture<BoardData> fetchBoard(String roomCode) {
        return CompletableFuture.supplyAsync(() -> {
            BoardResult cached = requestBoard(BOARD_BASE_URL, roomCode);
            if (cached.board != null && trustCachedBoard(cached.board)) {
                return cached.board;
            }
            if (cached.board != null || cached.retryable) {
                log.debug("Board cache host unavailable or stale for {}, falling back to primary backend", roomCode);
                BoardData primary = requestBoard(BASE_URL, roomCode).board;
                if (primary != null) {
                    return primary;
                }
                return cached.board;
            }
            return null;
        });
    }

    /**
     * An empty Impostor board after the deal is usually a cache host that does not
     * know the current objective pool — not "you have nothing to do". Ask the
     * primary backend instead so Catacombs tasks (and anything else added later)
     * still reach the plugin.
     */
    static boolean trustCachedBoard(BoardData board) {
        if (board == null) {
            return false;
        }
        if (!"impostor".equals(board.getGameType())) {
            return true;
        }
        if (board.getTiles() != null && !board.getTiles().isEmpty()) {
            String phase = board.getPhase();
            // A live round with no role means the cache host is an older build.
            // Fall through to the primary so Eliminate can still appear.
            if ("round".equals(phase) && (board.getRole() == null || board.getRole().isEmpty())) {
                return false;
            }
            return true;
        }
        String phase = board.getPhase();
        return "done".equals(phase) || "reveal".equals(phase);
    }

    /**
     * Outcome of one board request: the parsed board when it succeeded, plus whether
     * a different host is worth trying (host unreachable / 5xx) versus the response
     * being an authoritative answer we'd only receive again (4xx).
     */
    private static final class BoardResult {
        private final BoardData board;
        private final boolean retryable;

        private BoardResult(BoardData board, boolean retryable) {
            this.board = board;
            this.retryable = retryable;
        }
    }

    /**
     * Perform a single GET /board/{roomCode} against the given base URL.
     */
    private BoardResult requestBoard(String base, String roomCode) {
        try {
            Request request = new Request.Builder()
                .url(base + "/board/" + roomCode)
                .header("Authorization", "Bearer " + authToken)
                .get()
                .build();

            try (Response response = httpClient.newCall(request).execute()) {
                if (response.isSuccessful() && response.body() != null) {
                    BoardData parsed = gson.fromJson(response.body().string(), BoardData.class);
                    // A 2xx we can't parse means this host is misbehaving, not that the
                    // room is bad, so the caller may still try elsewhere.
                    return new BoardResult(parsed, parsed == null);
                }
                int code = response.code();
                return new BoardResult(null, code >= 500 || code == 429 || code == 408);
            }
        } catch (IOException e) {
            log.debug("Board fetch failed from {}: {}", base, e.getMessage());
            return new BoardResult(null, true);
        }
    }

    /**
     * Fetch the caller's own team chat thread.
     *
     * Cache host first, same as the board and for the same reason: the cache serves
     * this from a live listener, so polling it costs no database reads and a short
     * interval is affordable. A 4xx is again not a reason to fall back, since both
     * hosts read the same room roster and would answer identically.
     */
    public CompletableFuture<ChatData> fetchChat(String roomCode) {
        return CompletableFuture.supplyAsync(() -> {
            ChatResult cached = requestChat(BOARD_BASE_URL, roomCode);
            if (cached.chat != null) {
                return cached.chat;
            }
            if (!cached.retryable) {
                return null;
            }
            log.debug("Chat cache host unavailable for {}, falling back to primary backend", roomCode);
            return requestChat(BASE_URL, roomCode).chat;
        });
    }

    /** Outcome of one chat request; see BoardResult for why retryable is tracked. */
    private static final class ChatResult {
        private final ChatData chat;
        private final boolean retryable;

        private ChatResult(ChatData chat, boolean retryable) {
            this.chat = chat;
            this.retryable = retryable;
        }
    }

    private ChatResult requestChat(String base, String roomCode) {
        try {
            Request request = new Request.Builder()
                .url(base + "/chat/" + roomCode)
                .header("Authorization", "Bearer " + authToken)
                .get()
                .build();

            try (Response response = httpClient.newCall(request).execute()) {
                String body = response.body() != null ? response.body().string() : "";
                if (response.isSuccessful()) {
                    ChatData parsed = gson.fromJson(body, ChatData.class);
                    return new ChatResult(parsed, parsed == null);
                }
                int code = response.code();
                if (code >= 500 || code == 429 || code == 408) {
                    return new ChatResult(null, true);
                }
                // A 404 that did not come from our own application is a proxy declining to
                // route, not "no such room", and those two are otherwise indistinguishable
                // from here. This is how chat failed on release: the reverse proxy in front
                // of the cache host allowed /board and /healthz only, and answered /chat
                // with a plain-text 404 that looked authoritative enough to stop the
                // fallback. Trying the primary backend once costs a request; treating it as
                // final disables the feature outright.
                if (code == 404 && !isApiError(body)) {
                    return new ChatResult(null, true);
                }
                return new ChatResult(null, false);
            }
        } catch (IOException e) {
            log.debug("Chat fetch failed from {}: {}", base, e.getMessage());
            return new ChatResult(null, true);
        }
    }

    /**
     * Fetch the caller's own team roster with online status attached.
     *
     * Same cache-first shape as chat, including the 404 rule: the cache host answers
     * this from live listeners on tiny per-player nodes, and a 404 that isn't one of our
     * own JSON errors means the edge declined to route rather than that the room is
     * gone. That distinction is the whole reason chat shipped dead.
     */
    public CompletableFuture<PresenceData> fetchPresence(String roomCode) {
        return CompletableFuture.supplyAsync(() -> {
            PresenceResult cached = requestPresence(BOARD_BASE_URL, roomCode);
            if (cached.presence != null) {
                return cached.presence;
            }
            if (!cached.retryable) {
                return null;
            }
            log.debug("Presence cache host unavailable for {}, falling back to primary backend", roomCode);
            return requestPresence(BASE_URL, roomCode).presence;
        });
    }

    /** Outcome of one presence request; see BoardResult for why retryable is tracked. */
    private static final class PresenceResult {
        private final PresenceData presence;
        private final boolean retryable;

        private PresenceResult(PresenceData presence, boolean retryable) {
            this.presence = presence;
            this.retryable = retryable;
        }
    }

    private PresenceResult requestPresence(String base, String roomCode) {
        try {
            Request request = new Request.Builder()
                .url(base + "/presence/" + roomCode)
                .header("Authorization", "Bearer " + authToken)
                .get()
                .build();

            try (Response response = httpClient.newCall(request).execute()) {
                String body = response.body() != null ? response.body().string() : "";
                if (response.isSuccessful()) {
                    PresenceData parsed = gson.fromJson(body, PresenceData.class);
                    return new PresenceResult(parsed, parsed == null);
                }
                int code = response.code();
                if (code >= 500 || code == 429 || code == 408) {
                    return new PresenceResult(null, true);
                }
                if (code == 404 && !isApiError(body)) {
                    return new PresenceResult(null, true);
                }
                return new PresenceResult(null, false);
            }
        } catch (IOException e) {
            log.debug("Presence fetch failed from {}: {}", base, e.getMessage());
            return new PresenceResult(null, true);
        }
    }

    /** Whether a body is one of our own JSON errors rather than a proxy's error page. */
    private boolean isApiError(String body) {
        if (body == null || body.isEmpty()) {
            return false;
        }
        try {
            JsonObject json = gson.fromJson(body, JsonObject.class);
            return json != null && json.has("error");
        } catch (RuntimeException e) {
            return false;
        }
    }

    /**
     * Send one message to the caller's own team thread.
     *
     * Always the primary backend: the cache host is read-only by design, which is what
     * keeps it unable to affect game state.
     *
     * Resolves to null on success, or a short message suitable for showing the player.
     * The server's own wording is preferred where it gave any, since it is the side
     * that knows whether this was too long, too fast, or the wrong room.
     */
    public CompletableFuture<String> sendChat(String roomCode, String text) {
        return CompletableFuture.supplyAsync(() -> {
            if (!hasAuthToken()) {
                return "No auth token";
            }
            try {
                JsonObject body = new JsonObject();
                body.addProperty("text", text);

                Request request = new Request.Builder()
                    .url(BASE_URL + "/chat/" + roomCode)
                    .header("Authorization", "Bearer " + authToken)
                    .post(RequestBody.create(JSON_TYPE, gson.toJson(body)))
                    .build();

                try (Response response = httpClient.newCall(request).execute()) {
                    if (response.isSuccessful()) {
                        return null;
                    }
                    String reason = null;
                    if (response.body() != null) {
                        try {
                            JsonObject json = gson.fromJson(response.body().string(), JsonObject.class);
                            if (json != null && json.has("error")) {
                                reason = json.get("error").getAsString();
                            }
                        } catch (RuntimeException e) {
                            log.debug("Unparseable chat error body: {}", e.getMessage());
                        }
                    }
                    return reason != null ? reason : "Server returned " + response.code();
                }
            } catch (IOException e) {
                log.debug("Chat send failed: {}", e.getMessage());
                return "Could not reach the server";
            }
        });
    }

    /**
     * Report a session event (login/logout/heartbeat).
     *
     * Still fire-and-forget — failures are swallowed and the next heartbeat re-sends —
     * but the future is returned so a caller can wait for the write to land. Team status
     * needs that: it reads presence back from the server, so refreshing it before our own
     * login has been reported just re-reads the state we are trying to change.
     */
    public CompletableFuture<Void> reportSession(SessionEvent event) {
        if (!hasAuthToken()) {
            return CompletableFuture.completedFuture(null);
        }
        return CompletableFuture.runAsync(() -> {
            try {
                Request request = new Request.Builder()
                    .url(BASE_URL + "/session")
                    .header("Authorization", "Bearer " + authToken)
                    .post(RequestBody.create(JSON_TYPE, gson.toJson(event)))
                    .build();

                try (Response response = httpClient.newCall(request).execute()) {
                    if (!response.isSuccessful()) {
                        log.debug("Session report failed: {}", response.code());
                    }
                }
            } catch (IOException e) {
                log.debug("Failed to report session", e);
            }
        });
    }

    /**
     * Report a batched activity delta (active time, NPC kills, total loot GP) to the
     * /loot endpoint. Fire-and-forget: never blocks the game thread and swallows
     * failures so a hiccup can't disrupt gameplay (the next flush re-sends).
     */
    public void reportActivity(ActivityPayload payload) {
        if (!hasAuthToken()) {
            return;
        }
        CompletableFuture.runAsync(() -> {
            try {
                Request request = new Request.Builder()
                    .url(BASE_URL + "/loot")
                    .header("Authorization", "Bearer " + authToken)
                    .post(RequestBody.create(JSON_TYPE, gson.toJson(payload)))
                    .build();

                try (Response response = httpClient.newCall(request).execute()) {
                    if (!response.isSuccessful()) {
                        log.debug("Activity report failed: {}", response.code());
                    }
                }
            } catch (IOException e) {
                log.debug("Failed to report activity", e);
            }
        });
    }

    /**
     * Report an impling caught into a jar (Clue Trail).
     *
     * Sent as it happens rather than batched with the activity flush: the jar is usually
     * opened within seconds, and the clue it yields is only credited if the catch is
     * already on record.
     */
    public void reportImplingCatch(String roomCode, String impling, int count) {
        if (!hasAuthToken() || impling == null || impling.isEmpty()) {
            return;
        }
        CompletableFuture.runAsync(() -> {
            try {
                JsonObject body = new JsonObject();
                if (roomCode != null && !roomCode.isEmpty()) {
                    body.addProperty("roomCode", roomCode);
                }
                body.addProperty("impling", impling);
                body.addProperty("count", Math.max(1, count));

                Request request = new Request.Builder()
                    .url(BASE_URL + "/impling-catch")
                    .header("Authorization", "Bearer " + authToken)
                    .post(RequestBody.create(JSON_TYPE, gson.toJson(body)))
                    .build();

                try (Response response = httpClient.newCall(request).execute()) {
                    if (!response.isSuccessful()) {
                        log.debug("Impling catch report failed: {}", response.code());
                    }
                }
            } catch (IOException e) {
                log.debug("Failed to report impling catch", e);
            }
        });
    }

    /**
     * Report a loot drop, clue completion, or collection-log entry to the clan
     * leaderboard. Fire-and-forget: failures are silently swallowed so they can
     * never disrupt gameplay or the bingo submission path.
     */
    public void reportClanLoot(JsonObject payload) {
        CompletableFuture.runAsync(() -> {
            try {
                Request.Builder rb = new Request.Builder()
                    .url(BASE_URL + "/clan-loot")
                    .post(RequestBody.create(JSON_TYPE, gson.toJson(payload)));
                if (hasAuthToken()) {
                    rb.header("Authorization", "Bearer " + authToken);
                }
                Request request = rb.build();

                try (Response response = httpClient.newCall(request).execute()) {
                    if (!response.isSuccessful()) {
                        log.debug("Clan loot report failed: {}", response.code());
                    }
                }
            } catch (IOException e) {
                log.debug("Failed to report clan loot", e);
            }
        });
    }

    /**
     * Report where the player is standing during a round of The Impostor.
     *
     * Always the primary backend, never the board cache host: that host is read-only by
     * design and its reverse proxy routes four paths, so anything else there comes back as
     * a plain-text 404 from the catch-all. Team chat once shipped dead for precisely that
     * reason, and a position endpoint would fail the same way but silently, since nothing
     * about a missing position looks broken from in game.
     *
     * Resolves to null when the report did not land — a bad token, an unreachable server,
     * anything. The caller treats that as "this sample is gone" and does not retry it: a
     * position is worthless a few seconds later, so there is no queue and no backlog to
     * flush. A refusal, by contrast, resolves normally with {@code stop} set, because that
     * is the server telling us something we need to act on.
     */
    public CompletableFuture<PositionAck> reportPosition(PositionPayload payload) {
        if (!hasAuthToken()) {
            return CompletableFuture.completedFuture(null);
        }
        return CompletableFuture.supplyAsync(() -> {
            try {
                Request request = new Request.Builder()
                    .url(BASE_URL + "/impostor-position")
                    .header("Authorization", "Bearer " + authToken)
                    .post(RequestBody.create(JSON_TYPE, gson.toJson(payload)))
                    .build();

                try (Response response = httpClient.newCall(request).execute()) {
                    String body = response.body() != null ? response.body().string() : "";
                    // A refusal is a 409 carrying a parseable body, and it is the one error
                    // worth reading: it says to stop, and honouring that is what stops a
                    // client ticking into a finished game for the rest of the evening.
                    if (response.isSuccessful() || response.code() == 409) {
                        PositionAck ack = gson.fromJson(body, PositionAck.class);
                        if (ack != null) {
                            return ack;
                        }
                    }
                    // Every other failure is anonymous on purpose. A 401 or a 403 means the
                    // token or the room is wrong, which the player fixes in settings rather
                    // than something this loop can recover from, so it is logged and dropped
                    // rather than retried.
                    log.debug("Position report refused: {}", response.code());
                    return null;
                }
            } catch (IOException e) {
                log.debug("Failed to report position: {}", e.getMessage());
                return null;
            }
        });
    }

    /**
     * Fetch the player's active rooms for auto-detection.
     */
    public CompletableFuture<String> impostorKill(String roomCode, String targetName) {
        JsonObject body = new JsonObject();
        body.addProperty("roomCode", roomCode);
        body.addProperty("targetName", targetName);
        return postImpostorAction("/impostor-kill", body);
    }

    public CompletableFuture<String> impostorReport(String roomCode) {
        JsonObject body = new JsonObject();
        body.addProperty("roomCode", roomCode);
        return postImpostorAction("/impostor-report", body);
    }

    public CompletableFuture<String> impostorSabotage(String roomCode) {
        JsonObject body = new JsonObject();
        body.addProperty("roomCode", roomCode);
        return postImpostorAction("/impostor-sabotage", body);
    }

    public CompletableFuture<String> impostorMeeting(String roomCode) {
        JsonObject body = new JsonObject();
        body.addProperty("roomCode", roomCode);
        return postImpostorAction("/impostor-meeting", body);
    }

    /** Null on success, a player-facing reason on failure. */
    private CompletableFuture<String> postImpostorAction(String path, JsonObject body) {
        if (!hasAuthToken()) {
            return CompletableFuture.completedFuture("Paste your plugin token in settings.");
        }
        return CompletableFuture.supplyAsync(() -> {
            try {
                Request request = new Request.Builder()
                    .url(BASE_URL + path)
                    .header("Authorization", "Bearer " + authToken)
                    .post(RequestBody.create(JSON_TYPE, gson.toJson(body)))
                    .build();
                try (Response response = httpClient.newCall(request).execute()) {
                    if (response.isSuccessful()) {
                        return null;
                    }
                    String raw = response.body() != null ? response.body().string() : "";
                    try {
                        JsonObject parsed = gson.fromJson(raw, JsonObject.class);
                        if (parsed != null && parsed.has("error")) {
                            return parsed.get("error").getAsString();
                        }
                    } catch (RuntimeException ignored) {
                        // Fall through to the generic line.
                    }
                    return "That did not work.";
                }
            } catch (IOException e) {
                log.debug("Impostor action failed: {}", e.getMessage());
                return "Could not reach the server.";
            }
        });
    }

    public CompletableFuture<java.util.List<ActiveRoom>> fetchActiveRooms() {
        return CompletableFuture.supplyAsync(() -> {
            if (!hasAuthToken()) {
                log.warn("[Birdhouse] Cannot fetch active rooms — no auth token configured");
                return java.util.Collections.<ActiveRoom>emptyList();
            }
            try {
                Request request = new Request.Builder()
                    .url(BASE_URL + "/active-rooms")
                    .header("Authorization", "Bearer " + authToken)
                    .get()
                    .build();

                try (Response response = httpClient.newCall(request).execute()) {
                    if (response.isSuccessful() && response.body() != null) {
                        String body = response.body().string();
                        JsonObject obj = gson.fromJson(body, JsonObject.class);
                        if (obj.has("rooms")) {
                            ActiveRoom[] rooms = gson.fromJson(obj.get("rooms"), ActiveRoom[].class);
                            log.info("[Birdhouse] Active rooms response: {} rooms found", rooms.length);
                            return java.util.Arrays.asList(rooms);
                        }
                    } else {
                        String errBody = response.body() != null ? response.body().string() : "(no body)";
                        log.warn("[Birdhouse] Active rooms request failed: {} {} - {}", response.code(), response.message(), errBody);
                    }
                }
            } catch (IOException e) {
                log.error("[Birdhouse] Failed to fetch active rooms", e);
            }
            return java.util.Collections.emptyList();
        });
    }
}

