package com.thebirdhouse.plugin;

import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import javax.inject.Inject;
import java.awt.*;

public class BirdhouseOverlay extends OverlayPanel {

    private final BirdhouseConfig config;
    private final DropMatcher dropMatcher;

    private String lastMatchInfo = null;
    private long lastMatchTime = 0;

    @Inject
    public BirdhouseOverlay(BirdhouseConfig config, DropMatcher dropMatcher) {
        this.config = config;
        this.dropMatcher = dropMatcher;

        setPosition(OverlayPosition.TOP_LEFT);
        setPriority(OverlayPriority.LOW);
    }

    public void setLastMatch(String tileName, String itemName) {
        this.lastMatchInfo = tileName + " (" + itemName + ")";
        this.lastMatchTime = System.currentTimeMillis();
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!config.showOverlay()) return null;

        BoardData board = dropMatcher.getActiveBoard();
        if (board == null || !config.autoSubmitDrops()) {
            return null;
        }

        int total = 0;
        int completed = 0;
        if (board.getTiles() != null) {
            total = board.getTiles().size();
            completed = (int) board.getTiles().stream().filter(BoardTile::isCompleted).count();
        }

        if (total == 0) return null;

        panelComponent.getChildren().add(TitleComponent.builder()
            .text("The Birdhouse")
            .color(new Color(93, 164, 196))
            .build());

        boolean isBattleship = "battleship".equals(board.getGameType());
        BoardData.BattleshipMeta bsMeta = board.getBattleshipMeta();

        if (isBattleship && bsMeta != null && bsMeta.getEnemyShipsTotal() != null && bsMeta.getEnemyShipsTotal() > 0) {
            // For battleship, track the opponent's fleet rather than board tiles.
            int shipTotal = bsMeta.getEnemyShipsTotal();
            int shipAfloat = bsMeta.getEnemyShipsRemaining() != null ? bsMeta.getEnemyShipsRemaining() : shipTotal;
            int shipSunk = shipTotal - shipAfloat;

            panelComponent.getChildren().add(LineComponent.builder()
                .left("Enemy sunk:")
                .right(shipSunk + " / " + shipTotal)
                .rightColor(shipSunk == shipTotal ? Color.GREEN : Color.WHITE)
                .build());

            panelComponent.getChildren().add(LineComponent.builder()
                .left("Afloat:")
                .right(String.valueOf(shipAfloat))
                .rightColor(shipAfloat == 0 ? Color.GREEN : new Color(255, 200, 100))
                .build());
        } else if (isBattleship) {
            panelComponent.getChildren().add(LineComponent.builder()
                .left("Enemy fleet:")
                .right("hidden")
                .rightColor(new Color(150, 150, 180))
                .build());
        } else {
            panelComponent.getChildren().add(LineComponent.builder()
                .left("Tiles:")
                .right(completed + " / " + total)
                .rightColor(completed == total ? Color.GREEN : Color.WHITE)
                .build());

            int remaining = total - completed;
            panelComponent.getChildren().add(LineComponent.builder()
                .left("Remaining:")
                .right(String.valueOf(remaining))
                .rightColor(remaining == 0 ? Color.GREEN : new Color(255, 200, 100))
                .build());
        }

        String roomCode = config.roomCode();
        if (roomCode != null && !roomCode.isEmpty()) {
            panelComponent.getChildren().add(LineComponent.builder()
                .left("Room:")
                .right(roomCode)
                .rightColor(new Color(150, 150, 180))
                .build());
        }

        // Countdown
        Long deadline = board.getDeadline();
        if (deadline != null) {
            long timeLeft = deadline - System.currentTimeMillis();
            if (timeLeft > 0) {
                panelComponent.getChildren().add(LineComponent.builder()
                    .left("Ends in:")
                    .right(formatCountdown(timeLeft))
                    .rightColor(timeLeft < 3600000 ? new Color(255, 100, 100) : new Color(255, 180, 80))
                    .build());
            } else {
                panelComponent.getChildren().add(LineComponent.builder()
                    .left("Status:")
                    .right("Ended")
                    .rightColor(new Color(255, 100, 100))
                    .build());
            }
        }

        // Current date/time for screenshot verification
        String now = new java.text.SimpleDateFormat("MM/dd/yy h:mm a").format(new java.util.Date());
        panelComponent.getChildren().add(LineComponent.builder()
            .left("Time:")
            .right(now)
            .rightColor(new Color(180, 180, 180))
            .build());

        // Show last match for 30 seconds
        if (lastMatchInfo != null && System.currentTimeMillis() - lastMatchTime < 30000) {
            panelComponent.getChildren().add(LineComponent.builder()
                .left("Last match:")
                .right("")
                .build());
            panelComponent.getChildren().add(LineComponent.builder()
                .left("")
                .right(lastMatchInfo)
                .rightColor(Color.GREEN)
                .build());
        }

        return super.render(graphics);
    }

    private String formatCountdown(long millis) {
        long days = millis / (1000 * 60 * 60 * 24);
        long hours = (millis / (1000 * 60 * 60)) % 24;
        long mins = (millis / (1000 * 60)) % 60;
        if (days > 0) {
            return String.format("%dd %dh %dm", days, hours, mins);
        } else if (hours > 0) {
            return String.format("%dh %dm", hours, mins);
        }
        return String.format("%dm", mins);
    }
}

package com.thebirdhouse.plugin;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

import javax.inject.Inject;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

@Slf4j
public class BirdhousePanel extends PluginPanel {

    private static final int PANEL_WIDTH = 225;
    // Poll quickly while a game is live; back off hard when idle or the game has ended
    // so we don't keep hitting the server for dead/stale rooms.
    private static final int POLL_ACTIVE_SECONDS = 60;
    private static final int POLL_IDLE_SECONDS = 300;
    // Chat is polled far faster than the board because a conversation on a 60s delay is
    // not a conversation. It is affordable because the cache host answers it from a live
    // listener, so a poll costs no database read. Bounded either way so a bad config
    // value can't hammer it or make it useless.
    private static final int CHAT_POLL_MIN_SECONDS = 5;
    private static final int CHAT_POLL_MAX_SECONDS = 120;
    // Backed right off when there is nothing to show: no team, chat switched off, or a
    // room that has no thread at all.
    private static final int CHAT_POLL_IDLE_SECONDS = 300;
    private static final int CHAT_PANEL_HEIGHT = 190;
    // Slower than chat and with no knob, but not as slow as it was. The old 60s was
    // argued for on the grounds that a faster poll would return the same answer, since a
    // client only heartbeats every five minutes. That is true of the steady state and
    // wrong about the interesting one: a login or a logout is reported the moment it
    // happens, so the poll interval was the whole of the delay before a teammate
    // appeared or went. Affordable at this rate for the same reason chat is — the cache
    // host answers from a live listener, so a poll costs no database read.
    private static final int PRESENCE_POLL_SECONDS = 20;
    private static final int PRESENCE_POLL_IDLE_SECONDS = 300;
    // Shown by both team views while the client sits at the login screen, in place of a
    // loading message that would otherwise never resolve.
    private static final String WAITING_FOR_LOGIN = "Waiting for you to log in to the game.";

    private final BirdhouseConfig config;
    private final DropMatcher dropMatcher;
    private final BirdhouseApiClient apiClient;
    private final ScreenshotHelper screenshotHelper;
    private final ConfigManager configManager;
    private final Client client;
    private final ClientThread clientThread;
    private final TileIcons tileIcons;
    private final Notifier notifier;
    private final ImpostorSidePanel impostorPanel;

    private final JPanel boardPanel;
    private final JPanel tilesPanel;
    private final JLabel statusLabel;
    private final JLabel progressLabel;
    private final JLabel countdownLabel;
    private final JButton refreshButton;

    private ScheduledExecutorService scheduler;
    private ScheduledFuture<?> autoRefreshTask;
    private ScheduledFuture<?> countdownTask;
    private ScheduledFuture<?> chatTask;
    private Long currentDeadline;

    /**
     * One poller feeds every view of the chat, exactly as the board does, so opening the
     * pop-out window does not double the request rate.
     */
    private final ChatPanel chatPanel;
    /** Chat and status share the space under the board, one tab each. */
    private final JTabbedPane teamTabs;
    private final TeamStatusPanel teamStatusPanel;
    private ScheduledFuture<?> presenceTask;
    private PresenceData lastPresence;
    private int presenceFailures;
    private ChatData lastChat;
    /** Newest message id already seen, so a notification fires once and not on first load. */
    private String lastSeenMessageId;
    private String lastChatTeamId;
    private boolean chatPrimed;
    private int chatFailures;

    /** The pop-out window mirrors whatever the sidebar last rendered, so that is kept here. */
    private BirdhouseBoardWindow boardWindow;
    private BoardData lastBoard;
    private String lastRoomCode;
    private String lastStatus = "Not connected";
    private String lastProgress = "";
    private Color lastStatusColor = ColorScheme.LIGHT_GRAY_COLOR;

    @Inject
    public BirdhousePanel(BirdhouseConfig config, DropMatcher dropMatcher, BirdhouseApiClient apiClient,
                          ScreenshotHelper screenshotHelper, ConfigManager configManager,
                          Client client, ClientThread clientThread, TileIcons tileIcons,
                          Notifier notifier, ImpostorSidePanel impostorPanel) {
        super(false);
        this.config = config;
        this.notifier = notifier;
        this.dropMatcher = dropMatcher;
        this.apiClient = apiClient;
        this.screenshotHelper = screenshotHelper;
        this.configManager = configManager;
        this.client = client;
        this.clientThread = clientThread;
        this.tileIcons = tileIcons;
        this.impostorPanel = impostorPanel;

        setLayout(new BorderLayout());
        setBorder(new EmptyBorder(10, 10, 10, 10));
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        // Header
        JPanel headerPanel = new JPanel(new BorderLayout());
        headerPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JLabel titleLabel = new JLabel("The Birdhouse");
        titleLabel.setForeground(BoardRenderer.COLOR_BRAND);
        titleLabel.setFont(FontManager.getDefaultFont().deriveFont(Font.BOLD, 16f));
        headerPanel.add(titleLabel, BorderLayout.WEST);

        JPanel headerButtons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
        headerButtons.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JButton popOutButton = new JButton("\u2197");
        popOutButton.setToolTipText("Open the board in a resizable window");
        popOutButton.setFocusPainted(false);
        popOutButton.addActionListener(e -> openBoardWindow());
        headerButtons.add(popOutButton);

        refreshButton = new JButton("\u21BB");
        refreshButton.setToolTipText("Refresh board");
        refreshButton.setFocusPainted(false);
        refreshButton.addActionListener(e -> refreshBoard());
        headerButtons.add(refreshButton);

        headerPanel.add(headerButtons, BorderLayout.EAST);

        // Status
        JPanel statusPanel = new JPanel();
        statusPanel.setLayout(new BoxLayout(statusPanel, BoxLayout.Y_AXIS));
        statusPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        statusPanel.setBorder(new EmptyBorder(8, 0, 8, 0));

        statusLabel = new JLabel("Not connected");
        statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        statusLabel.setFont(FontManager.getDefaultFont().deriveFont(12f));
        statusLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        statusPanel.add(statusLabel);

        progressLabel = new JLabel("");
        progressLabel.setForeground(new Color(150, 200, 100));
        progressLabel.setFont(FontManager.getDefaultFont().deriveFont(Font.BOLD, 13f));
        progressLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        statusPanel.add(progressLabel);

        countdownLabel = new JLabel("");
        countdownLabel.setForeground(new Color(255, 180, 80));
        countdownLabel.setFont(FontManager.getDefaultFont().deriveFont(11f));
        countdownLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        statusPanel.add(countdownLabel);

        // Mini board area
        boardPanel = new JPanel();
        boardPanel.setLayout(new BorderLayout());
        boardPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        boardPanel.setBorder(new EmptyBorder(0, 0, 8, 0));

        // Tiles list
        tilesPanel = new JPanel();
        tilesPanel.setLayout(new BoxLayout(tilesPanel, BoxLayout.Y_AXIS));
        tilesPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JScrollPane scrollPane = new JScrollPane(tilesPanel);
        scrollPane.setBackground(ColorScheme.DARK_GRAY_COLOR);
        scrollPane.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
        scrollPane.setBorder(null);
        scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);

        // Main content panel with proper layout
        JPanel mainPanel = new JPanel(new BorderLayout());
        mainPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        mainPanel.add(boardPanel, BorderLayout.NORTH);
        mainPanel.add(scrollPane, BorderLayout.CENTER);

        // Top section
        JPanel topSection = new JPanel();
        topSection.setLayout(new BoxLayout(topSection, BoxLayout.Y_AXIS));
        topSection.setBackground(ColorScheme.DARK_GRAY_COLOR);
        topSection.add(headerPanel);
        topSection.add(statusPanel);
        impostorPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
        topSection.add(impostorPanel);

        // Team chat sits under the board rather than replacing it: the point is to read a
        // reply without leaving whatever you were doing, which includes looking at tiles.
        chatPanel = new ChatPanel(this::sendChat, PANEL_WIDTH - 40);
        // Not `statusPanel`: that name is taken by the header's status block above, and a
        // local of a compatible type would quietly swallow this assignment.
        teamStatusPanel = new TeamStatusPanel(PANEL_WIDTH - 40);

        // Tabs rather than stacking both: at 225px wide there is only room for one of
        // them at a readable height, and they are read at different moments anyway —
        // chat while you are talking, status while you are deciding where to go.
        teamTabs = new JTabbedPane();
        teamTabs.setBorder(new EmptyBorder(8, 0, 0, 0));
        teamTabs.setPreferredSize(new Dimension(PANEL_WIDTH, CHAT_PANEL_HEIGHT));
        syncTeamTabs();

        add(topSection, BorderLayout.NORTH);
        add(mainPanel, BorderLayout.CENTER);
        add(teamTabs, BorderLayout.SOUTH);
    }

    /**
     * Show a tab per enabled feature, and nothing at all when neither is on.
     *
     * Rebuilt wholesale because JTabbedPane has no "hide this tab", and a disabled tab
     * that explains it is disabled would just be settings restated in the panel. The
     * selection is preserved by title so toggling the other feature does not move the
     * player off what they were reading.
     */
    private void syncTeamTabs() {
        String selected = teamTabs.getTabCount() > 0 && teamTabs.getSelectedIndex() >= 0
            ? teamTabs.getTitleAt(teamTabs.getSelectedIndex())
            : null;

        teamTabs.removeAll();
        if (config.enableTeamChat()) {
            teamTabs.addTab("Chat", chatPanel);
        }
        if (config.showTeamStatus()) {
            teamTabs.addTab("Team", teamStatusPanel);
        }

        for (int i = 0; i < teamTabs.getTabCount(); i++) {
            if (teamTabs.getTitleAt(i).equals(selected)) {
                teamTabs.setSelectedIndex(i);
                break;
            }
        }
        teamTabs.setVisible(teamTabs.getTabCount() > 0);
    }

    /** Wired into both chat views; the backend picks the team from the room roster. */
    private void sendChat(String text, java.util.function.Consumer<String> onResult) {
        String roomCode = resolveRoomCode();
        if (roomCode == null) {
            onResult.accept("No active room");
            return;
        }
        apiClient.sendChat(roomCode, text).thenAccept(error -> {
            onResult.accept(error);
            // Pull straight away on success so your own message appears immediately
            // rather than after the next scheduled poll.
            if (error == null) {
                SwingUtilities.invokeLater(this::refreshChat);
            }
        });
    }

    public void startAutoRefresh() {
        if (scheduler == null || scheduler.isShutdown()) {
            scheduler = Executors.newSingleThreadScheduledExecutor();
        }
        stopAutoRefresh();
        scheduleNextRefresh(POLL_ACTIVE_SECONDS);
        scheduleNextChatRefresh(0);
        scheduleNextPresenceRefresh(0);
        if (config.openBoardWindowOnStart()) {
            SwingUtilities.invokeLater(this::openBoardWindow);
        }
    }

    private int chatPollSeconds() {
        return Math.max(CHAT_POLL_MIN_SECONDS, Math.min(CHAT_POLL_MAX_SECONDS, config.teamChatPollSeconds()));
    }

    private void scheduleNextChatRefresh(int seconds) {
        if (scheduler == null || scheduler.isShutdown()) return;
        if (chatTask != null) {
            chatTask.cancel(false);
        }
        chatTask = scheduler.schedule(
            () -> SwingUtilities.invokeLater(this::refreshChat),
            seconds, TimeUnit.SECONDS
        );
    }

    /** Applies a config change to the chat views without waiting for the next poll. */
    public void onChatConfigChanged() {
        SwingUtilities.invokeLater(() -> {
            boolean enabled = config.enableTeamChat();
            syncTeamTabs();
            if (boardWindow != null && boardWindow.isDisplayable()) {
                boardWindow.syncTeamTabs();
            }
            revalidate();
            repaint();
            if (enabled) {
                // Re-priming means switching the feature on does not immediately fire a
                // notification for every message already sitting in the thread.
                chatPrimed = false;
                scheduleNextChatRefresh(0);
            }
        });
    }

    // Self-rescheduling poll: each refresh decides how long to wait before the next one
    // based on whether the game is still live.
    private void scheduleNextRefresh(int seconds) {
        if (scheduler == null || scheduler.isShutdown()) return;
        if (autoRefreshTask != null) {
            autoRefreshTask.cancel(false);
        }
        autoRefreshTask = scheduler.schedule(
            () -> SwingUtilities.invokeLater(this::refreshBoard),
            seconds, TimeUnit.SECONDS
        );
    }

    public void stopAutoRefresh() {
        if (autoRefreshTask != null) {
            autoRefreshTask.cancel(false);
            autoRefreshTask = null;
        }
        if (countdownTask != null) {
            countdownTask.cancel(false);
            countdownTask = null;
        }
        if (chatTask != null) {
            chatTask.cancel(false);
            chatTask = null;
        }
        if (presenceTask != null) {
            presenceTask.cancel(false);
            presenceTask = null;
        }
    }

    public void shutdown() {
        stopAutoRefresh();
        if (scheduler != null) {
            scheduler.shutdownNow();
            scheduler = null;
        }
        tileIcons.clear();
        impostorPanel.stop();
        SwingUtilities.invokeLater(() -> {
            if (boardWindow != null) {
                boardWindow.dispose();
                boardWindow = null;
            }
        });
    }

    private String activeRoomCode;

    public void setActiveRoomCode(String code) {
        this.activeRoomCode = code;
    }

    /** Opens (or re-focuses) the resizable board window and hands it the current board. */
    public void openBoardWindow() {
        if (boardWindow == null || !boardWindow.isDisplayable()) {
            boardWindow = new BirdhouseBoardWindow(apiClient, screenshotHelper, config, configManager,
                client, clientThread, tileIcons, this::refreshBoard, this::sendChat);
        }
        boardWindow.syncTeamTabs();
        boardWindow.setVisible(true);
        boardWindow.toFront();
        pushToWindow();
    }

    private void pushToWindow() {
        if (boardWindow == null || !boardWindow.isDisplayable()) {
            return;
        }
        if (lastBoard != null) {
            boardWindow.updateBoard(lastBoard, lastRoomCode, lastStatus, lastProgress);
        } else {
            boardWindow.showStatus(lastStatus, lastStatusColor);
        }
        pushChatToWindow();
        pushPresenceToWindow();
    }

    /** Shows a single status line with no board, for the states where there is nothing to draw. */
    private void showIdleState(String message, Color color) {
        lastBoard = null;
        lastStatus = message;
        lastProgress = "";
        lastStatusColor = color;
        impostorPanel.onBoard(null);

        statusLabel.setText(message);
        statusLabel.setForeground(color);
        progressLabel.setText("");
        countdownLabel.setText("");
        boardPanel.removeAll();
        tilesPanel.removeAll();
        boardPanel.revalidate();
        tilesPanel.revalidate();
        pushToWindow();
    }

    /** The room being tracked: the manually entered code first, then the auto-detected one. */
    private String resolveRoomCode() {
        String roomCode = config.roomCode();
        if (roomCode != null) {
            roomCode = roomCode.trim();
        }
        if ((roomCode == null || roomCode.isEmpty()) && activeRoomCode != null && !activeRoomCode.isEmpty()) {
            roomCode = activeRoomCode;
        }
        return roomCode == null || roomCode.isEmpty() ? null : roomCode;
    }

    /**
     * Poll the caller's team thread.
     *
     * Self-rescheduling like the board poll, and quiet about failures: chat dropping out
     * for one cycle is not worth an error in the panel when the next attempt is seconds
     * away, and the status line is needed for send feedback.
     */
    public void refreshChat() {
        if (!config.enableTeamChat()) {
            scheduleNextChatRefresh(CHAT_POLL_IDLE_SECONDS);
            return;
        }

        if (!loggedIn()) {
            // Whatever thread is already drawn stays put: logging out is not a reason to
            // take the conversation away from someone still reading it. An empty panel has
            // nothing worth keeping though, and sitting on "Loading" with no end in sight
            // reads as broken rather than waiting.
            if (lastChat == null) {
                chatPanel.setUnavailable(WAITING_FOR_LOGIN);
                if (boardWindow != null && boardWindow.isDisplayable()) {
                    boardWindow.showChatNote(WAITING_FOR_LOGIN);
                }
            }
            scheduleNextChatRefresh(CHAT_POLL_IDLE_SECONDS);
            return;
        }

        String token = config.authToken();
        String roomCode = resolveRoomCode();
        if (token == null || token.trim().isEmpty() || roomCode == null) {
            chatPanel.setUnavailable("Set your auth token and join a room to use team chat.");
            pushChatToWindow();
            scheduleNextChatRefresh(CHAT_POLL_IDLE_SECONDS);
            return;
        }

        apiClient.fetchChat(roomCode).thenAccept(chat -> SwingUtilities.invokeLater(() -> {
            if (chat == null) {
                chatFailures++;
                // One dropped poll is not worth alarming anyone when the next is seconds
                // away, but a persistent failure must not keep looking like a slow load.
                if (chatFailures >= 3) {
                    chatPanel.showProblem("Chat unavailable \u2014 still trying");
                }
                scheduleNextChatRefresh(chatPollSeconds());
                return;
            }
            chatFailures = 0;

            if (chat.getTeamId() == null) {
                chatPanel.setUnavailable("This room has no team chat.");
                lastChat = null;
                pushChatToWindow();
                scheduleNextChatRefresh(CHAT_POLL_IDLE_SECONDS);
                return;
            }

            chatPanel.setSendEnabled(true);
            applyChat(chat);
            scheduleNextChatRefresh(chatPollSeconds());
        }));
    }

    /** Applies a config change to the status views without waiting for the next poll. */
    public void onTeamStatusConfigChanged() {
        SwingUtilities.invokeLater(() -> {
            syncTeamTabs();
            if (boardWindow != null && boardWindow.isDisplayable()) {
                boardWindow.syncTeamTabs();
            }
            revalidate();
            repaint();
            if (config.showTeamStatus()) {
                scheduleNextPresenceRefresh(0);
            }
        });
    }

    private void scheduleNextPresenceRefresh(int seconds) {
        if (scheduler == null || scheduler.isShutdown()) return;
        if (presenceTask != null) {
            presenceTask.cancel(false);
        }
        presenceTask = scheduler.schedule(
            () -> SwingUtilities.invokeLater(this::refreshPresence),
            seconds, TimeUnit.SECONDS
        );
    }

    /**
     * Poll the caller's team roster.
     *
     * Same self-rescheduling shape as the chat poll. Unlike chat there is no send path,
     * so a failure here has nowhere else to surface and the panel says so directly
     * rather than sitting on the loading placeholder.
     */
    public void refreshPresence() {
        if (!config.showTeamStatus()) {
            scheduleNextPresenceRefresh(PRESENCE_POLL_IDLE_SECONDS);
            return;
        }

        // Nothing to report while logged out, and the server would not report us as
        // online either, so this is the one place where backing off loses nothing at all.
        if (!loggedIn()) {
            if (lastPresence == null) {
                teamStatusPanel.showNote(WAITING_FOR_LOGIN, null);
                if (boardWindow != null && boardWindow.isDisplayable()) {
                    boardWindow.showPresenceNote(WAITING_FOR_LOGIN);
                }
            }
            scheduleNextPresenceRefresh(PRESENCE_POLL_IDLE_SECONDS);
            return;
        }

        String token = config.authToken();
        String roomCode = resolveRoomCode();
        if (token == null || token.trim().isEmpty() || roomCode == null) {
            teamStatusPanel.showNote("Set your auth token and join a room to see your team.", null);
            lastPresence = null;
            pushPresenceToWindow();
            scheduleNextPresenceRefresh(PRESENCE_POLL_IDLE_SECONDS);
            return;
        }

        apiClient.fetchPresence(roomCode).thenAccept(presence -> SwingUtilities.invokeLater(() -> {
            if (presence == null) {
                presenceFailures++;
                if (presenceFailures >= 3) {
                    teamStatusPanel.setPresence(null);
                }
                scheduleNextPresenceRefresh(PRESENCE_POLL_SECONDS);
                return;
            }
            presenceFailures = 0;
            lastPresence = presence;
            teamStatusPanel.setPresence(presence);
            pushPresenceToWindow();

            // A room with no teams will never grow one, so stop asking every minute.
            scheduleNextPresenceRefresh(presence.getTeamId() == null
                ? PRESENCE_POLL_IDLE_SECONDS
                : PRESENCE_POLL_SECONDS);
        }));
    }

    private void pushPresenceToWindow() {
        if (boardWindow == null || !boardWindow.isDisplayable()) {
            return;
        }
        boardWindow.updatePresence(lastPresence);
    }

    private void applyChat(ChatData chat) {
        lastChat = chat;

        boolean teamChanged = lastChatTeamId != null && !lastChatTeamId.equals(chat.getTeamId());
        lastChatTeamId = chat.getTeamId();

        String self = localPlayerName();
        chatPanel.setSelfName(self);
        chatPanel.setThread(chat);
        pushChatToWindow();

        List<ChatMessage> messages = chat.getMessages();
        String newestId = messages == null || messages.isEmpty()
            ? null
            : messages.get(messages.size() - 1).getId();

        // The first successful poll only records where the thread is up to. Without it,
        // logging in would announce the whole backlog as though it had just arrived.
        //
        // A team change re-primes for the same reason: the newest message in your new
        // team's thread is almost certainly not new, it is just the first one you are
        // allowed to see, and announcing it would be wrong whether you switched yourself
        // or an admin moved you.
        if (!chatPrimed || teamChanged) {
            chatPrimed = true;
            lastSeenMessageId = newestId;
            return;
        }

        if (newestId == null || newestId.equals(lastSeenMessageId)) {
            return;
        }
        lastSeenMessageId = newestId;

        ChatMessage newest = messages.get(messages.size() - 1);
        boolean mine = self != null && !self.isEmpty()
            && newest.getName() != null && self.equalsIgnoreCase(newest.getName());
        if (!mine && config.notifyOnTeamChat()) {
            notifier.notify(newest.getName() + ": " + summarise(newest));
        }
    }

    /** Notifications are one line, so a long message is cut rather than wrapped. */
    private static String summarise(ChatMessage message) {
        String text = message.getText() != null ? message.getText() : "";
        if (text.isEmpty()) {
            return message.isHasImage() ? "[image]" : "";
        }
        return text.length() <= 80 ? text : text.substring(0, 77) + "\u2026";
    }

    /**
     * Whether the player is actually in game.
     *
     * Both the chat and status polls back off when they are not, because a client parked
     * at the login screen has nothing to say and nobody to say it to — and the poll
     * otherwise carried on every ten seconds all night. Backed off rather than stopped,
     * with an immediate refresh on login, so nothing actually waits on the idle interval.
     */
    private boolean loggedIn() {
        try {
            return client.getGameState() == GameState.LOGGED_IN;
        } catch (RuntimeException e) {
            // Same reasoning as localPlayerName: never let a client read throw into a poll.
            return false;
        }
    }

    /** Called on login so the backed-off pollers pick up straight away. */
    public void onLoggedIn() {
        SwingUtilities.invokeLater(() -> {
            scheduleNextChatRefresh(0);
            scheduleNextPresenceRefresh(0);
        });
    }

    /**
     * Re-read the team roster now, because something we did has changed what it will say.
     *
     * Called once our own session write has landed. The refresh on the login event above
     * cannot cover this: it runs before the write, which waits for the client to be able
     * to name the local player and then goes out asynchronously, so it read us as still
     * offline and left us looking that way until the next poll.
     */
    public void onSessionReported() {
        SwingUtilities.invokeLater(() -> {
            if (config.showTeamStatus()) {
                scheduleNextPresenceRefresh(0);
            }
        });
    }

    private String localPlayerName() {
        try {
            return client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : null;
        } catch (RuntimeException e) {
            // Reading the player off the Swing thread is tolerated everywhere else in this
            // panel, but it is never worth an exception escaping into the poll loop.
            return null;
        }
    }

    private void pushChatToWindow() {
        if (boardWindow == null || !boardWindow.isDisplayable()) {
            return;
        }
        if (lastChat != null) {
            boardWindow.updateChat(lastChat, localPlayerName());
        }
    }

    public void refreshBoard() {
        // Tested ahead of the room code, because a token is what makes any of this work:
        // without one the server rejects every request, so a player who has pasted a room
        // code but not a token would poll indefinitely and only ever see "Failed to load
        // board". This panel is also the sole place that setup gap is visible to them.
        String token = config.authToken();
        if (token == null || token.trim().isEmpty()) {
            showIdleState("\u26A0 No auth token — paste yours in settings", new Color(255, 120, 120));
            scheduleNextRefresh(POLL_IDLE_SECONDS);
            return;
        }

        String roomCode = resolveRoomCode();

        if (roomCode == null) {
            showIdleState("\u26A0 No active room found", ColorScheme.LIGHT_GRAY_COLOR);
            // No room to track — idle until login/config change or a manual refresh.
            scheduleNextRefresh(POLL_IDLE_SECONDS);
            return;
        }

        final String fetchCode = roomCode;
        statusLabel.setText("Loading...");
        statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        refreshButton.setEnabled(false);

        apiClient.fetchBoard(fetchCode).thenAccept(board -> {
            SwingUtilities.invokeLater(() -> {
                refreshButton.setEnabled(true);
                if (board == null) {
                    statusLabel.setText("Failed to load board");
                    progressLabel.setText("");
                    countdownLabel.setText("");
                    // Transient failure — retry on the normal cadence.
                    scheduleNextRefresh(POLL_ACTIVE_SECONDS);
                    return;
                }
                dropMatcher.setActiveRoomCode(fetchCode);
                dropMatcher.updateBoard(board);
                updatePanel(board, fetchCode);
                // Back off once the game is no longer live (older servers omit the flag → treat as live).
                boolean live = board.getActive() == null || board.getActive();
                scheduleNextRefresh(live ? POLL_ACTIVE_SECONDS : POLL_IDLE_SECONDS);
            });
        });
    }

    private void updatePanel(BoardData board, String roomCode) {
        List<BoardTile> tiles = board.getTiles();
        impostorPanel.onBoard(board);
        if ((tiles == null || tiles.isEmpty()) && !"impostor".equals(board.getGameType())) {
            showIdleState("Room: " + roomCode + " (no tiles)", ColorScheme.LIGHT_GRAY_COLOR);
            return;
        }
        if (tiles == null) {
            tiles = java.util.Collections.emptyList();
        }

        String gameType = board.getGameType();
        int total = tiles.size();
        int completed = (int) tiles.stream().filter(BoardTile::isCompleted).count();
        int remaining = total - completed;

        boolean ended = Boolean.FALSE.equals(board.getActive());
        lastStatus = "Room: " + roomCode + " \u2022 " + BoardRenderer.formatGameType(gameType) + (ended ? " (ended)" : "");
        lastStatusColor = ColorScheme.LIGHT_GRAY_COLOR;
        statusLabel.setText(lastStatus);

        // For battleship, the meaningful progress is how many of the opponent's ships are
        // still afloat — not how many board tiles are unmarked.
        // The Delve has no checklist to complete — supplies are the currency and sigils are
        // the objective, so a tile count says nothing about how the run is going.
        if ("delve".equals(gameType)) {
            BoardData.DelveMeta dm = board.getDelveMeta();
            if (dm != null) {
                String sigils = dm.getSigilsNeeded() > 0
                    ? "  \u2022  " + dm.getSigilsHeld() + "/" + dm.getSigilsNeeded() + " sigils"
                    : "";
                lastProgress = dm.getSupplies() + " supplies" + sigils;
            } else {
                lastProgress = "Waiting for the Delve to be set up";
            }
        } else if ("battleship".equals(gameType)) {
            BoardData.BattleshipMeta meta = board.getBattleshipMeta();
            if (meta != null && meta.getEnemyShipsTotal() != null && meta.getEnemyShipsTotal() > 0) {
                int shipTotal = meta.getEnemyShipsTotal();
                int shipRemaining = meta.getEnemyShipsRemaining() != null ? meta.getEnemyShipsRemaining() : shipTotal;
                int shipSunk = shipTotal - shipRemaining;
                lastProgress = shipSunk + " / " + shipTotal + " enemy ships sunk (" + shipRemaining + " afloat)";
            } else {
                lastProgress = "Enemy fleet hidden until ships are placed";
            }
        } else if ("impostor".equals(gameType)) {
            lastProgress = ended || tiles.isEmpty()
                ? ""
                : tiles.get(0).getName();
        } else {
            lastProgress = completed + " / " + total + " complete (" + remaining + " remaining)";
        }
        progressLabel.setText(lastProgress);

        // Countdown
        currentDeadline = board.getDeadline();
        updateCountdown();
        startCountdownTimer();

        boardPanel.removeAll();
        tilesPanel.removeAll();
        if (!tiles.isEmpty()) {
            BoardRenderer renderer = new BoardRenderer(PANEL_WIDTH, 0, 18, false);
            renderer.setTileIcons(tileIcons);
            boardPanel.add(renderer.renderBoard(board), BorderLayout.CENTER);
            renderer.renderTileList(board, tilesPanel);
        }
        boardPanel.revalidate();
        boardPanel.repaint();
        tilesPanel.revalidate();
        tilesPanel.repaint();

        lastBoard = board;
        lastRoomCode = roomCode;
        pushToWindow();
    }

    private void startCountdownTimer() {
        if (countdownTask != null) {
            countdownTask.cancel(false);
        }
        if (currentDeadline == null) return;
        if (scheduler == null || scheduler.isShutdown()) {
            scheduler = Executors.newSingleThreadScheduledExecutor();
        }
        countdownTask = scheduler.scheduleAtFixedRate(
            () -> SwingUtilities.invokeLater(this::updateCountdown),
            1, 1, TimeUnit.SECONDS
        );
    }

    private void updateCountdown() {
        if (currentDeadline == null) {
            setCountdown("", countdownLabel.getForeground());
            return;
        }
        long remaining = currentDeadline - System.currentTimeMillis();
        if (remaining <= 0) {
            setCountdown("\u23F0 Event ended!", new Color(255, 100, 100));
            return;
        }
        long days = remaining / (1000 * 60 * 60 * 24);
        long hours = (remaining / (1000 * 60 * 60)) % 24;
        long mins = (remaining / (1000 * 60)) % 60;
        long secs = (remaining / 1000) % 60;

        String timeStr;
        if (days > 0) {
            timeStr = String.format("%dd %dh %dm %ds", days, hours, mins, secs);
        } else if (hours > 0) {
            timeStr = String.format("%dh %dm %ds", hours, mins, secs);
        } else {
            timeStr = String.format("%dm %ds", mins, secs);
        }
        setCountdown("\u23F0 " + timeStr + " remaining",
            remaining < 3600000 ? new Color(255, 100, 100) : new Color(255, 180, 80));
    }

    private void setCountdown(String text, Color color) {
        countdownLabel.setText(text);
        countdownLabel.setForeground(color);
        if (boardWindow != null && boardWindow.isDisplayable()) {
            boardWindow.setCountdown(text, color);
        }
    }
}

package com.thebirdhouse.plugin;

import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.WorldChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import java.awt.image.BufferedImage;

@Slf4j
@PluginDescriptor(
    name = "The Birdhouse",
    description = "Auto-submit drop proofs, track activity, and sync with your Birdhouse games",
    tags = {"bingo", "osrs", "birdhouse", "drops", "proof", "clan"}
)
public class BirdhousePlugin extends Plugin {

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private BirdhouseConfig config;

    @Inject
    private BirdhouseApiClient apiClient;

    @Inject
    private DropMatcher dropMatcher;

    @Inject
    private AchievementTracker achievementTracker;

    @Inject
    private ActivityTracker activityTracker;

    @Inject
    private ClueTracker clueTracker;

    @Inject
    private GatheredTracker gatheredTracker;

    @Inject
    private KillCountTracker killCountTracker;

    @Inject
    private ClanLootReporter clanLootReporter;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private BirdhouseOverlay birdhouseOverlay;

    @Inject
    private ImpostorDeathOverlay impostorDeathOverlay;

    @Inject
    private ImpostorBodyOverlay impostorBodyOverlay;

    @Inject
    private ImpostorStatusOverlay impostorStatusOverlay;

    @Inject
    private ImpostorBlackoutOverlay impostorBlackoutOverlay;

    @Inject
    private ImpostorActions impostorActions;

    @Inject
    private BirdhousePanel birdhousePanel;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private SessionTracker sessionTracker;

    @Inject
    private ImpostorPositionTracker impostorPositionTracker;

    @Inject
    private EventBus eventBus;

    private NavigationButton navButton;

    @Override
    protected void startUp() {
        log.info("The Birdhouse plugin started");

        eventBus.register(dropMatcher);
        eventBus.register(achievementTracker);
        eventBus.register(activityTracker);
        eventBus.register(clueTracker);
        eventBus.register(gatheredTracker);
        eventBus.register(killCountTracker);
        eventBus.register(clanLootReporter);
        eventBus.register(impostorPositionTracker);
        eventBus.register(impostorActions);

        // Registered and started unconditionally, because the toggle can be switched on
        // mid-round and the tracker's own gate is what decides whether anything is sent.
        // Idle it costs one boolean read per game tick and one per second on its scheduler.
        impostorPositionTracker.start();

        String token = config.authToken();
        if (token != null) {
            token = token.trim();
        }
        log.info("[Birdhouse] Auth token configured: {} (length={})",
            token != null && !token.isEmpty() ? token.substring(0, Math.min(8, token.length())) + "..." : "(empty)",
            token != null ? token.length() : 0);
        apiClient.setAuthToken(token);

        overlayManager.add(birdhouseOverlay);
        overlayManager.add(impostorDeathOverlay);
        overlayManager.add(impostorBodyOverlay);
        overlayManager.add(impostorStatusOverlay);
        overlayManager.add(impostorBlackoutOverlay);

        BufferedImage icon;
        try {
            icon = ImageUtil.loadImageResource(getClass(), "/panel_icon.png");
        } catch (Exception e) {
            icon = createFallbackIcon();
        }
        navButton = NavigationButton.builder()
            .tooltip("The Birdhouse")
            .icon(icon)
            .priority(10)
            .panel(birdhousePanel)
            .build();
        clientToolbar.addNavigation(navButton);

        // The tracker owns the write that decides what team status shows, so the panel
        // waits on it rather than on the login event that precedes it.
        sessionTracker.setSessionReportedListener(birdhousePanel::onSessionReported);

        birdhousePanel.startAutoRefresh();

        // Same guard as the login handler, and the same reason: a plugin restarted while
        // the player is already in game gets no LOGGED_IN event to lean on. Status
        // sharing is included because it rides on the session write too, so without it
        // switching the plugin off and on left a sharer looking like they had opted out.
        if ((config.trackActivity() || config.showTeamStatus())
            && client.getGameState() == GameState.LOGGED_IN) {
            startSessionWhenPlayerLoads();
        }

        if (client.getGameState() == GameState.LOGGED_IN) {
            loadBoard();
        }
    }

    @Override
    protected void shutDown() {
        log.info("The Birdhouse plugin stopped");
        eventBus.unregister(dropMatcher);
        eventBus.unregister(achievementTracker);
        eventBus.unregister(activityTracker);
        eventBus.unregister(clueTracker);
        eventBus.unregister(gatheredTracker);
        eventBus.unregister(killCountTracker);
        eventBus.unregister(clanLootReporter);
        eventBus.unregister(impostorPositionTracker);
        eventBus.unregister(impostorActions);
        impostorPositionTracker.stop();
        overlayManager.remove(birdhouseOverlay);
        overlayManager.remove(impostorDeathOverlay);
        overlayManager.remove(impostorBodyOverlay);
        overlayManager.remove(impostorStatusOverlay);
        overlayManager.remove(impostorBlackoutOverlay);
        clientToolbar.removeNavigation(navButton);
        birdhousePanel.stopAutoRefresh();
        birdhousePanel.shutdown();
        sessionTracker.endSession();
        // After endSession, which still wants to report the logout. The tracker outlives
        // the plugin's panel, so it must not be left holding it.
        sessionTracker.setSessionReportedListener(null);
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() == GameState.LOGGED_IN) {
            String token = config.authToken();
            if (token != null) {
                token = token.trim();
            }
            apiClient.setAuthToken(token);
            log.info("[Birdhouse] Login detected, token present: {}", token != null && !token.isEmpty());

            // The inventory diff is meaningless across a login, so start from a clean slate.
            clueTracker.reset();
            gatheredTracker.reset();
            killCountTracker.reset();
            loadBoard();

            // The chat and status polls back off while logged out, so they are nudged
            // here rather than left to wait out the idle interval.
            birdhousePanel.onLoggedIn();

            // Team status is carried by the session write, so it needs a session even
            // for a player who has playtime tracking switched off.
            if (config.trackActivity() || config.showTeamStatus()) {
                startSessionWhenPlayerLoads();
            }
        } else if (event.getGameState() == GameState.LOGIN_SCREEN) {
            sessionTracker.endSession();
            // Game ticks are what keep the sampled position fresh, and they stop here, so
            // the last one has to be dropped rather than left to be resent on the keepalive.
            impostorPositionTracker.clearPosition();
        }
    }

    /**
     * Start a session once the client can say who we are.
     *
     * The local player is not populated at the instant LOGGED_IN fires, so reading a name
     * straight out of the event threw and abandoned the rest of the handler. Everything
     * after it went with it: the board never loaded on login, no session was opened, and
     * the chat and team status polls were never nudged, so both panels sat on "Loading"
     * until their five-minute retry came round.
     *
     * Returning false asks the client thread to try again on the next tick.
     */
    private void startSessionWhenPlayerLoads() {
        clientThread.invokeLater(() -> {
            if (client.getGameState() != GameState.LOGGED_IN) {
                // Logged out again before the player loaded; nothing left to start.
                return true;
            }
            Player me = client.getLocalPlayer();
            if (me == null || me.getName() == null) {
                return false;
            }
            sessionTracker.setWorld(client.getWorld());
            sessionTracker.startSession(me.getName());
            return true;
        });
    }

    /**
     * A hop is the only thing that changes a player's world, so status is reported on
     * the event rather than polled. Read here because this runs on the client thread.
     */
    @Subscribe
    public void onWorldChanged(WorldChanged event) {
        sessionTracker.setWorld(client.getWorld());
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!"birdhouse".equals(event.getGroup())) {
            return;
        }

        if ("authToken".equals(event.getKey()) || "roomCode".equals(event.getKey())) {
            String token = config.authToken();
            if (token != null) {
                token = token.trim();
            }
            apiClient.setAuthToken(token);
            log.info("[Birdhouse] Config changed ({}), token present: {}", event.getKey(), token != null && !token.isEmpty());

            if (client.getGameState() == GameState.LOGGED_IN) {
                loadBoard();
            }
        }

        if ("enableTeamChat".equals(event.getKey())) {
            birdhousePanel.onChatConfigChanged();
        }

        if ("shareImpostorPosition".equals(event.getKey())) {
            // Switching off takes effect on the next tick through the tracker's own gate;
            // this drops what was already sampled so nothing in flight outlives the choice.
            // Switching on clears a stop left over from an earlier round, so the player does
            // not have to wait for the next phase change to start being counted.
            impostorPositionTracker.clearPosition();
        }

        if ("showTeamStatus".equals(event.getKey())) {
            // Sharing has to reach the server before the panel is any use: the read is
            // reciprocal, so a player who just switched it on would otherwise be told
            // they aren't sharing until their next heartbeat.
            if (config.showTeamStatus() && client.getGameState() == GameState.LOGGED_IN
                && client.getLocalPlayer() != null) {
                sessionTracker.setWorld(client.getWorld());
                sessionTracker.startSession(client.getLocalPlayer().getName());
            }
            sessionTracker.onStatusSharingChanged();
            birdhousePanel.onTeamStatusConfigChanged();
        }
    }

    private void loadBoard() {
        String rawCode = config.roomCode();
        final String roomCode = (rawCode != null) ? rawCode.trim() : "";

        if (roomCode.isEmpty()) {
            log.info("[Birdhouse] No manual room code set, attempting auto-detect via active-rooms...");
            apiClient.fetchActiveRooms().thenAccept(rooms -> {
                if (rooms != null && !rooms.isEmpty()) {
                    String autoCode = rooms.get(0).getCode();
                    log.info("[Birdhouse] Auto-detected room: {} (from {} active rooms)", autoCode, rooms.size());
                    birdhousePanel.setActiveRoomCode(autoCode);
                    activityTracker.setActiveRoom(autoCode);
                    dropMatcher.loadActiveBoard(autoCode);
                    apiClient.fetchBoard(autoCode).thenAccept(board -> {
                        if (board != null) {
                            achievementTracker.setActiveBoard(autoCode, board);
                            birdhousePanel.refreshBoard();
                        }
                    });
                } else {
                    log.warn("[Birdhouse] No active rooms found. Check: 1) Auth token is set correctly 2) You've joined a room on the website");
                    birdhousePanel.refreshBoard();
                }
            });
        } else {
            log.info("[Birdhouse] Using manual room code: {}", roomCode);
            birdhousePanel.setActiveRoomCode(roomCode);
            activityTracker.setActiveRoom(roomCode);
            dropMatcher.loadActiveBoard(roomCode);
            apiClient.fetchBoard(roomCode).thenAccept(board -> {
                if (board != null) {
                    achievementTracker.setActiveBoard(roomCode, board);
                    birdhousePanel.refreshBoard();
                }
            });
        }
    }

    private BufferedImage createFallbackIcon() {
        BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
        java.awt.Graphics2D g = img.createGraphics();
        g.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
        g.setColor(new java.awt.Color(93, 164, 196));
        g.fillRoundRect(1, 1, 14, 14, 4, 4);
        g.setColor(java.awt.Color.WHITE);
        g.setFont(new java.awt.Font("SansSerif", java.awt.Font.BOLD, 11));
        g.drawString("B", 4, 13);
        g.dispose();
        return img;
    }

    @Provides
    BirdhouseConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(BirdhouseConfig.class);
    }
}

package com.thebirdhouse.plugin;

import lombok.Data;
import java.util.List;
import java.util.Map;

@Data
public class BoardData {
    private String roomCode;
    private String gameType;
    private List<BoardTile> tiles;
    private int rows;
    private int cols;
    private Integer position;
    private Long deadline;

    // Whether the game is still live. When false (game ended / deadline passed),
    // the panel backs off its polling cadence. Defaults true for older API responses.
    private Boolean active;
    private String status;

    // Whether the event has started/locked. When explicitly false, drops don't count
    // yet — the plugin warns the player to screenshot instead of auto-submitting.
    private Boolean started;

    // The Impostor: which part of the game loop the room is in — lobby, round, meeting,
    // reveal or done. Only "round" wants position reports, and gating on it here is what
    // keeps the plugin from ticking through meetings and votes for the server to discard.
    // Absent on every other game type and on older servers, which reads as "no round".
    private String phase;

    // Own role only. Position acks also carry this; the board poll is the fallback so
    // Eliminate does not vanish if a ping is late or a cache host omitted the ack field.
    private String role;

    // True once this player has been dealt out. The board poll is slower than a
    // position ack but it still has to be able to announce a death if pings stall.
    private Boolean dead;

    // Tile Race: opponent positions
    private List<OpponentPosition> opponents;

    // Territory War: ownership and adjacency info
    private TerritoryMeta territoryMeta;

    // Battleship: attack/defense data
    private BattleshipMeta battleshipMeta;

    // The Delve: spendable supplies, descent progress, and which bosses pay what
    private DelveMeta delveMeta;

    @Data
    public static class OpponentPosition {
        private String name;
        private int position;
    }

    @Data
    public static class TerritoryMeta {
        private Map<String, List<String>> connections;
        private Map<String, TerritoryOwner> owners;
        private Map<String, String> ownerNames;
    }

    @Data
    public static class TerritoryOwner {
        private String owner;
        private boolean ours;
        private int defense;
        private boolean attackable;
    }

    @Data
    public static class BattleshipMeta {
        private Map<String, String> defenseGrid;
        private List<BattleshipShip> ourShips;
        private List<BattleshipShip> sunkEnemyShips;
        // Public enemy fleet summary (name + sunk status, no cell positions).
        private List<BattleshipShip> enemyFleet;
        // Ship counts so the overlay can show how many opponent ships remain afloat.
        private Integer enemyShipsTotal;
        private Integer enemyShipsRemaining;
        private Integer myShipsTotal;
        private Integer myShipsRemaining;
        private String turn;
        private String myTeam;
        private String enemyTeam;
    }

    /**
     * The Delve runs on supplies, which are earned by killing bosses and spent opening
     * rooms. The panel needs the spendable total and the per-boss rates, because "which
     * boss should I kill and what is it worth" is the only in-game decision the mode has.
     */
    @Data
    public static class DelveMeta {
        private int supplies;
        private int fromKills;
        private int bonusEarned;
        private int spent;
        private int sigilsHeld;
        private int sigilsNeeded;
        private int roomsOpened;
        private boolean vaultCleared;
        private List<DelveBoss> bosses;
    }

    @Data
    public static class DelveBoss {
        private String name;
        private String tier;  // easy | mid | hard
        private int rate;     // supplies per kill
        private int kills;    // banked so far for this party
    }

    @Data
    public static class BattleshipShip {
        private String name;
        private int size;
        // Gson delivers JSON arrays-of-arrays as List<List<Number>>, not int[][].
        private List<List<Number>> cells;
        private boolean sunk;
    }
}

package com.thebirdhouse.plugin;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.components.ThinProgressBar;

import javax.swing.*;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.LineBorder;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import java.util.stream.Collectors;

/**
 * Draws a board and its tile list into whatever space the caller has.
 *
 * The sidebar and the pop-out window show the same boards at wildly different scales,
 * so every size decision here derives from the space handed in rather than from the
 * 225px sidebar that used to be the only consumer.
 */
class BoardRenderer {

    static final Color COLOR_COMPLETED = new Color(100, 200, 100);
    static final Color COLOR_CURRENT = new Color(255, 200, 100);
    static final Color COLOR_AVAILABLE = new Color(255, 200, 100);
    static final Color COLOR_LOCKED = new Color(60, 60, 70);
    static final Color COLOR_INCOMPLETE = new Color(120, 120, 140);
    static final Color COLOR_FREE = new Color(93, 164, 196);
    static final Color COLOR_BRAND = new Color(93, 164, 196);
    static final Color COLOR_OPPONENT = new Color(220, 80, 80);
    static final Color COLOR_HIT = new Color(220, 60, 60);
    static final Color COLOR_SUNK = new Color(160, 40, 40);
    static final Color COLOR_MISS = new Color(80, 80, 120);
    static final Color COLOR_ATTACKABLE = new Color(220, 140, 60);
    static final Color COLOR_MUTED = new Color(150, 150, 170);
    /** Tile notes, a touch brighter than muted text so a whole sentence stays readable. */
    static final Color COLOR_NOTE = new Color(178, 178, 192);
    static final Color COLOR_HOT = new Color(240, 120, 60);
    /** Ceiling on a row carrying a wrapped note, so one long note cannot eat the list. */
    private static final int NOTE_ROW_MAX_HEIGHT = 78;
    private static final int TERRITORY_CARD_WIDTH = 190;
    private static final int BOUNTY_CARD_WIDTH = 220;
    private static final int BOUNTY_CARD_HEIGHT = 78;
    /** Beyond this a closesAt is a sentinel for "rotates out", not a real date. */
    private static final long NO_DEADLINE_AFTER_MS = 4_000_000_000_000L;

    private final int availableWidth;
    /** 0 means "as tall as it needs to be" — the sidebar scrolls, the window does not. */
    private final int availableHeight;
    private final int maxCellSize;
    /** Detailed cells carry the tile name and progress; small ones are colour-coded squares. */
    private final boolean detailed;

    /** Height of an in-game item sprite, which is what most tile icons are. */
    private static final int ITEM_SPRITE_HEIGHT = 32;

    private Consumer<BoardTile> tileClickListener;
    private TileIcons tileIcons;

    BoardRenderer(int availableWidth, int availableHeight, int maxCellSize, boolean detailed) {
        this.availableWidth = availableWidth;
        this.availableHeight = availableHeight;
        this.maxCellSize = maxCellSize;
        this.detailed = detailed;
    }

    void setTileClickListener(Consumer<BoardTile> listener) {
        this.tileClickListener = listener;
    }

    void setTileIcons(TileIcons tileIcons) {
        this.tileIcons = tileIcons;
    }

    // ===== BOARD =====

    JPanel renderBoard(BoardData board) {
        String gameType = board.getGameType();
        switch (gameType != null ? gameType : "") {
            case "bingo":
            case "battleship":
                return renderGridBoard(board);
            case "chipdrop":
                return renderChipDropBoard(board);
            case "tilerace":
                return renderTileRaceBoard(board);
            case "territory":
                return renderTerritoryBoard(board);
            case "monopoly":
                return renderMonopolyBoard(board);
            case "delve":
                return renderDelveBoard(board);
            case "bounty":
                return renderBountyBoard(board);
            default:
                return unsupportedNotice(gameType);
        }
    }

    /**
     * Modes without a board renderer yet (Bounty Board, Clue Trail, The Maze) still get a
     * usable tile list, so the board area says so rather than sitting empty.
     */
    private JPanel unsupportedNotice(String gameType) {
        JPanel panel = new JPanel(new BorderLayout());
        panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        if (!detailed) {
            return panel;
        }
        String label = formatGameType(gameType);
        JLabel notice = new JLabel("<html><div style='text-align:center'>No board view for "
            + escapeHtml(label.isEmpty() ? "this game mode" : label)
            + " yet.<br>Your tiles are listed on the right, and the full board is on the website.</div></html>",
            SwingConstants.CENTER);
        notice.setForeground(COLOR_MUTED);
        notice.setBorder(new EmptyBorder(40, 20, 40, 20));
        panel.add(notice, BorderLayout.CENTER);
        return panel;
    }

    private int calculateCellSize(int cols, int rows) {
        if (cols <= 0) return maxCellSize;
        int byWidth = (availableWidth - 28) / cols - 2;
        int size = byWidth;
        if (availableHeight > 0 && rows > 0) {
            size = Math.min(size, (availableHeight - 28) / rows - 2);
        }
        return Math.min(Math.max(8, size), maxCellSize);
    }

    // A 16x16 Delve map is unreadable at panel width and the website already draws it, so
    // this space goes to the numbers a player actually acts on: what the party can spend,
    // and where the supplies came from.
    private JPanel renderDelveBoard(BoardData board) {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);

        BoardData.DelveMeta dm = board.getDelveMeta();
        if (dm == null) return panel;

        JLabel supplies = new JLabel(String.valueOf(dm.getSupplies()));
        supplies.setForeground(COLOR_BRAND);
        supplies.setFont(supplies.getFont().deriveFont(Font.BOLD, fs(26f)));
        supplies.setAlignmentX(Component.CENTER_ALIGNMENT);
        panel.add(supplies);

        JLabel caption = new JLabel("supplies to spend");
        caption.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        caption.setFont(caption.getFont().deriveFont(fs(10f)));
        caption.setAlignmentX(Component.CENTER_ALIGNMENT);
        panel.add(caption);

        panel.add(Box.createVerticalStrut(4));

        JLabel split = new JLabel("\u2694 " + dm.getFromKills()
            + "   \uD83D\uDCE6 " + dm.getBonusEarned()
            + "   \u2212" + dm.getSpent() + " spent");
        split.setForeground(new Color(150, 150, 180));
        split.setFont(split.getFont().deriveFont(fs(10f)));
        split.setAlignmentX(Component.CENTER_ALIGNMENT);
        split.setToolTipText("Earned from kills, plus bonus drops, minus what the party has spent");
        panel.add(split);

        String progress = dm.getRoomsOpened() + " rooms opened";
        if (dm.isVaultCleared()) progress = "\uD83C\uDFC6 Vault cracked \u2022 " + progress;
        JLabel rooms = new JLabel(progress);
        rooms.setForeground(dm.isVaultCleared() ? COLOR_COMPLETED : new Color(150, 150, 180));
        rooms.setFont(rooms.getFont().deriveFont(fs(10f)));
        rooms.setAlignmentX(Component.CENTER_ALIGNMENT);
        panel.add(rooms);

        return panel;
    }

    /**
     * The Bounty Board is a rotating set of live objectives rather than a grid, and the
     * only decision it offers is which one to chase next. That turns on two numbers the
     * other modes don't have: what it pays, and whether anyone has claimed it yet — the
     * first claim takes the full payout and everyone after gets a consolation slice.
     */
    private JPanel renderBountyBoard(BoardData board) {
        List<BoardTile> tiles = board.getTiles();

        if (!detailed) {
            long claimed = tiles.stream().filter(BoardTile::isCompleted).count();
            JPanel summary = new JPanel();
            summary.setLayout(new BoxLayout(summary, BoxLayout.Y_AXIS));
            summary.setBackground(ColorScheme.DARKER_GRAY_COLOR);

            JLabel count = new JLabel(tiles.size() + " live");
            count.setForeground(COLOR_BRAND);
            count.setFont(count.getFont().deriveFont(Font.BOLD, 26f));
            count.setAlignmentX(Component.CENTER_ALIGNMENT);
            summary.add(count);

            JLabel caption = new JLabel(claimed + " claimed by you");
            caption.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            caption.setFont(caption.getFont().deriveFont(10f));
            caption.setAlignmentX(Component.CENTER_ALIGNMENT);
            summary.add(caption);

            return summary;
        }

        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        panel.setBorder(new EmptyBorder(6, 6, 6, 6));

        List<BoardTile> ordered = orderBounties(tiles);
        // FlowLayout keeps each card at its preferred size. GridLayout was stretching
        // six cards to fill the whole window, which is why a 2x3 bounty board looked
        // like six empty boxes with a caption in the corner.
        JPanel grid = new JPanel(new FlowLayout(FlowLayout.LEFT, 8, 8));
        grid.setBackground(ColorScheme.DARK_GRAY_COLOR);
        grid.setAlignmentX(Component.LEFT_ALIGNMENT);

        for (BoardTile tile : ordered) {
            grid.add(bountyCard(tile));
        }

        panel.add(grid);
        return panel;
    }

    /** Unclaimed before claimed, first-claim-still-open before contested, then by payout. */
    private List<BoardTile> orderBounties(List<BoardTile> tiles) {
        List<BoardTile> ordered = new ArrayList<>(tiles);
        ordered.sort((a, b) -> {
            if (a.isCompleted() != b.isCompleted()) {
                return a.isCompleted() ? 1 : -1;
            }
            boolean aOpen = a.getClaimsSoFar() == 0;
            boolean bOpen = b.getClaimsSoFar() == 0;
            if (aOpen != bOpen) {
                return aOpen ? -1 : 1;
            }
            return Integer.compare(b.getPoints(), a.getPoints());
        });
        return ordered;
    }

    private JPanel bountyCard(BoardTile tile) {
        boolean hot = "hot".equals(tile.getTier());
        Color state;
        if (tile.isCompleted()) {
            state = COLOR_COMPLETED;
        } else if (hot) {
            state = COLOR_HOT;
        } else if (tile.getClaimsSoFar() == 0) {
            state = COLOR_BRAND;
        } else {
            state = COLOR_INCOMPLETE;
        }

        Color bg = tint(state);
        JPanel card = new JPanel(new BorderLayout(8, 0));
        card.setBackground(bg);
        card.setBorder(new CompoundBorder(new LineBorder(state, hot ? 2 : 1), new EmptyBorder(8, 8, 8, 8)));
        card.setPreferredSize(new Dimension(BOUNTY_CARD_WIDTH, BOUNTY_CARD_HEIGHT));
        card.setMinimumSize(new Dimension(BOUNTY_CARD_WIDTH, BOUNTY_CARD_HEIGHT));
        card.setMaximumSize(new Dimension(BOUNTY_CARD_WIDTH, BOUNTY_CARD_HEIGHT));

        JLabel icon = new JLabel("", SwingConstants.CENTER);
        icon.setPreferredSize(new Dimension(ITEM_SPRITE_HEIGHT + 4, ITEM_SPRITE_HEIGHT + 4));
        boolean drewIcon = tileIcons != null && tileIcons.apply(tile, icon);
        if (drewIcon) {
            card.add(icon, BorderLayout.WEST);
        }

        JPanel text = new JPanel();
        text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
        text.setOpaque(false);

        JPanel top = new JPanel(new BorderLayout());
        top.setOpaque(false);
        top.setAlignmentX(Component.LEFT_ALIGNMENT);
        top.setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));

        JLabel points = new JLabel(tile.getPoints() + " pts");
        points.setForeground(state);
        points.setFont(FontManager.getDefaultFont().deriveFont(Font.BOLD, 13f));
        top.add(points, BorderLayout.WEST);

        if (hot) {
            JLabel badge = new JLabel("HOT");
            badge.setForeground(COLOR_HOT);
            badge.setFont(FontManager.getDefaultFont().deriveFont(Font.BOLD, 10f));
            top.add(badge, BorderLayout.EAST);
        }
        text.add(top);

        int nameWidth = BOUNTY_CARD_WIDTH - (drewIcon ? ITEM_SPRITE_HEIGHT + 28 : 24);
        JLabel name = new JLabel(wrapHtml(escapeHtml(tile.getName()), nameWidth, "left"));
        name.setForeground(Color.WHITE);
        name.setFont(FontManager.getDefaultFont().deriveFont(12f));
        name.setAlignmentX(Component.LEFT_ALIGNMENT);
        text.add(name);

        JLabel status = new JLabel(bountyStatus(tile));
        status.setForeground(tile.isCompleted() ? COLOR_COMPLETED : COLOR_MUTED);
        status.setFont(FontManager.getDefaultFont().deriveFont(Font.BOLD, 10f));
        status.setAlignmentX(Component.LEFT_ALIGNMENT);
        text.add(status);

        card.add(text, BorderLayout.CENTER);
        card.setToolTipText(richTooltip(tile, tile.getName() + " \u2014 " + tile.getPoints() + " points"));
        attachClick(card, tile, bg);
        return card;
    }

    private String bountyStatus(BoardTile tile) {
        StringBuilder sb = new StringBuilder();
        if (tile.isCompleted()) {
            sb.append("\u2713 claimed by you");
        } else if (tile.getClaimsSoFar() == 0) {
            sb.append("first claim open");
        } else {
            sb.append(tile.getClaimsSoFar()).append(" already claimed");
        }
        if (tile.getQuantity() > 1) {
            sb.append("  \u2022  ").append(tile.getCurrentQty()).append("/").append(tile.getQuantity());
        }
        String closing = bountyClosing(tile);
        if (closing != null) {
            sb.append("  \u2022  ").append(closing);
        }
        return sb.toString();
    }

    /**
     * A live bounty is sent with closesAt at the far end of the number range because it
     * rotates out rather than expiring, so only a plausible timestamp becomes a countdown.
     */
    private String bountyClosing(BoardTile tile) {
        Long closesAt = tile.getClosesAt();
        if (closesAt == null || closesAt > NO_DEADLINE_AFTER_MS) {
            return null;
        }
        long remaining = closesAt - System.currentTimeMillis();
        if (remaining <= 0) {
            return "closed";
        }
        long hours = remaining / (1000 * 60 * 60);
        if (hours >= 1) {
            return hours + "h left";
        }
        return Math.max(1, remaining / (1000 * 60)) + "m left";
    }

    private JPanel renderGridBoard(BoardData board) {
        int rows = board.getRows();
        int cols = board.getCols();
        if (rows == 0 || cols == 0) return new JPanel();

        // For battleship, show two grids (attack + defense)
        if ("battleship".equals(board.getGameType())) {
            return renderBattleshipGrids(board);
        }

        int cellSize = calculateCellSize(cols, rows);

        JPanel grid = new JPanel(new GridLayout(rows, cols, 1, 1));
        grid.setBackground(ColorScheme.DARK_GRAY_COLOR);
        grid.setBorder(new EmptyBorder(4, 4, 4, 4));

        List<BoardTile> tiles = board.getTiles();
        int tileIdx = 0;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                BoardTile tile = null;
                Color state = COLOR_LOCKED;

                if (tileIdx < tiles.size()) {
                    BoardTile candidate = tiles.get(tileIdx);
                    String expectedKey = r + "-" + c;
                    if (expectedKey.equals(candidate.getKey())) {
                        tile = candidate;
                        if (tile.isFree()) {
                            state = COLOR_FREE;
                        } else if (tile.isCompleted()) {
                            state = COLOR_COMPLETED;
                        } else {
                            state = COLOR_INCOMPLETE;
                        }
                        tileIdx++;
                    }
                }

                grid.add(createCell(cellSize, state, tile,
                    tile != null ? tile.getName() : null,
                    progressText(tile),
                    tile != null ? tile.getName() : null));
            }
        }

        return center(grid);
    }

    private JPanel renderBattleshipGrids(BoardData board) {
        int rows = board.getRows();
        int cols = board.getCols();
        BoardData.BattleshipMeta meta = board.getBattleshipMeta();

        // Two 10x10 grids stacked make cells too short to hold a name, which is why
        // the attack board used to look like overlapping fragments. Side-by-side
        // wins whenever it produces a larger square.
        int stacked = calculateCellSize(cols, rows * 2);
        int beside = calculateCellSize(cols * 2, rows);
        boolean sideBySide = detailed && beside > stacked && availableWidth >= cols * 2 * 18;
        int cellSize = sideBySide ? beside : stacked;

        JPanel attackGrid = new JPanel(new GridLayout(rows, cols, 1, 1));
        attackGrid.setBackground(ColorScheme.DARK_GRAY_COLOR);
        List<BoardTile> tiles = board.getTiles();
        int tileIdx = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (tileIdx >= tiles.size()) {
                    attackGrid.add(markerCell(cellSize, COLOR_LOCKED, null, null, null));
                    continue;
                }
                BoardTile tile = tiles.get(tileIdx++);
                String result = tile.getAttackResult();
                Color state;
                String tip;
                String glyph;
                if ("hit".equals(result) || "sunk".equals(result)) {
                    boolean isSunk = "sunk".equals(result);
                    state = isSunk ? COLOR_SUNK : COLOR_HIT;
                    tip = (isSunk ? "Sunk: " : "Hit: ") + tile.getName();
                    glyph = isSunk ? "\u2620" : "\u2716";
                } else if ("miss".equals(result)) {
                    state = COLOR_MISS;
                    tip = "Miss";
                    glyph = "\u00B7";
                } else {
                    state = COLOR_INCOMPLETE;
                    tip = tile.getName();
                    glyph = null;
                }
                attackGrid.add(markerCell(cellSize, state, glyph, tip, tile));
            }
        }

        JPanel defenseGrid = null;
        if (meta != null && (meta.getDefenseGrid() != null || meta.getOurShips() != null)) {
            java.util.Map<String, String> shots = meta.getDefenseGrid() != null
                ? meta.getDefenseGrid() : java.util.Collections.emptyMap();
            defenseGrid = new JPanel(new GridLayout(rows, cols, 1, 1));
            defenseGrid.setBackground(ColorScheme.DARK_GRAY_COLOR);
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    String defResult = shots.get(r + "-" + c);
                    boolean hasShip = shipAt(meta.getOurShips(), r, c);
                    Color state;
                    String tip;
                    String glyph;
                    if ("hit".equals(defResult) || "sunk".equals(defResult)) {
                        boolean isSunk = "sunk".equals(defResult);
                        state = isSunk ? COLOR_SUNK : COLOR_HIT;
                        tip = isSunk ? "Enemy sunk this ship" : "Enemy hit here";
                        glyph = isSunk ? "\u2620" : "\u2716";
                    } else if ("miss".equals(defResult)) {
                        state = COLOR_MISS;
                        tip = "Enemy missed";
                        glyph = "\u00B7";
                    } else if (hasShip) {
                        state = COLOR_BRAND;
                        tip = "Your ship";
                        glyph = "\u25A0";
                    } else {
                        state = new Color(50, 70, 90);
                        tip = "Water";
                        glyph = null;
                    }
                    defenseGrid.add(markerCell(cellSize, state, glyph, tip, null));
                }
            }
        }

        JPanel container = new JPanel();
        container.setBackground(ColorScheme.DARK_GRAY_COLOR);
        if (sideBySide && defenseGrid != null) {
            container.setLayout(new GridLayout(1, 2, 12, 0));
            container.add(labeledGrid("Your Attacks", attackGrid));
            container.add(labeledGrid("Your Fleet", defenseGrid));
        } else {
            container.setLayout(new BoxLayout(container, BoxLayout.Y_AXIS));
            container.add(labeledGrid("Your Attacks", attackGrid));
            if (defenseGrid != null) {
                container.add(Box.createVerticalStrut(8));
                container.add(labeledGrid("Your Fleet", defenseGrid));
            }
        }
        return container;
    }

