    /**
     * A battleship square is a colour and a mark, never a name. A 10x10 cell is too
     * small to wrap "Voidwaker blade" and the previous cell renderer tried anyway,
     * which is what produced the overlapping fragments on the attack grid.
     */
    private JPanel markerCell(int cellSize, Color state, String glyph, String tooltip, BoardTile tile) {
        JPanel cell = new JPanel(new BorderLayout());
        cell.setPreferredSize(new Dimension(cellSize, cellSize));
        cell.setMinimumSize(new Dimension(cellSize, cellSize));
        if (tooltip != null) {
            cell.setToolTipText(tile != null ? richTooltip(tile, tooltip) : tooltip);
        }

        if (!detailed) {
            cell.setBackground(state);
            attachClick(cell, tile, state);
            return cell;
        }

        Color bg = tint(state);
        cell.setBackground(bg);
        cell.setBorder(new LineBorder(state, 1));
        if (glyph != null && cellSize >= 12) {
            JLabel mark = new JLabel(glyph, SwingConstants.CENTER);
            mark.setForeground(state);
            mark.setFont(FontManager.getDefaultFont().deriveFont(Font.BOLD,
                Math.max(10f, Math.min(16f, cellSize * 0.45f))));
            cell.add(mark, BorderLayout.CENTER);
        }
        attachClick(cell, tile, bg);
        return cell;
    }

    private static boolean shipAt(List<BoardData.BattleshipShip> ships, int r, int c) {
        if (ships == null) {
            return false;
        }
        for (BoardData.BattleshipShip ship : ships) {
            if (ship == null || ship.getCells() == null) {
                continue;
            }
            for (List<Number> cell : ship.getCells()) {
                if (cell != null && cell.size() >= 2 && cell.get(0) != null && cell.get(1) != null
                    && cell.get(0).intValue() == r && cell.get(1).intValue() == c) {
                    return true;
                }
            }
        }
        return false;
    }

    private JPanel renderChipDropBoard(BoardData board) {
        int rows = board.getRows();
        int cols = board.getCols();
        if (rows == 0 || cols == 0) return new JPanel();

        int cellSize = calculateCellSize(cols, rows);

        JPanel grid = new JPanel(new GridLayout(rows, cols, 1, 1));
        grid.setBackground(ColorScheme.DARK_GRAY_COLOR);
        grid.setBorder(new EmptyBorder(4, 4, 4, 4));

        List<BoardTile> tiles = board.getTiles();
        int tileIdx = 0;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                BoardTile tile = null;
                Color state = COLOR_LOCKED;
                String tip = null;

                if (tileIdx < tiles.size()) {
                    BoardTile candidate = tiles.get(tileIdx);
                    if ((r + "-" + c).equals(candidate.getKey())) {
                        tile = candidate;
                        if (tile.isCompleted()) {
                            state = COLOR_COMPLETED;
                        } else if (tile.isAvailable()) {
                            state = COLOR_AVAILABLE;
                        } else {
                            state = COLOR_LOCKED;
                        }
                        tip = tile.getName() + (tile.isAvailable() ? " (available)" : tile.isCompleted() ? " (claimed)" : " (locked)");
                        tileIdx++;
                    }
                }

                grid.add(createCell(cellSize, state, tile,
                    tile != null ? tile.getName() : null, progressText(tile), tip));
            }
        }

        return center(grid);
    }

    // A tile race tile's key is its index along the track. Blind mode leaves fogged tiles
    // out of the list altogether, so a tile's place in the list is not its position and
    // reading one as the other shifts every tile after the first hidden one.
    private static int trackPosition(BoardTile tile, int fallback) {
        String key = tile.getKey();
        if (key != null) {
            try {
                return Integer.parseInt(key.trim());
            } catch (NumberFormatException ignored) {
                // Not a track index; fall back to list order.
            }
        }
        return fallback;
    }

    // The square a track position occupies on a snaking board: row 0 runs left to right,
    // row 1 right to left, and so on. Mirrors getSerpentinePosition in the website's
    // src/services/tileRaceEngine.js. BoardRendererLayoutTest covers this copy.
    static int serpentineSlot(int position, int cols) {
        int row = position / cols;
        int colInRow = position % cols;
        int col = (row % 2 == 1) ? (cols - 1 - colInRow) : colInRow;
        return row * cols + col;
    }

    private JPanel renderTileRaceBoard(BoardData board) {
        List<BoardTile> tiles = board.getTiles();

        // The track snakes, the same way it does on the website: the first row runs left
        // to right, the next right to left, so the end of one row sits directly above the
        // start of the next. Drawing every row left to right instead mirrored the odd
        // ones, which is not a cosmetic difference — standing at the right-hand end of a
        // row, the next tile looked like the one directly below when it was really the
        // one at the far left.
        //
        // The column count comes from the server so all three views agree. Choosing our
        // own would snake in different places, which puts the turns somewhere else again.
        int maxPosition = -1;
        for (int i = 0; i < tiles.size(); i++) {
            maxPosition = Math.max(maxPosition, trackPosition(tiles.get(i), i));
        }
        if (maxPosition < 0) return center(new JPanel());

        int cols = board.getCols();
        if (cols <= 0) {
            cols = Math.min(detailed ? 8 : 12, maxPosition + 1);
        }
        // Blind mode hides tiles rather than shrinking the board, so the track has to be
        // tall enough for the furthest position we were handed, not for the number of
        // tiles actually in the list. Sizing it from the list would drop the tiles past
        // the end of it.
        int rows = Math.max(board.getRows(), (int) Math.ceil((maxPosition + 1) / (double) cols));

        BoardTile[] slots = new BoardTile[rows * cols];
        int[] slotPositions = new int[slots.length];
        java.util.Arrays.fill(slotPositions, -1);
        for (int i = 0; i < tiles.size(); i++) {
            BoardTile tile = tiles.get(i);
            int pos = trackPosition(tile, i);
            if (pos < 0) continue;
            int slot = serpentineSlot(pos, cols);
            if (slot >= 0 && slot < slots.length) {
                slots[slot] = tile;
                slotPositions[slot] = pos;
            }
        }

        int cellSize = calculateCellSize(cols, rows);

        java.util.Set<Integer> opponentPositions = new java.util.HashSet<>();
        if (board.getOpponents() != null) {
            for (BoardData.OpponentPosition opp : board.getOpponents()) {
                opponentPositions.add(opp.getPosition());
            }
        }

        JPanel track = new JPanel(new GridLayout(rows, cols, 1, 1));
        track.setBackground(ColorScheme.DARK_GRAY_COLOR);
        track.setBorder(new EmptyBorder(4, 4, 4, 4));

        for (int slot = 0; slot < slots.length; slot++) {
            BoardTile tile = slots[slot];
            if (tile == null) {
                track.add(createCell(cellSize, ColorScheme.DARK_GRAY_COLOR, null, null, null, null));
                continue;
            }

            int i = slotPositions[slot];
            String special = tile.getSpecial();
            Color state;
            String tip;
            String badge = progressText(tile);

            if ("start".equals(special)) {
                state = COLOR_FREE;
                tip = "Start";
            } else if ("finish".equals(special)) {
                state = new Color(200, 100, 200);
                tip = "Finish";
            } else if ("forward".equals(special) || "backward".equals(special)) {
                state = new Color(180, 140, 80);
                tip = tile.getName();
            } else if (tile.isCurrent()) {
                state = COLOR_CURRENT;
                tip = "\u25B6 " + tile.getName() + " (YOU)";
                badge = "\u25B6 you";
            } else if (opponentPositions.contains(i)) {
                state = COLOR_OPPONENT;
                tip = "\u2716 " + tile.getName() + " (" + getOpponentNamesAt(board, i) + ")";
            } else if (tile.isCompleted()) {
                state = COLOR_COMPLETED;
                tip = "\u2713 " + tile.getName();
            } else {
                state = COLOR_INCOMPLETE;
                tip = tile.getName();
            }

            // The same number the website prints in the corner of every race tile, so a
            // player can read one board against the other and land on the same tile.
            track.add(createCell(cellSize, state, tile, tile.getName(), badge,
                tip + "  (#" + i + ")"));
        }

        return center(track);
    }

    private String getOpponentNamesAt(BoardData board, int position) {
        if (board.getOpponents() == null) return "Opponent";
        return board.getOpponents().stream()
            .filter(o -> o.getPosition() == position)
            .map(BoardData.OpponentPosition::getName)
            .collect(Collectors.joining(", "));
    }

    private JPanel renderTerritoryBoard(BoardData board) {
        List<BoardTile> tiles = board.getTiles();

        if (detailed) {
            return renderTerritoryCards(board, tiles);
        }

        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        panel.setBorder(new EmptyBorder(4, 4, 4, 4));

        List<BoardTile> ourTiles = tiles.stream().filter(BoardTile::isOurs).collect(Collectors.toList());
        List<BoardTile> attackable = tiles.stream().filter(t -> t.isAttackable() && !t.isOurs()).collect(Collectors.toList());
        List<BoardTile> enemyLocked = tiles.stream().filter(t -> !t.isOurs() && !t.isAttackable()).collect(Collectors.toList());

        addTerritoryRow(panel, "Yours (" + ourTiles.size() + "):", COLOR_COMPLETED, ourTiles, true);
        addTerritoryRow(panel, "\u2694 Attack (" + attackable.size() + "):", COLOR_ATTACKABLE, attackable, true);
        addTerritoryRow(panel, "Enemy (" + enemyLocked.size() + "):", COLOR_LOCKED, enemyLocked, false);

        return panel;
    }

    /**
     * Territory War has no grid to draw — adjacency is the map — so at window size each
     * territory becomes a card carrying the three things that decide a move: who holds it,
     * how well defended it is, and which drop takes it.
     */
    private JPanel renderTerritoryCards(BoardData board, List<BoardTile> tiles) {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        panel.setBorder(new EmptyBorder(6, 6, 6, 6));

        addTerritoryGroup(panel, board, "\u2694 Attackable", COLOR_ATTACKABLE,
            tiles.stream().filter(t -> t.isAttackable() && !t.isOurs()).collect(Collectors.toList()));
        addTerritoryGroup(panel, board, "\u2713 Yours", COLOR_COMPLETED,
            tiles.stream().filter(BoardTile::isOurs).collect(Collectors.toList()));
        addTerritoryGroup(panel, board, "\uD83D\uDD12 Out of reach", COLOR_LOCKED,
            tiles.stream().filter(t -> !t.isOurs() && !t.isAttackable()).collect(Collectors.toList()));

        return panel;
    }

    private void addTerritoryGroup(JPanel parent, BoardData board, String title, Color color,
                                   List<BoardTile> tiles) {
        if (tiles.isEmpty()) {
            return;
        }

        JPanel header = createSectionHeader(title + " (" + tiles.size() + ")", color);
        header.setAlignmentX(Component.LEFT_ALIGNMENT);
        parent.add(header);
        parent.add(Box.createVerticalStrut(4));

        int cols = Math.max(1, (availableWidth - 20) / TERRITORY_CARD_WIDTH);
        int rows = (int) Math.ceil(tiles.size() / (double) cols);
        JPanel grid = new JPanel(new GridLayout(rows, cols, 4, 4));
        grid.setBackground(ColorScheme.DARK_GRAY_COLOR);
        grid.setAlignmentX(Component.LEFT_ALIGNMENT);

        for (BoardTile tile : tiles) {
            grid.add(territoryCard(tile, board, color));
        }
        // GridLayout stretches its last row's cells otherwise.
        for (int i = tiles.size(); i < rows * cols; i++) {
            JPanel filler = new JPanel();
            filler.setBackground(ColorScheme.DARK_GRAY_COLOR);
            grid.add(filler);
        }

        parent.add(grid);
        parent.add(Box.createVerticalStrut(10));
    }

    private JPanel territoryCard(BoardTile tile, BoardData board, Color color) {
        Color bg = tint(color);
        JPanel card = new JPanel();
        card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
        card.setBackground(bg);
        card.setBorder(new CompoundBorder(new LineBorder(color, 1), new EmptyBorder(6, 8, 6, 8)));
        card.setPreferredSize(new Dimension(TERRITORY_CARD_WIDTH, 82));

        String name = tile.getTerritoryName() != null && !tile.getTerritoryName().isEmpty()
            ? tile.getTerritoryName() : tile.getName();
        JLabel nameLabel = new JLabel(name);
        nameLabel.setForeground(Color.WHITE);
        nameLabel.setFont(nameLabel.getFont().deriveFont(Font.BOLD, 13f));
        nameLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        card.add(nameLabel);

        JLabel dropLabel = new JLabel(tile.getName());
        dropLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        dropLabel.setFont(dropLabel.getFont().deriveFont(11f));
        dropLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        card.add(dropLabel);

        StringBuilder meta = new StringBuilder();
        String holder = territoryHolder(tile, board);
        if (holder != null) {
            meta.append(holder);
        }
        if (tile.getDefenseLevel() > 0) {
            if (meta.length() > 0) meta.append("  \u2022  ");
            meta.append("+").append(tile.getDefenseLevel()).append(" def");
        }
        if (meta.length() > 0) {
            JLabel metaLabel = new JLabel(meta.toString());
            metaLabel.setForeground(color);
            metaLabel.setFont(metaLabel.getFont().deriveFont(Font.BOLD, 10f));
            metaLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
            card.add(metaLabel);
        }

        card.setToolTipText(name + " \u2014 " + tile.getName());
        attachClick(card, tile, bg);
        return card;
    }

    /** Display name of whoever currently holds a territory, or null when unknown. */
    private String territoryHolder(BoardTile tile, BoardData board) {
        BoardData.TerritoryMeta meta = board.getTerritoryMeta();
        if (meta == null || meta.getOwners() == null) {
            return null;
        }
        BoardData.TerritoryOwner owner = meta.getOwners().get(tile.getKey());
        if (owner == null || owner.getOwner() == null) {
            return "unclaimed";
        }
        if (meta.getOwnerNames() != null) {
            String display = meta.getOwnerNames().get(owner.getOwner());
            if (display != null && !display.isEmpty()) {
                return display;
            }
        }
        return owner.getOwner();
    }

    private void addTerritoryRow(JPanel parent, String title, Color color, List<BoardTile> tiles, boolean showDefense) {
        if (tiles.isEmpty()) return;
        int dot = detailed ? 18 : 10;

        JPanel section = new JPanel(new FlowLayout(FlowLayout.LEFT, 3, 2));
        section.setBackground(ColorScheme.DARK_GRAY_COLOR);
        section.setMaximumSize(new Dimension(Integer.MAX_VALUE, detailed ? Integer.MAX_VALUE : 26));

        JLabel label = new JLabel(title);
        label.setForeground(color);
        label.setFont(label.getFont().deriveFont(fs(10f)));
        section.add(label);

        for (BoardTile tile : tiles) {
            JPanel cell = new JPanel();
            cell.setPreferredSize(new Dimension(dot, dot));
            cell.setBackground(color);
            String tip = tile.getTerritoryName() != null ? tile.getTerritoryName() : tile.getName();
            if (showDefense && tile.getDefenseLevel() > 0) tip += " +" + tile.getDefenseLevel() + " def";
            cell.setToolTipText(tip);
            attachClick(cell, tile, color);
            section.add(cell);
        }
        parent.add(section);
    }

    private JPanel renderMonopolyBoard(BoardData board) {
        List<BoardTile> tiles = board.getTiles();
        int tilesPerRow = 8;
        int totalRows = (int) Math.ceil(tiles.size() / (double) tilesPerRow);
        int cellSize = calculateCellSize(tilesPerRow, totalRows);

        JPanel track = new JPanel(new GridLayout(totalRows, tilesPerRow, 1, 1));
        track.setBackground(ColorScheme.DARK_GRAY_COLOR);
        track.setBorder(new EmptyBorder(4, 4, 4, 4));

        for (int i = 0; i < totalRows * tilesPerRow; i++) {
            if (i >= tiles.size()) {
                track.add(createCell(cellSize, ColorScheme.DARK_GRAY_COLOR, null, null, null, null));
                continue;
            }
            BoardTile tile = tiles.get(i);
            Color state = tile.isCompleted() ? COLOR_COMPLETED : COLOR_INCOMPLETE;
            track.add(createCell(cellSize, state, tile, tile.getName(), progressText(tile), tile.getName()));
        }

        return center(track);
    }

    // ===== TILE LIST =====

    void renderTileList(BoardData board, JPanel container) {
        String gameType = board.getGameType();
        List<BoardTile> tiles = board.getTiles();

        if ("tilerace".equals(gameType)) {
            renderTileRaceList(tiles, board, container);
        } else if ("chipdrop".equals(gameType)) {
            renderChipDropList(tiles, container);
        } else if ("territory".equals(gameType)) {
            renderTerritoryList(tiles, container);
        } else if ("battleship".equals(gameType)) {
            renderBattleshipList(tiles, container);
        } else if ("delve".equals(gameType)) {
            renderDelveList(tiles, board, container);
        } else if ("bounty".equals(gameType)) {
            renderBountyList(tiles, container);
        } else {
            renderDefaultList(tiles, container);
        }
    }

    private void renderTileRaceList(List<BoardTile> tiles, BoardData board, JPanel container) {
        List<BoardTile> current = tiles.stream()
            .filter(t -> t.isCurrent() && t.getSpecial() == null && !t.isCompleted())
            .collect(Collectors.toList());
        if (!current.isEmpty()) {
            container.add(createSectionHeader("\u25B6 Current Tile", COLOR_CURRENT));
            container.add(Box.createVerticalStrut(4));
            for (BoardTile tile : current) {
                container.add(createTileRow(tile, false, "\u25B6 "));
            }
            container.add(Box.createVerticalStrut(8));
        }

        if (board.getOpponents() != null && !board.getOpponents().isEmpty()) {
            container.add(createSectionHeader("\u2716 Opponents", COLOR_OPPONENT));
            container.add(Box.createVerticalStrut(4));
            for (BoardData.OpponentPosition opp : board.getOpponents()) {
                JPanel row = newRow();
                JLabel label = new JLabel("\u2716 " + opp.getName());
                label.setForeground(COLOR_OPPONENT);
                label.setFont(label.getFont().deriveFont(fs(11f)));
                row.add(label, BorderLayout.WEST);
                JLabel posLabel = new JLabel("tile " + opp.getPosition());
                posLabel.setForeground(new Color(150, 150, 180));
                posLabel.setFont(posLabel.getFont().deriveFont(fs(10f)));
                row.add(posLabel, BorderLayout.EAST);
                container.add(row);
            }
            container.add(Box.createVerticalStrut(8));
        }

        List<BoardTile> remaining = tiles.stream()
            .filter(t -> !t.isCompleted() && !t.isCurrent() && t.getSpecial() == null)
            .collect(Collectors.toList());
        if (!remaining.isEmpty()) {
            container.add(createSectionHeader("\u25CB Remaining (" + remaining.size() + ")", COLOR_INCOMPLETE));
            container.add(Box.createVerticalStrut(4));
            for (BoardTile tile : remaining) {
                container.add(createTileRow(tile, false, null));
            }
        }
    }

    private void renderTerritoryList(List<BoardTile> tiles, JPanel container) {
        List<BoardTile> attackable = tiles.stream()
            .filter(t -> t.isAttackable() && !t.isOurs())
            .collect(Collectors.toList());
        if (!attackable.isEmpty()) {
            container.add(createSectionHeader("\u2694 Attackable (" + attackable.size() + ")", COLOR_ATTACKABLE));
            container.add(Box.createVerticalStrut(4));
            for (BoardTile tile : attackable) {
                String name = tile.getTerritoryName() != null ? tile.getTerritoryName() : tile.getName();
                String suffix = tile.getDefenseLevel() > 0 ? " [+" + tile.getDefenseLevel() + " def]" : "";
                JPanel row = newRow();
                JLabel label = new JLabel("\u2694 " + name + suffix);
                label.setForeground(COLOR_ATTACKABLE);
                label.setFont(label.getFont().deriveFont(fs(11f)));
                row.add(label, BorderLayout.WEST);
                JLabel dropLabel = new JLabel(tile.getName());
                dropLabel.setForeground(new Color(150, 150, 180));
                dropLabel.setFont(dropLabel.getFont().deriveFont(fs(9f)));
                row.add(dropLabel, BorderLayout.EAST);
                attachClick(row, tile, ColorScheme.DARKER_GRAY_COLOR);
                container.add(row);
            }
            container.add(Box.createVerticalStrut(8));
        }

        List<BoardTile> ours = tiles.stream().filter(BoardTile::isOurs).collect(Collectors.toList());
        if (!ours.isEmpty()) {
            container.add(createSectionHeader("\u2713 Your Territories (" + ours.size() + ")", COLOR_COMPLETED));
            container.add(Box.createVerticalStrut(4));
            for (BoardTile tile : ours) {
                container.add(createTileRow(tile, true, null));
            }
            container.add(Box.createVerticalStrut(8));
        }

        List<BoardTile> locked = tiles.stream()
            .filter(t -> !t.isOurs() && !t.isAttackable())
            .collect(Collectors.toList());
        if (!locked.isEmpty()) {
            container.add(createSectionHeader("\uD83D\uDD12 Out of Reach (" + locked.size() + ")", COLOR_LOCKED));
            container.add(Box.createVerticalStrut(4));
            for (BoardTile tile : locked) {
                container.add(createTileRow(tile, false, null));
            }
        }
    }

    private void renderBattleshipList(List<BoardTile> tiles, JPanel container) {
        List<BoardTile> sunk = tiles.stream()
            .filter(t -> "sunk".equals(t.getAttackResult()))
            .collect(Collectors.toList());
        if (!sunk.isEmpty()) {
            container.add(createSectionHeader("\u2620 Sunk (" + sunk.size() + ")", COLOR_SUNK));
            container.add(Box.createVerticalStrut(4));
            for (BoardTile tile : sunk) {
                container.add(createTileRow(tile, true, "\u2620 "));
            }
            container.add(Box.createVerticalStrut(8));
        }

        List<BoardTile> hits = tiles.stream()
            .filter(t -> "hit".equals(t.getAttackResult()))
            .collect(Collectors.toList());
        if (!hits.isEmpty()) {
            container.add(createSectionHeader("\u2716 Hits (" + hits.size() + ")", COLOR_HIT));
            container.add(Box.createVerticalStrut(4));
            for (BoardTile tile : hits) {
                container.add(createTileRow(tile, true, "\u2716 "));
            }
            container.add(Box.createVerticalStrut(8));
        }

        List<BoardTile> misses = tiles.stream()
            .filter(t -> "miss".equals(t.getAttackResult()))
            .collect(Collectors.toList());
        if (!misses.isEmpty()) {
            container.add(createSectionHeader("\u25CB Misses (" + misses.size() + ")", COLOR_MISS));
            container.add(Box.createVerticalStrut(4));
            for (BoardTile tile : misses) {
                container.add(createTileRow(tile, false, "\u25CB "));
            }
            container.add(Box.createVerticalStrut(8));
        }

        List<BoardTile> remaining = tiles.stream()
            .filter(t -> t.getAttackResult() == null)
            .collect(Collectors.toList());
        if (!remaining.isEmpty()) {
            container.add(createSectionHeader("\u25CB Remaining (" + remaining.size() + ")", COLOR_INCOMPLETE));
            container.add(Box.createVerticalStrut(4));
            for (BoardTile tile : remaining) {
                container.add(createTileRow(tile, false, null));
            }
        }
    }

    private void renderChipDropList(List<BoardTile> tiles, JPanel container) {
        List<BoardTile> available = tiles.stream()
            .filter(t -> t.isAvailable() && !t.isCompleted())
            .collect(Collectors.toList());
        if (!available.isEmpty()) {
            container.add(createSectionHeader("\uD83D\uDD13 Available (" + available.size() + ")", COLOR_AVAILABLE));
            container.add(Box.createVerticalStrut(4));
            for (BoardTile tile : available) {
                container.add(createTileRow(tile, false, null));
            }
            container.add(Box.createVerticalStrut(8));
        }

        List<BoardTile> completed = tiles.stream()
            .filter(BoardTile::isCompleted)
            .collect(Collectors.toList());
        if (!completed.isEmpty()) {
            container.add(createSectionHeader("\u2713 Claimed (" + completed.size() + ")", COLOR_COMPLETED));
            container.add(Box.createVerticalStrut(4));
            for (BoardTile tile : completed) {
                container.add(createTileRow(tile, true, null));
            }
            container.add(Box.createVerticalStrut(8));
        }

        List<BoardTile> locked = tiles.stream()
            .filter(t -> !t.isAvailable() && !t.isCompleted())
            .collect(Collectors.toList());
        if (!locked.isEmpty()) {
            container.add(createSectionHeader("\uD83D\uDD12 Locked (" + locked.size() + ")", COLOR_LOCKED));
            container.add(Box.createVerticalStrut(4));
            for (BoardTile tile : locked) {
                container.add(createTileRow(tile, false, "\uD83D\uDD12 "));
            }
        }
    }

    private void renderBountyList(List<BoardTile> tiles, JPanel container) {
        List<BoardTile> ordered = orderBounties(tiles);

        List<BoardTile> open = ordered.stream().filter(t -> !t.isCompleted()).collect(Collectors.toList());
        if (!open.isEmpty()) {
            container.add(createSectionHeader("\u25CB Live bounties (" + open.size() + ")", COLOR_BRAND));
            container.add(Box.createVerticalStrut(4));
            for (BoardTile tile : open) {
                container.add(bountyRow(tile));
            }
            container.add(Box.createVerticalStrut(8));
        }

        List<BoardTile> claimed = ordered.stream().filter(BoardTile::isCompleted).collect(Collectors.toList());
        if (!claimed.isEmpty()) {
            container.add(createSectionHeader("\u2713 Claimed (" + claimed.size() + ")", COLOR_COMPLETED));
            container.add(Box.createVerticalStrut(4));
            for (BoardTile tile : claimed) {
                container.add(bountyRow(tile));
            }
        }
    }

    /** Payout is the point of a bounty, so it takes the slot a quantity would use. */
    private JPanel bountyRow(BoardTile tile) {
        boolean hot = "hot".equals(tile.getTier());
        JPanel row = newRow();

        JLabel nameLabel = new JLabel((hot ? "HOT  " : "") + tile.getName());
        nameLabel.setForeground(tile.isCompleted() ? new Color(120, 180, 120) : ColorScheme.LIGHT_GRAY_COLOR);
        nameLabel.setFont(nameLabel.getFont().deriveFont(fs(11f)));
        row.add(nameLabel, BorderLayout.CENTER);

        if (tileIcons != null) {
            JLabel icon = new JLabel();
            if (tileIcons.apply(tile, icon)) {
                icon.setBorder(new EmptyBorder(0, 0, 0, 6));
                row.add(icon, BorderLayout.WEST);
                row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 42));
                row.setPreferredSize(new Dimension(row.getPreferredSize().width, 42));
            }
        }

        JLabel pointsLabel = new JLabel(tile.getPoints() + " pts");
        pointsLabel.setForeground(hot ? COLOR_HOT : COLOR_MUTED);
        pointsLabel.setFont(pointsLabel.getFont().deriveFont(Font.BOLD, fs(10f)));
        pointsLabel.setToolTipText(bountyStatus(tile));
        row.add(pointsLabel, BorderLayout.EAST);

        attachClick(row, tile, ColorScheme.DARKER_GRAY_COLOR);
        return row;
    }

    private void renderDefaultList(List<BoardTile> tiles, JPanel container) {
        List<BoardTile> completed = tiles.stream()
            .filter(t -> t.isCompleted() && !t.isFree())
            .collect(Collectors.toList());
        if (!completed.isEmpty()) {
            container.add(createSectionHeader("\u2713 Completed (" + completed.size() + ")", COLOR_COMPLETED));
            container.add(Box.createVerticalStrut(4));
            for (BoardTile tile : completed) {
                container.add(createTileRow(tile, true, null));
            }
            container.add(Box.createVerticalStrut(8));
        }

        List<BoardTile> remaining = tiles.stream()
            .filter(t -> !t.isCompleted() && !t.isFree())
            .collect(Collectors.toList());
        if (!remaining.isEmpty()) {
            container.add(createSectionHeader("\u25CB Remaining (" + remaining.size() + ")", COLOR_INCOMPLETE));
            container.add(Box.createVerticalStrut(4));
            for (BoardTile tile : remaining) {
                container.add(createTileRow(tile, false, null));
            }
        }
    }

    /**
     * The Delve's list is not a checklist. Its three groups answer three different
     * questions, and conflating them is what made the old panel useless here: the boss
     * table is what you should be killing right now, the objectives are the only drops
     * actually required, and the bonus drops are pure upside that nobody is assigned.
     */
    private void renderDelveList(List<BoardTile> tiles, BoardData board, JPanel container) {
        BoardData.DelveMeta dm = board.getDelveMeta();

        List<BoardData.DelveBoss> bosses = (dm != null && dm.getBosses() != null)
            ? dm.getBosses()
            : java.util.Collections.<BoardData.DelveBoss>emptyList();
        if (!bosses.isEmpty()) {
            container.add(createSectionHeader("\u2694 Kill for supplies (" + bosses.size() + ")", COLOR_BRAND));
            container.add(Box.createVerticalStrut(4));
            for (BoardData.DelveBoss boss : bosses) {
                container.add(createDelveBossRow(boss));
            }
            container.add(Box.createVerticalStrut(8));
        }

        // Guardians and the warden: the only drops the Delve genuinely requires, and only
        // once the party has paid to open that room.
        List<BoardTile> required = tiles.stream()
            .filter(t -> !t.isOptional() && !t.isCompleted())
            .collect(Collectors.toList());
        if (!required.isEmpty()) {
            container.add(createSectionHeader("\uD83D\uDDDD Must drop (" + required.size() + ")", COLOR_CURRENT));
            container.add(Box.createVerticalStrut(4));
            for (BoardTile tile : required) {
                container.add(createTileRow(tile, false, null));
            }
            container.add(Box.createVerticalStrut(8));
        }

        List<BoardTile> bonus = tiles.stream()
            .filter(BoardTile::isOptional)
            .collect(Collectors.toList());
        if (!bonus.isEmpty()) {
            container.add(createSectionHeader("\u2728 Bonus if you get lucky (" + bonus.size() + ")", COLOR_FREE));
            container.add(Box.createVerticalStrut(2));
            container.add(createDelveNote("Not required, not assigned \u2014 the plugin submits these automatically."));
            container.add(Box.createVerticalStrut(4));
            for (BoardTile tile : bonus) {
                container.add(createDelveBonusRow(tile));
            }
        }
    }

    private JPanel createDelveBossRow(BoardData.DelveBoss boss) {
        JPanel row = newRow();

        JLabel nameLabel = new JLabel(boss.getName());
        nameLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        nameLabel.setFont(nameLabel.getFont().deriveFont(fs(11f)));
        row.add(nameLabel, BorderLayout.WEST);

        String right = boss.getRate() + "/kill";
        if (boss.getKills() > 0) right = boss.getKills() + " \u00D7 " + right;
        JLabel rateLabel = new JLabel(right);
        rateLabel.setForeground(boss.getKills() > 0 ? COLOR_COMPLETED : tierColor(boss.getTier()));
        rateLabel.setFont(rateLabel.getFont().deriveFont(fs(10f)));
        rateLabel.setToolTipText(boss.getKills() > 0
            ? boss.getKills() + " kills banked, worth " + (boss.getKills() * boss.getRate()) + " supplies"
            : "Worth " + boss.getRate() + " supplies per kill");
        row.add(rateLabel, BorderLayout.EAST);

        return row;
    }

    private JPanel createDelveBonusRow(BoardTile tile) {
        JPanel row = newRow();

        JLabel nameLabel = new JLabel(tile.getName());
        nameLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        nameLabel.setFont(nameLabel.getFont().deriveFont(fs(11f)));
        row.add(nameLabel, BorderLayout.WEST);

        if (tile.getTier() != null && !tile.getTier().isEmpty()) {
            JLabel tierLabel = new JLabel(tile.getTier());
            tierLabel.setForeground(new Color(150, 150, 180));
            tierLabel.setFont(tierLabel.getFont().deriveFont(fs(10f)));
            row.add(tierLabel, BorderLayout.EAST);
        }

        return row;
    }

    private JPanel createDelveNote(String text) {
        JPanel panel = new JPanel(new BorderLayout());
        panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        panel.setBorder(new EmptyBorder(0, 8, 2, 8));
        JLabel label = new JLabel(wrapHtml(text, Math.max(120, availableWidth - 40), "left"));
        label.setForeground(new Color(130, 130, 150));
        label.setFont(label.getFont().deriveFont(fs(9f)));
        panel.add(label, BorderLayout.WEST);
        return panel;
    }

    private Color tierColor(String tier) {
        if ("hard".equals(tier)) return new Color(226, 120, 120);
        if ("easy".equals(tier)) return new Color(140, 190, 140);
        return new Color(220, 180, 60);
    }

    // ===== UI HELPERS =====

    JPanel createSectionHeader(String text, Color color) {
        JPanel panel = new JPanel(new BorderLayout());
        panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));

        JLabel label = new JLabel(text);
        label.setForeground(color);
        label.setFont(label.getFont().deriveFont(Font.BOLD, fs(11f)));
        panel.add(label, BorderLayout.WEST);

        JSeparator sep = new JSeparator();
        sep.setForeground(new Color(60, 60, 70));
        panel.add(sep, BorderLayout.SOUTH);

        return panel;
    }

    private JPanel newRow() {
        JPanel row = new JPanel(new BorderLayout());
        row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        row.setBorder(new EmptyBorder(4, 8, 4, 8));
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, detailed ? 40 : 32));
        return row;
    }

    private JPanel createTileRow(BoardTile tile, boolean completed, String prefix) {
        JPanel row = newRow();

        // The icon goes on first because the note below has to wrap inside whatever width
        // is left once the sprite and the quantity badge have taken theirs.
        boolean hasIcon = false;
        if (tileIcons != null) {
            JLabel icon = new JLabel();
            if (tileIcons.apply(tile, icon)) {
                icon.setBorder(new EmptyBorder(0, 0, 0, 6));
                row.add(icon, BorderLayout.WEST);
                hasIcon = true;
            }
        }
        boolean hasQty = tile.getQuantity() > 1;

        String displayName = (prefix != null ? prefix : "") + tile.getName();
        if (completed && prefix == null) {
            displayName = "\u2713 " + tile.getName();
        }

        JLabel nameLabel = new JLabel(displayName);
        nameLabel.setForeground(completed ? new Color(120, 180, 120) : ColorScheme.LIGHT_GRAY_COLOR);
        nameLabel.setFont(nameLabel.getFont().deriveFont(fs(11f)));

        // The host's note is a rule, not a hint ("solo only, no alts"), so it rides under
        // the name where it cannot be missed rather than hiding in a tooltip.
        String note = tile.getDescription();
        boolean hasNote = note != null && !note.trim().isEmpty();
        JPanel stack = null;

        if (hasNote) {
            stack = new JPanel();
            stack.setLayout(new BoxLayout(stack, BoxLayout.Y_AXIS));
            stack.setOpaque(false);
            nameLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
            stack.add(nameLabel);

            // Three things made this hard to read, and the size was the least of them.
            // It was a plain label, which does not wrap, so anything longer than the row
            // ran off the edge and the tail was simply gone — and every generated note
            // ("Obtain a Ring of the gods from Wilderness Boss Uniques") is longer than a
            // 225px sidebar row. It was also italic at 9pt, and a slanted pixel font that
            // small is mush. Wrapped, upright, and a point larger.
            int noteWidth = availableWidth - 22 - (hasIcon ? 40 : 0) - (hasQty ? 34 : 0);
            JLabel noteLabel = new JLabel(
                wrapHtml(escapeHtml(note.trim()), Math.max(80, noteWidth), "left"));
            noteLabel.setForeground(COLOR_NOTE);
            noteLabel.setFont(noteLabel.getFont().deriveFont(fs(10f)));
            noteLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
            stack.add(noteLabel);

            row.add(stack, BorderLayout.CENTER);
        } else {
            row.add(nameLabel, BorderLayout.CENTER);
        }

        // An item sprite is 32px tall and the row's own padding adds 8, so the default
        // 32px cap would slice the icon in half.
        int height = 32;
        if (hasIcon) height = Math.max(height, 42);
        if (detailed) height = Math.max(height, 40);
        if (stack != null) {
            // Tall enough for however many lines the note wrapped to, but not without
            // limit: a host can paste a paragraph, and a row sized to hold one would push
            // the rest of the list off the screen. The tooltip still carries the whole of it.
            height = Math.min(Math.max(height, stack.getPreferredSize().height + 10), NOTE_ROW_MAX_HEIGHT);
        }
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
        row.setPreferredSize(new Dimension(row.getPreferredSize().width, height));

        if (tile.getQuantity() > 1) {
            String qtyText = tile.getCurrentQty() + "/" + tile.getQuantity();
            JLabel qtyLabel = new JLabel(qtyText);
            Color qtyColor = tile.getCurrentQty() >= tile.getQuantity()
                ? new Color(120, 180, 120)
                : tile.getCurrentQty() > 0
                    ? new Color(220, 180, 60)
                    : new Color(150, 150, 180);
            qtyLabel.setForeground(qtyColor);
            qtyLabel.setFont(qtyLabel.getFont().deriveFont(Font.BOLD, fs(10f)));
            row.add(qtyLabel, BorderLayout.EAST);
        }

        // A note longer than the row's height cap is cut off, so the whole of it has to
        // be reachable somewhere. The children get the tooltip as well: a label is not
        // registered with the tooltip manager on its own, and it sits over the row, so
        // hovering the text itself would otherwise show nothing.
        applyTooltip(row, richTooltip(tile, displayName));

        attachClick(row, tile, ColorScheme.DARKER_GRAY_COLOR);
        return row;
    }

    private static void applyTooltip(Container root, String text) {
        if (root instanceof JComponent) {
            ((JComponent) root).setToolTipText(text);
        }
        for (Component child : root.getComponents()) {
            if (child instanceof Container) {
                applyTooltip((Container) child, text);
            }
        }
    }

    /**
     * One board cell.
     *
     * Small cells are bare colour swatches because that is all 12px can carry. A detailed
     * cell is a card: the tile's picture on top, its name under that, and a progress bar
     * along the bottom for anything needing more than one drop. The icon is what makes a
     * board scannable — a player recognises a voidwaker blade far faster than they read
     * "Voidwaker Piece" — so it gets the vertical space and the name gets what's left.
     */
    private JComponent createCell(int cellSize, Color state, BoardTile tile,
                                  String label, String progress, String tooltip) {
        JPanel cell = new JPanel();
        cell.setPreferredSize(new Dimension(cellSize, cellSize));
        if (tooltip != null) {
            cell.setToolTipText(richTooltip(tile, tooltip));
        }

        if (!detailed) {
            cell.setBackground(state);
            attachClick(cell, tile, state);
            return cell;
        }

        Color bg = tint(state);
        cell.setLayout(new BorderLayout(0, 1));
        cell.setBackground(bg);
        cell.setBorder(new CompoundBorder(new LineBorder(state, 1), new EmptyBorder(4, 3, 4, 3)));

        // A cell only earns an icon once there is room for the icon and the name both.
        boolean roomForIcon = cellSize >= 62;
        if (roomForIcon && tileIcons != null && tile != null) {
            JLabel icon = new JLabel("", SwingConstants.CENTER);
            icon.setVerticalAlignment(SwingConstants.CENTER);
            if (tileIcons.apply(tile, icon)) {
                // An item sprite is 32px tall; reserving more than that just steals rows
                // from the name, which is what has to wrap.
                icon.setPreferredSize(new Dimension(cellSize - 8, ITEM_SPRITE_HEIGHT));
                cell.add(icon, BorderLayout.NORTH);
            }
        }

        if (label != null && !label.isEmpty()) {
            JLabel name = new JLabel(wrapHtml(escapeHtml(label), cellSize - 12, "center"),
                SwingConstants.CENTER);
            name.setForeground(tile != null && tile.isCompleted() ? new Color(190, 230, 190) : Color.WHITE);
            name.setFont(cellFont(cellSize));
            cell.add(name, BorderLayout.CENTER);
        }

        JComponent footer = cellFooter(tile, state, progress, cellSize);
        if (footer != null) {
            cell.add(footer, BorderLayout.SOUTH);
        }

        attachClick(cell, tile, bg);
        return cell;
    }

    /**
     * The bottom strip of a detailed cell: a real bar for multi-drop tiles, since "2/9"
     * alone makes a player do the arithmetic to see how close they are, and a plain label
     * for everything else.
     */
    private JComponent cellFooter(BoardTile tile, Color state, String progress, int cellSize) {
        if (progress == null || progress.isEmpty()) {
            return null;
        }

        JLabel text = new JLabel(progress, SwingConstants.CENTER);
        text.setForeground(state);
        text.setFont(FontManager.getDefaultFont().deriveFont(Font.BOLD, 11f));
        text.setAlignmentX(Component.CENTER_ALIGNMENT);

        boolean wantsBar = tile != null && tile.getQuantity() > 1 && cellSize >= 62;
        if (!wantsBar) {
            return text;
        }

        ThinProgressBar bar = new ThinProgressBar();
        bar.setMaximumValue(tile.getQuantity());
        bar.setValue(Math.min(tile.getCurrentQty(), tile.getQuantity()));
        bar.setForeground(tile.getCurrentQty() >= tile.getQuantity() ? COLOR_COMPLETED : state);
        bar.setAlignmentX(Component.CENTER_ALIGNMENT);

        JPanel wrapper = new JPanel();
        wrapper.setLayout(new BoxLayout(wrapper, BoxLayout.Y_AXIS));
        wrapper.setOpaque(false);
        wrapper.add(text);
        wrapper.add(Box.createVerticalStrut(2));
        wrapper.add(bar);
        return wrapper;
    }

    /**
     * Cell text uses the default sans rather than the RuneScape font. That font is a
     * bitmap design meant for 16px, and the derived 9-13px sizes a board cell needs left
     * every tile name looking smudged.
     */
    private static Font cellFont(int cellSize) {
        float size = Math.max(10f, Math.min(13f, cellSize / 9f));
        return FontManager.getDefaultFont().deriveFont(size);
    }

    /**
     * A cell is too small to show the host's note inline, so the hover carries it along
     * with what the tile actually accepts — the two questions a player hovers to answer.
     */
    private String richTooltip(BoardTile tile, String base) {
        if (tile == null) {
            return base;
        }
        StringBuilder sb = new StringBuilder("<b>").append(escapeHtml(base)).append("</b>");

        String note = tile.getDescription();
        if (note != null && !note.trim().isEmpty()) {
            sb.append("<br><i>").append(escapeHtml(note.trim())).append("</i>");
        }
        if (tile.getQuantity() > 1) {
            sb.append("<br>").append(tile.getCurrentQty()).append(" of ").append(tile.getQuantity())
              .append(" collected");
        }
        return wrapHtml(sb.toString(), 220, "left");
    }

    /**
     * HTML text that actually wraps at the given width.
     *
     * A JLabel only wraps inside a fixed-width table. Setting a width on a div or a body
     * is the obvious way to write this, and is what this class did throughout, but Swing's
     * HTML renderer ignores it: the label reports a one-line preferred size and the text
     * gets silently clipped by whatever contains it. Callers pass HTML, so anything
     * player-supplied must already be escaped.
     */
    static String wrapHtml(String innerHtml, int width, String align) {
        return "<html><table width='" + Math.max(30, width) + "' cellpadding='0' cellspacing='0'>"
            + "<tr><td align='" + align + "'>" + innerHtml + "</td></tr></table></html>";
    }

    private String progressText(BoardTile tile) {
        if (tile == null) return null;
        if (tile.getQuantity() > 1) {
            return tile.getCurrentQty() + "/" + tile.getQuantity();
        }
        return tile.isCompleted() ? "\u2713" : null;
    }

    private void attachClick(JPanel cell, BoardTile tile, Color base) {
        if (tileClickListener == null || tile == null) return;
        cell.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        cell.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                tileClickListener.accept(tile);
            }

            @Override
            public void mouseEntered(MouseEvent e) {
                cell.setBackground(base.brighter());
            }

            @Override
            public void mouseExited(MouseEvent e) {
                cell.setBackground(base);
            }
        });
    }

    /** Pulls a state colour most of the way down to the panel background. */
    private static Color tint(Color state) {
        Color base = ColorScheme.DARKER_GRAY_COLOR;
        float f = 0.25f;
        return new Color(
            (int) (base.getRed() + (state.getRed() - base.getRed()) * f),
            (int) (base.getGreen() + (state.getGreen() - base.getGreen()) * f),
            (int) (base.getBlue() + (state.getBlue() - base.getBlue()) * f));
    }

    private JPanel center(JComponent content) {
        JPanel wrapper = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));
        wrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
        wrapper.add(content);
        return wrapper;
    }

    /** Tile names are player-authored and land inside an HTML label. */
    static String escapeHtml(String s) {
        return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    private float fs(float base) {
        return detailed ? base * 1.3f : base;
    }

    static String formatGameType(String gameType) {
        if (gameType == null) return "";
        switch (gameType) {
            case "bingo": return "Bingo";
            case "tilerace": return "Tile Race";
            case "territory": return "Territory War";
            case "chipdrop": return "Chip Drop";
            case "battleship": return "Battleship";
            case "monopoly": return "Boss Tycoon";
            case "delve": return "The Delve";
            case "bounty": return "Bounty Board";
            case "gauntlet": return "The Maze";
            case "slotmachine": return "Slot Machine";
            case "spire": return "Clue Trail";
            default: return gameType;
        }
    }
}

package com.thebirdhouse.plugin;

import lombok.Data;
import java.util.List;
import java.util.Map;

@Data
public class BoardTile {
    private String key;
    private String name;
    private String matchName;
    private List<String> matchItems;
    private String gameType;
    private boolean completed;
    private boolean current;
    private boolean available;
    private boolean free;
    private boolean anyUnique;
    private String special;
    private String region;
    private int quantity;
    private int currentQty;

    // Set by the host in the site's tile editor, and only sent when non-empty: the
    // picture shown on the tile, and a short note ("solo only, no alts") that is a rule
    // rather than a hint, so it belongs anywhere the tile is shown.
    private String image;
    private String description;

    // The Delve: bonus-supply drops are repeatable and are never required, so they must
    // not be rendered as a "remaining" checklist the clan is expected to clear.
    private boolean repeatable;
    private boolean optional;
    private String tier;

    // Bounty Board: what a bounty pays, when its window shuts, and how many teams have
    // already claimed it. The first claim takes full points and later ones a fraction, so
    // claimsSoFar is what decides whether a bounty is still worth chasing.
    private int points;
    private Long closesAt;
    private int claimsSoFar;

    // "Collect all" (AND) tiles: require every slot in matchGroups to be filled.
    private boolean matchAll;
    private List<String> requiredItems;
    private List<String> collectedItems; // lowercased item names already submitted/approved
    // Per-item required quantity and collected count, keyed by lowercased item name.
    // Missing entries mean "1 required" / "0 collected".
    private Map<String, Integer> itemQuantities;
    private Map<String, Integer> collectedCounts;
    // Slots (OR-groups): each slot is satisfied by any one of its items reaching qty.
    private List<MatchGroup> matchGroups;

    @Data
    public static class MatchGroup {
        private List<String> items; // lowercased acceptable item names for this slot
        private int qty;
    }

    // Territory War extras
    private String territoryName;
    private boolean ours;
    private boolean attackable;
    private int defenseLevel;

    // Battleship extras
    private String attackResult; // "hit", "miss", "sunk", or null
}

package com.thebirdhouse.plugin;

import lombok.Data;

import java.util.List;

/**
 * The caller's own team thread.
 *
 * The backend decides which team that is from the room roster, so there is no team
 * to ask for and none to send. A null teamId means this room has no team chat at
 * all (a solo game, or the player has not joined a team yet) rather than an error.
 */
@Data
public class ChatData {
    private String roomCode;
    private String teamId;
    private String teamName;
    private List<ChatMessage> messages;
}

package com.thebirdhouse.plugin;

import lombok.Data;

/**
 * One team chat message as the backend hands it over.
 *
 * Deliberately thinner than what the website stores: no colour (that is a CSS
 * variable and means nothing in Swing) and no image URL, only a flag saying an
 * image was posted. The panel never fetches chat images, so a conversation full
 * of screenshots costs the same as a conversation full of text.
 */
@Data
public class ChatMessage {
    private String id;
    private String name;
    private String text;
    private boolean hasImage;
    private long timestamp;
}

package com.thebirdhouse.plugin;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;

/**
 * Read and reply to your team's chat without leaving the client.
 *
 * A view only: it renders whatever thread it is handed and reports what the player
 * typed. One poller in BirdhousePanel feeds every instance, the same way the board
 * is mirrored into the pop-out window, so having this in two places does not double
 * the request rate.
 *
 * Messages are player-authored and land inside Swing HTML labels, so every field is
 * escaped on the way in. Nothing here writes to the game chatbox: incoming messages
 * are only ever drawn in this panel.
 */
public class ChatPanel extends JPanel {

    /** Matches the cap the backend and the database rules both enforce. */
    static final int MAX_LENGTH = 300;

    private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("HH:mm");
    private static final Color COLOR_SELF = new Color(120, 200, 255);
    private static final Color COLOR_OTHER = new Color(255, 195, 90);
    private static final Color COLOR_MUTED = new Color(150, 150, 150);
    private static final Color COLOR_ERROR = new Color(255, 120, 120);

    /** How the panel hands a typed message off to whoever owns the connection. */
    public interface Sender {
        /** Resolves with null on success, or a short message to show the player. */
        void send(String text, Consumer<String> onResult);
    }

    private final Sender sender;
    private final int wrapWidth;

    private final JPanel messagesPanel;
    private final JScrollPane scrollPane;
    private final JLabel titleLabel;
    private final JLabel statusLabel;
    private final JTextField input;
    private final JButton sendButton;

    /**
     * Ids of what is currently drawn, so an unchanged poll does not rebuild the view.
     *
     * Null means nothing has been drawn yet, which is distinct from an empty thread:
     * comparing two empty lists as equal would skip the very first render and leave the
     * message area blank instead of saying there is nothing in it.
     */
    private List<String> renderedIds;
    private String renderedTeamId;
    private String selfName = "";
    private boolean sending;
    private boolean loaded;

    public ChatPanel(Sender sender, int wrapWidth) {
        this.sender = sender;
        this.wrapWidth = wrapWidth;

        setLayout(new BorderLayout(0, 4));
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        titleLabel = new JLabel("Team Chat");
        titleLabel.setForeground(Color.WHITE);
        titleLabel.setFont(FontManager.getDefaultFont().deriveFont(Font.BOLD, 14f));
        titleLabel.setBorder(new EmptyBorder(0, 2, 2, 2));
        add(titleLabel, BorderLayout.NORTH);

        messagesPanel = new JPanel();
        messagesPanel.setLayout(new BoxLayout(messagesPanel, BoxLayout.Y_AXIS));
        messagesPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        messagesPanel.setBorder(new EmptyBorder(4, 4, 4, 4));

        scrollPane = new JScrollPane(messagesPanel,
            ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
            ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        scrollPane.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
        scrollPane.getVerticalScrollBar().setUnitIncrement(12);
        scrollPane.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        add(scrollPane, BorderLayout.CENTER);

        JPanel bottom = new JPanel(new BorderLayout(4, 2));
        bottom.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel inputRow = new JPanel(new BorderLayout(4, 0));
        inputRow.setBackground(ColorScheme.DARK_GRAY_COLOR);

        input = new JTextField();
        input.setToolTipText("Message your team (" + MAX_LENGTH + " characters)");
        // Enter sends, which is what anyone typing in a chat box expects. This is a
        // Swing field in the plugin's own panel; nothing is ever typed into the game.
        input.addActionListener(this::onSend);
        input.getDocument().addDocumentListener(new DocumentListener() {
            public void insertUpdate(DocumentEvent e) { syncSendEnabled(); }
            public void removeUpdate(DocumentEvent e) { syncSendEnabled(); }
            public void changedUpdate(DocumentEvent e) { syncSendEnabled(); }
        });
        inputRow.add(input, BorderLayout.CENTER);

        sendButton = new JButton("Send");
        sendButton.setFocusPainted(false);
        sendButton.setEnabled(false);
        sendButton.addActionListener(this::onSend);
        inputRow.add(sendButton, BorderLayout.EAST);

        bottom.add(inputRow, BorderLayout.CENTER);

        statusLabel = new JLabel(" ");
        statusLabel.setForeground(COLOR_MUTED);
        statusLabel.setFont(FontManager.getDefaultFont().deriveFont(12f));
        statusLabel.setBorder(new EmptyBorder(1, 2, 0, 2));
        bottom.add(statusLabel, BorderLayout.SOUTH);

        add(bottom, BorderLayout.SOUTH);

        showStatus("Loading\u2026", COLOR_MUTED);
    }

    /** The player's own roster name, so their messages read differently to everyone else's. */
    public void setSelfName(String name) {
        this.selfName = name != null ? name : "";
    }

    /**
     * Chat could not be loaded.
     *
     * Worth its own method because the panel's failure mode was otherwise to sit on the
     * startup placeholder indefinitely, which is indistinguishable from a slow network
     * and hides the actual cause completely.
     */
    public void showProblem(String message) {
        loaded = true;
        showStatus(message, COLOR_ERROR);
    }

    public void showStatus(String message, Color color) {
        statusLabel.setText(message == null || message.isEmpty() ? " " : message);
        statusLabel.setForeground(color != null ? color : COLOR_MUTED);
    }

    /**
     * Hand over the current thread.
     *
     * Rebuilt only when the message list actually changed: a poll that brings nothing
     * new would otherwise throw away the scroll position several times a minute while
     * someone is reading back through it.
     */
    public void setThread(ChatData chat) {
        List<ChatMessage> messages = chat != null && chat.getMessages() != null
            ? chat.getMessages()
            : new ArrayList<>();

        String team = chat != null && chat.getTeamName() != null ? chat.getTeamName() : null;
        titleLabel.setText(team != null ? "Team Chat \u2014 " + team : "Team Chat");

        // Being moved between teams replaces the conversation wholesale. Without this the
        // id comparison below would skip the redraw whenever both threads happen to be
        // empty, and someone reading back through the old team's messages would be left
        // scrolled into the middle of a thread that is no longer theirs.
        String teamId = chat != null ? chat.getTeamId() : null;
        boolean teamChanged = renderedTeamId != null && !renderedTeamId.equals(teamId);
        renderedTeamId = teamId;

        // Clear the startup placeholder once, rather than on every poll: after this the
        // status line belongs to send feedback, and a poll must not wipe an error.
        if (!loaded) {
            loaded = true;
            showStatus("", null);
        }

        List<String> ids = new ArrayList<>(messages.size());
        for (ChatMessage m : messages) {
            ids.add(m.getId());
        }
        if (!teamChanged && ids.equals(renderedIds)) {
            return;
        }

        boolean pinnedToBottom = isScrolledToBottom() || teamChanged;
        renderedIds = ids;

        messagesPanel.removeAll();
        if (messages.isEmpty()) {
            JLabel empty = new JLabel("No messages yet.");
            empty.setForeground(COLOR_MUTED);
            empty.setFont(FontManager.getDefaultFont().deriveFont(12f));
            empty.setAlignmentX(Component.LEFT_ALIGNMENT);
            messagesPanel.add(empty);
        } else {
            for (ChatMessage m : messages) {
                messagesPanel.add(messageRow(m));
                messagesPanel.add(Box.createRigidArea(new Dimension(0, 3)));
            }
        }
        messagesPanel.revalidate();
        messagesPanel.repaint();

        // Someone who has scrolled up to re-read is not dragged back down by a new
        // message; anyone sitting at the bottom follows the conversation.
        if (pinnedToBottom) {
            SwingUtilities.invokeLater(this::scrollToBottom);
        }
    }

    /** Called when the room has no team thread at all, so the reply box is pointless. */
    public void setUnavailable(String reason) {
        // Back to "nothing drawn", so being put back on a team redraws even if that
        // team's thread is empty and the id comparison would otherwise match.
        renderedIds = null;
        renderedTeamId = null;
        titleLabel.setText("Team Chat");
        messagesPanel.removeAll();
        JLabel note = new JLabel(BoardRenderer.wrapHtml(
            BoardRenderer.escapeHtml(reason), wrapWidth, "left"));
        note.setForeground(COLOR_MUTED);
        note.setFont(FontManager.getDefaultFont().deriveFont(12f));
        note.setAlignmentX(Component.LEFT_ALIGNMENT);
        messagesPanel.add(note);
        messagesPanel.revalidate();
        messagesPanel.repaint();
        input.setEnabled(false);
        sendButton.setEnabled(false);
        showStatus("", null);
    }

    public void setSendEnabled(boolean enabled) {
        input.setEnabled(enabled);
        syncSendEnabled();
    }

    private JPanel messageRow(ChatMessage m) {
        JPanel row = new JPanel();
        row.setLayout(new BoxLayout(row, BoxLayout.Y_AXIS));
        row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        row.setAlignmentX(Component.LEFT_ALIGNMENT);

        String name = m.getName() != null ? m.getName() : "?";
        boolean mine = !selfName.isEmpty() && selfName.equalsIgnoreCase(name);

        JLabel header = new JLabel(name + "  " + clock(m.getTimestamp()));
        header.setForeground(mine ? COLOR_SELF : COLOR_OTHER);
        header.setFont(FontManager.getDefaultFont().deriveFont(12f));
        header.setAlignmentX(Component.LEFT_ALIGNMENT);
        row.add(header);

        // An image-only message would otherwise render as a name with nothing under it.
        // The panel does not download chat images, so it says one was posted instead.
        String text = m.getText() != null ? m.getText() : "";
        StringBuilder body = new StringBuilder();
        if (!text.isEmpty()) {
            body.append(BoardRenderer.escapeHtml(text));
        }
        if (m.isHasImage()) {
            if (body.length() > 0) {
                body.append("<br>");
            }
            body.append("<i>[image \u2014 open the room on the site to view]</i>");
        }
        if (body.length() == 0) {
            body.append("<i>[empty]</i>");
        }

        JLabel textLabel = new JLabel(BoardRenderer.wrapHtml(body.toString(), wrapWidth, "left"));
        textLabel.setForeground(Color.WHITE);
        textLabel.setFont(FontManager.getDefaultFont().deriveFont(12f));
        textLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        row.add(textLabel);

        return row;
    }

    private static String clock(long timestamp) {
        if (timestamp <= 0) {
            return "";
        }
        try {
            return CLOCK.format(Instant.ofEpochMilli(timestamp).atZone(ZoneId.systemDefault()));
        } catch (RuntimeException e) {
            return "";
        }
    }

    private void onSend(ActionEvent event) {
        if (sending) {
            return;
        }
        String text = input.getText().trim();
        if (text.isEmpty()) {
            return;
        }
        if (text.length() > MAX_LENGTH) {
            showStatus("Too long by " + (text.length() - MAX_LENGTH) + " characters", COLOR_ERROR);
            return;
        }

        sending = true;
        sendButton.setEnabled(false);
        sendButton.setText("\u2026");
        showStatus("Sending\u2026", COLOR_MUTED);

        sender.send(text, error -> SwingUtilities.invokeLater(() -> {
            sending = false;
            sendButton.setText("Send");
            if (error == null) {
                // Cleared only on success, so a failed send does not lose what was typed.
                input.setText("");
                showStatus("", null);
            } else {
                showStatus(error, COLOR_ERROR);
            }
            syncSendEnabled();
        }));
    }

    private void syncSendEnabled() {
        if (sending) {
            return;
        }
        int length = input.getText().trim().length();
        sendButton.setEnabled(input.isEnabled() && length > 0 && length <= MAX_LENGTH);
        if (length > MAX_LENGTH) {
            showStatus("Too long by " + (length - MAX_LENGTH) + " characters", COLOR_ERROR);
        } else if (COLOR_ERROR.equals(statusLabel.getForeground())) {
            showStatus("", null);
        }
    }

    private boolean isScrolledToBottom() {
        JScrollBar bar = scrollPane.getVerticalScrollBar();
        if (!bar.isVisible()) {
            return true;
        }
        // A few pixels of slack: dragging to the very end rarely lands exactly on it.
        return bar.getValue() + bar.getVisibleAmount() >= bar.getMaximum() - 8;
    }

    private void scrollToBottom() {
        JScrollBar bar = scrollPane.getVerticalScrollBar();
        bar.setValue(bar.getMaximum());
    }
}

package com.thebirdhouse.plugin;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reports loot drops, clue completions, and collection-log entries to the clan
 * leaderboard via POST /api/plugin/clan-loot. This replaces the Dink dynamic-
 * config pipeline so clan members no longer need Dink installed for the Discord
 * drop tracker to work.
 *
 * Completely independent of the bingo game path (DropMatcher / submit-proof).
 * Gated on the contributeClanStats toggle and a non-empty clanId in config.
 */
@Slf4j
@Singleton
public class ClanLootReporter {

    private static final long MIN_LOOT_VALUE = 100_000;

    private static final Pattern COLLECTION_LOG_PATTERN =
        Pattern.compile("New item added to your collection log: (.+)");

    private static final Pattern CLUE_COMPLETE_PATTERN =
        Pattern.compile("You have completed (\\d+) (beginner|easy|medium|hard|elite|master) Treasure Trails?\\.");

    @Inject
    private Client client;

    @Inject
    private ItemManager itemManager;

    @Inject
    private BirdhouseConfig config;

    @Inject
    private BirdhouseApiClient apiClient;

    private boolean isEnabled() {
        return config.contributeClanStats()
            && config.clanId() != null
            && !config.clanId().trim().isEmpty();
    }

    private String clanId() {
        return config.clanId().trim().toLowerCase();
    }

    @Subscribe
    public void onLootReceived(LootReceived event) {
        if (!isEnabled()) return;
        if ("PLAYER".equals(String.valueOf(event.getType()))) return;

        String source = event.getName();
        JsonArray items = new JsonArray();
        long totalValue = 0;

        for (ItemStack stack : event.getItems()) {
            ItemComposition comp = itemManager.getItemComposition(stack.getId());
            long price = 0;
            try {
                price = itemManager.getItemPrice(stack.getId());
            } catch (Exception ignored) {
            }
            long stackVal = Math.max(0L, price) * Math.max(0, stack.getQuantity());
            totalValue += stackVal;

            JsonObject item = new JsonObject();
            item.addProperty("name", comp.getName());
            item.addProperty("id", stack.getId());
            item.addProperty("quantity", stack.getQuantity());
            item.addProperty("priceEach", Math.max(0L, price));
            items.add(item);
        }

        if (totalValue < MIN_LOOT_VALUE) return;

        JsonObject payload = new JsonObject();
        payload.addProperty("type", "LOOT");
        payload.addProperty("clanId", clanId());
        payload.addProperty("playerName", client.getLocalPlayer().getName());
        payload.add("items", items);
        payload.addProperty("source", source);
        payload.addProperty("totalValue", totalValue);

        apiClient.reportClanLoot(payload);
        log.debug("[Birdhouse] Clan loot reported: {} from {} ({}gp)", items.size(), source, totalValue);
    }

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        if (!isEnabled()) return;
        if (event.getType() != ChatMessageType.GAMEMESSAGE
            && event.getType() != ChatMessageType.SPAM) return;

        String message = event.getMessage();
        if (message == null) return;
        String clean = message.replaceAll("<[^>]+>", "").trim();

        Matcher collLog = COLLECTION_LOG_PATTERN.matcher(clean);
        if (collLog.find()) {
            String itemName = collLog.group(1);

            JsonObject payload = new JsonObject();
            payload.addProperty("type", "COLLECTION");
            payload.addProperty("clanId", clanId());
            payload.addProperty("playerName", client.getLocalPlayer().getName());
            payload.addProperty("itemName", itemName);

            apiClient.reportClanLoot(payload);
            log.debug("[Birdhouse] Clan collection log reported: {}", itemName);
            return;
        }

        Matcher clue = CLUE_COMPLETE_PATTERN.matcher(clean);
        if (clue.find()) {
            String clueType = clue.group(2).toLowerCase();

            JsonObject payload = new JsonObject();
            payload.addProperty("type", "CLUE");
            payload.addProperty("clanId", clanId());
            payload.addProperty("playerName", client.getLocalPlayer().getName());
            payload.addProperty("clueType", clueType);
            payload.addProperty("source", "Clue scroll (" + clueType + ")");
            payload.add("items", new JsonArray());

            apiClient.reportClanLoot(payload);
            log.debug("[Birdhouse] Clan clue reported: {}", clueType);
        }
    }
}

package com.thebirdhouse.plugin;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Clue Trail support for the clue sources RuneLite's loot tracker cannot see.
 *
 * Every loot event the tracker emits is anchored to an NPC death, a player kill, the
 * pickpocket message, or a menu click on one of an explicit list of containers. Two ways of
 * winning a clue fall outside all of that and so were invisible to the backend:
 *
 *   - Impling jars. Catching an impling into a jar loots nothing, and opening the jar later
 *     is a plain inventory interaction with no handler. Only a no-jar catch, which loots
 *     immediately as NPC loot, was ever reported. That left honest jarred catches uncounted
 *     while making jars bought off the Grand Exchange indistinguishable from hunted ones.
 *   - Skilling. Mining, Fishing and Woodcutting emit no loot events whatsoever, so a scroll
 *     box, geode, bottle or nest simply materialises in the inventory unannounced.
 *
 * Both are recovered here by diffing the inventory, and both are pinned to something the
 * player demonstrably did — a catch message, or gathering experience in the same tick.
 *
 * Ground pickups are deliberately never credited, which is what keeps this honest. Monster
 * drops land on the floor and enter the inventory via Take, so ignoring takes prevents
 * paying twice for a drop the loot tracker already reported, and stops the obvious exploit
 * of dropping a scroll box and picking it back up for unlimited credits.
 *
 * Everything here is scoped to Clue Trail rooms; other game types are untouched.
 */
@Slf4j
@Singleton
public class ClueTracker {

    private static final String SPIRE_GAME_TYPE = "spire";

    // "You manage to catch the impling and squeeze it into a jar." The other catch message
    // ("...and acquire some loot") is the no-jar case, which arrives as NPC loot instead.
    private static final Pattern JAR_CATCH_MESSAGE = Pattern.compile(
        "you manage to catch the impling and squeeze it into a jar", Pattern.CASE_INSENSITIVE
    );

    // "Eclectic impling jar" -> "Eclectic impling". Empty jars carry no impling name and so
    // never match, which is what we want: an empty jar is not a catch.
    private static final Pattern JAR_ITEM = Pattern.compile("^(.*impling) jar$", Pattern.CASE_INSENSITIVE);

    private static final String TIERS = "beginner|easy|medium|hard|elite|master";

    // What a jar yields: a scroll box after X Marks the Spot, a bare clue scroll before it.
    private static final Pattern JAR_CLUE = Pattern.compile(
        "^(?:clue scroll|scroll box) \\((" + TIERS + ")\\)$", Pattern.CASE_INSENSITIVE
    );

    // What skilling yields. Bare clue scrolls are excluded on purpose: a scroll appearing
    // means a container was opened, which must not pay a second time, and opening one that
    // was banked before the event must never pay at all.
    private static final Pattern SKILLING_CONTAINER = Pattern.compile(
        "^(?:scroll box|clue geode|clue bottle|clue nest) \\((" + TIERS + ")\\)$", Pattern.CASE_INSENSITIVE
    );

    /**
     * Skills whose experience vouches for a container appearing out of nowhere.
     *
     * Sailing is here for clue turtles, an ocean encounter that hands over a clue directly
     * and which the loot tracker knows nothing about. Shipwreck salvaging does not need it —
     * the tracker has a handler for the "you sort through the ... salvage" message — but its
     * loot lands in the inventory alongside Sailing experience all the same, so it would look
     * identical here. The deferred check below is what stops that being counted twice.
     *
     * Hunter is deliberately absent. Catching an impling without a jar loots on the spot, and
     * crediting that against Hunter experience would launder it past the impling gate.
     */
    private static final Set<Skill> GATHERING = EnumSet.of(
        Skill.MINING, Skill.FISHING, Skill.WOODCUTTING, Skill.SAILING
    );

    // Experience arrives on the same tick as the container, but a tick of slack costs
    // nothing and covers the odd ordering difference.
    private static final int GATHER_TICKS = 2;
    private static final int RECENT_TICKS = 1;

    @Inject
    private Client client;

    @Inject
    private ItemManager itemManager;

    @Inject
    private BirdhouseApiClient apiClient;

    @Inject
    private DropMatcher dropMatcher;

    // Last known inventory by item name, so a change can be read as a diff.
    private Map<String, Integer> lastInventory = new HashMap<>();
    // Set by the catch message and consumed by the inventory change in the same tick, which
    // is the only place the impling's type is actually stated.
    private boolean awaitingCatch = false;

    private int lastGatherTick = Integer.MIN_VALUE;
    private Skill lastGatherSkill = null;
    private int lastTakeTick = Integer.MIN_VALUE;
    private int lastLootTick = Integer.MIN_VALUE;
    private Set<String> lastLootItems = new HashSet<>();

    private String pendingClue = null;
    private Skill pendingSkill = null;
    private int pendingTick = Integer.MIN_VALUE;

    public void reset() {
        lastInventory = new HashMap<>();
        awaitingCatch = false;
        lastGatherTick = Integer.MIN_VALUE;
        lastGatherSkill = null;
        lastTakeTick = Integer.MIN_VALUE;
        lastLootTick = Integer.MIN_VALUE;
        lastLootItems = new HashSet<>();
        pendingClue = null;
        pendingSkill = null;
        pendingTick = Integer.MIN_VALUE;
    }

    private boolean inClueTrailRoom() {
        BoardData board = dropMatcher.getActiveBoard();
        return board != null && SPIRE_GAME_TYPE.equals(board.getGameType())
            && !Boolean.FALSE.equals(board.getStarted())
            && !dropMatcher.isEventOver();
    }

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        if (!inClueTrailRoom()) return;
        if (JAR_CATCH_MESSAGE.matcher(event.getMessage()).find()) {
            // The message names no impling, so the type is read from the jar that appears.
            awaitingCatch = true;
        }
    }

    @Subscribe
    public void onStatChanged(StatChanged event) {
        if (GATHERING.contains(event.getSkill())) {
            lastGatherTick = client.getTickCount();
            lastGatherSkill = event.getSkill();
        }
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event) {
        String option = event.getMenuOption();
        if ("Take".equals(option) || "Take-all".equals(option)) {
            lastTakeTick = client.getTickCount();
        }
    }

    /** Remembers what the loot tracker already reported, so it is never paid for twice. */
    @Subscribe
    public void onLootReceived(LootReceived event) {
        lastLootTick = client.getTickCount();
        lastLootItems = new HashSet<>();
        for (ItemStack stack : event.getItems()) {
            String name = itemName(stack.getId());
            if (name != null) lastLootItems.add(name.toLowerCase());
        }
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event) {
        if (event.getContainerId() != InventoryID.INV) return;

        Map<String, Integer> current = snapshot(event.getItemContainer());
        Map<String, Integer> previous = lastInventory;
        lastInventory = current;

        if (!inClueTrailRoom()) return;

        if (awaitingCatch) {
            awaitingCatch = false;
            String jarred = firstGained(previous, current, JAR_ITEM);
            if (jarred != null) {
                log.info("[Birdhouse] Impling caught into a jar: {}", jarred);
                apiClient.reportImplingCatch(dropMatcher.getActiveRoomCode(), jarred, 1);
            }
        }

        String openedJar = firstLost(previous, current, JAR_ITEM);
        if (openedJar != null) {
            String clue = firstGainedMatching(previous, current, JAR_CLUE);
            if (clue != null) {
                // Tagged as a jar so the backend can require a recorded catch, which is what
                // separates a night of hunting from a stack of bought jars.
                log.info("[Birdhouse] Clue from impling jar: {} from {}", clue, openedJar);
                submitClue(openedJar + " (jar)", clue, JAR_CLUE);
            }
            // A jar was consumed, so this change is accounted for and is not a skilling find.
            return;
        }

        String gathered = firstGainedMatching(previous, current, SKILLING_CONTAINER);
        if (gathered == null) return;

        int tick = client.getTickCount();
        if (tick - lastGatherTick > GATHER_TICKS) {
            // No gathering experience just now, so this came from a bank, a trade, a reward
            // interface or an item reclaim rather than from a rock, a fish, a tree or the sea.
            return;
        }
        if (tick - lastTakeTick <= RECENT_TICKS) {
            log.debug("[Birdhouse] Ignoring '{}' picked up off the ground", gathered);
            return;
        }

        // Held for a tick rather than submitted here. The loot tracker reports from this same
        // inventory change, and the order two subscribers run in is not defined, so checking
        // for a duplicate now would be a coin flip — which matters for shipwreck salvaging,
        // where the tracker does report the clue and this would otherwise double it.
        pendingClue = gathered;
        pendingSkill = lastGatherSkill;
        pendingTick = tick;
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        if (pendingClue == null) return;
        int now = client.getTickCount();
        if (now == pendingTick) return;

        String clue = pendingClue;
        Skill skill = pendingSkill;
        int found = pendingTick;
        pendingClue = null;
        pendingSkill = null;

        if (!inClueTrailRoom()) return;
        if (lastLootTick >= found - RECENT_TICKS && lastLootItems.contains(clue.toLowerCase())) {
            log.debug("[Birdhouse] '{}' already reported by the loot tracker", clue);
            return;
        }

        String source = skill == null ? "Skilling" : label(skill);
        log.info("[Birdhouse] Clue from {}: {}", source, clue);
        submitClue(source, clue, SKILLING_CONTAINER);
    }

    private static String label(Skill skill) {
        String name = skill.getName();
        if (name == null || name.isEmpty()) return "Skilling";
        return Character.toUpperCase(name.charAt(0)) + name.substring(1).toLowerCase();
    }

    private String itemName(int itemId) {
        try {
            ItemComposition comp = itemManager.getItemComposition(itemId);
            return comp == null ? null : comp.getName();
        } catch (Exception e) {
            return null;
        }
    }

    private Map<String, Integer> snapshot(ItemContainer container) {
        Map<String, Integer> counts = new HashMap<>();
        if (container == null) return counts;
        for (Item item : container.getItems()) {
            if (item == null || item.getId() < 0) continue;
            String name = itemName(item.getId());
            if (name == null || name.isEmpty()) continue;
            counts.merge(name, Math.max(1, item.getQuantity()), Integer::sum);
        }
        return counts;
    }

    /** First item gained whose name matches, returning capture group 1. */
    private String firstGained(Map<String, Integer> before, Map<String, Integer> after, Pattern pattern) {
        for (Map.Entry<String, Integer> e : after.entrySet()) {
            if (e.getValue() <= before.getOrDefault(e.getKey(), 0)) continue;
            Matcher m = pattern.matcher(e.getKey());
            if (m.matches()) return m.group(1);
        }
        return null;
    }

    /** First item gained whose name matches, returning the whole item name. */
    private String firstGainedMatching(Map<String, Integer> before, Map<String, Integer> after, Pattern pattern) {
        for (Map.Entry<String, Integer> e : after.entrySet()) {
            if (e.getValue() <= before.getOrDefault(e.getKey(), 0)) continue;
            if (pattern.matcher(e.getKey()).matches()) return e.getKey();
        }
        return null;
    }

    private String firstLost(Map<String, Integer> before, Map<String, Integer> after, Pattern pattern) {
        for (Map.Entry<String, Integer> e : before.entrySet()) {
            if (e.getValue() <= after.getOrDefault(e.getKey(), 0)) continue;
            Matcher m = pattern.matcher(e.getKey());
            if (m.matches()) return m.group(1);
        }
        return null;
    }

    private void submitClue(String source, String clueName, Pattern tierPattern) {
        String roomCode = dropMatcher.getActiveRoomCode();
        if (roomCode == null || roomCode.isEmpty()) return;
        Matcher m = tierPattern.matcher(clueName);
        if (!m.matches()) return;
        String tier = m.group(1).toLowerCase();

        ProofPayload payload = new ProofPayload();
        payload.setRoomCode(roomCode);
        payload.setPlayerName(client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : null);
        payload.setTileKey("spire~key~" + tier);
        payload.setTileName(clueName);
        payload.setGameType(SPIRE_GAME_TYPE);
        payload.setItemName(clueName);
        payload.setNpcName(source);
        payload.setQuantity(1);
        payload.setTimestamp(System.currentTimeMillis());

        // No screenshot: an inventory change is not proof of anything, and the backend gates
        // these on the catch counter and the gathering anchor rather than on an image.
        apiClient.submitProof(payload, null);
    }
}

package com.thebirdhouse.plugin;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Matches received drops against the player's active board tiles.
 * When a match is found, triggers proof submission.
 */
@Slf4j
@Singleton
public class DropMatcher {

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private ItemManager itemManager;

    @Inject
    private BirdhouseApiClient apiClient;

    @Inject
    private BirdhouseConfig config;

    @Inject
    private ScreenshotHelper screenshotHelper;

    @Inject
    private BirdhouseOverlay overlay;

    private BoardData activeBoard;
    private String activeRoomCode;

    /**
     * Tile keys the server has confirmed are counting kills against a single proof.
     *
     * Only the first kill on such a tile keeps a screenshot, so once a tile is in here
     * the rest are submitted without one. Held per room and rebuilt from the server's
     * answers, so a stale entry costs at most one saved screenshot and never a lost
     * proof. Written from HTTP callback threads and read from the client thread.
     */
    private final Set<String> tallyTiles = ConcurrentHashMap.newKeySet();

    public BoardData getActiveBoard() {
        return activeBoard;
    }

    public void updateBoard(BoardData board) {
        if (board != null) {
            this.activeBoard = board;
            log.info("[Birdhouse] Board updated: {} tiles, gameType={}", board.getTiles() != null ? board.getTiles().size() : 0, board.getGameType());
        }
    }

    public void setActiveRoomCode(String roomCode) {
        // Tile keys are only unique within a room, so what was a tally in the last one
        // could silently suppress the first screenshot of a tile in the next.
        if (roomCode == null || !roomCode.equals(this.activeRoomCode)) {
            tallyTiles.clear();
        }
        this.activeRoomCode = roomCode;
    }

    public String getActiveRoomCode() {
        return activeRoomCode;
    }

    /**
     * Whether the tracked event has finished (deadline passed or host closed it).
     *
     * A room code lives in plugin config, so it outlives the event: once a bingo ends,
     * nothing clears it and every later kill would otherwise still be matched, uploaded
     * with a screenshot, and rejected by the server. That is pure waste which persists
     * for as long as the player leaves the plugin installed, so the submitting paths all
     * gate on this.
     *
     * Absent flag means live: an older server omits it, and going quiet against one
     * would break submission entirely rather than merely waste a request.
     */
    public boolean isEventOver() {
        BoardData board = activeBoard;
        return board != null && Boolean.FALSE.equals(board.getActive());
    }

    public void loadActiveBoard(String roomCode) {
        if (roomCode == null || roomCode.isEmpty()) {
            log.warn("[Birdhouse] loadActiveBoard called with empty roomCode");
            return;
        }
        setActiveRoomCode(roomCode);
        log.info("[Birdhouse] Loading board for room: {}", roomCode);
        apiClient.fetchBoard(roomCode).thenAccept(board -> {
            if (board != null) {
                this.activeBoard = board;
                log.info("[Birdhouse] Board loaded for room {}: {} tiles, gameType={}", roomCode, board.getTiles().size(), board.getGameType());
                if (board.getTiles().size() > 0) {
                    BoardTile first = board.getTiles().get(0);
                    log.info("[Birdhouse]   First tile: name='{}', matchName='{}', matchItems={}", first.getName(), first.getMatchName(), first.getMatchItems());
                }
            } else {
                log.warn("[Birdhouse] Board fetch returned null for room {}", roomCode);
            }
        });
    }

    @Subscribe
    public void onLootReceived(LootReceived event) {
        if (!config.autoSubmitDrops()) {
            // Impostor tasks ARE the game. Auto-submit is a convenience for bingo;
            // switching it off must not silently freeze the crew's bar.
            if (activeBoard == null || !"impostor".equals(activeBoard.getGameType())) {
                log.info("[Birdhouse] Auto-submit disabled in config, skipping loot event");
                return;
            }
        }
        if (activeBoard == null) {
            log.info("[Birdhouse] No active board loaded, skipping loot event");
            return;
        }
        if (isEventOver()) {
            log.debug("[Birdhouse] Event {} has ended, not matching drops", activeRoomCode);
            return;
        }

        String sourceName = event.getName();

        log.info("[Birdhouse] Loot received from '{}' (type={}): {} items", sourceName, event.getType(), event.getItems().size());

        // One drop, however many items are in it. A kill-count tile counts kills but this
        // loop submits per item, so the backend needs to know which submissions shared a
        // kill; see ProofPayload#killId.
        String killId = UUID.randomUUID().toString();

        for (ItemStack itemStack : event.getItems()) {
            ItemComposition itemComp = itemManager.getItemComposition(itemStack.getId());
            String itemName = itemComp.getName();
            int quantity = itemStack.getQuantity();

            log.info("[Birdhouse]   Item: '{}' x{}", itemName, quantity);

            List<TileMatch> matches = findMatches(sourceName, itemName, quantity);
            if (matches.isEmpty()) {
                log.info("[Birdhouse]   No tile match for '{}'", itemName);
            } else {
                TileMatch match = matches.get(0);
                log.info("[Birdhouse]   MATCH! tile='{}' key={} (of {} matching tiles)", match.getTileName(), match.getTileKey(), matches.size());
                // Drops don't count until the board is locked / event has started.
                // Warn the player to screenshot so the drop isn't lost (older servers omit
                // the flag → treat as started and submit as before).
                if (Boolean.FALSE.equals(activeBoard.getStarted())) {
                    log.info("[Birdhouse]   Event not started — not submitting '{}', warning player to screenshot", itemName);
                    warnNotStarted(match, itemName);
                } else {
                    submitMatch(match, sourceName, itemName, quantity, itemStack.getId(), killId);
                }
            }
        }
    }

    /**
     * An item that reached the inventory without a loot event — see {@link GatheredTracker}.
     *
     * Routed through the matching and submission path a drop takes rather than a parallel
     * one, so every per-game-type rule, quantity cap and not-started warning applies
     * identically. {@code source} names the activity ("Mining") where a drop would name
     * the NPC; a kill-count tile matches on that field and so can never be satisfied by
     * one of these, which is correct.
     */
    public void handleGatheredItem(String source, String itemName, int itemId, int quantity) {
        if (!config.autoSubmitDrops()) return;
        if (activeBoard == null || isEventOver()) return;

        List<TileMatch> matches = findMatches(source, itemName, quantity);
        if (matches.isEmpty()) return;

        TileMatch match = matches.get(0);
        if (Boolean.FALSE.equals(activeBoard.getStarted())) {
            warnNotStarted(match, itemName);
            return;
        }
        // No killId: nothing was killed, so there are no sibling rolls to collapse.
        submitMatch(match, source, itemName, quantity, itemId, null);
    }

    /**
     * A kill the game announced in chat — see {@link KillCountTracker}.
     *
     * Only kill-count tiles are eligible, so this cannot be reused to satisfy a tile that
     * wants a specific item. There is no drop to name, so the boss stands in as the item
     * for the log line; the server forces a quantity of one on these regardless.
     */
    public void handleKillCount(String bossName) {
        if (!config.autoSubmitDrops()) return;
        if (activeBoard == null || isEventOver()) return;
        if (bossName == null || bossName.isEmpty()) return;

        List<TileMatch> matches = findKillCountMatches(bossName);
        if (matches.isEmpty()) return;

        TileMatch match = matches.get(0);
        if (Boolean.FALSE.equals(activeBoard.getStarted())) {
            warnNotStarted(match, bossName);
            return;
        }
        // One announcement is one kill, so this is the only submission carrying this id.
        submitMatch(match, bossName, bossName, 1, -1, UUID.randomUUID().toString());
    }

    /**
     * Tiles still accepting submissions.
     *
     * Shared by every matching path so that a tile which is finished, fogged, not the one
     * the piece is standing on, or otherwise closed stays closed no matter which signal
     * arrived.
     */
    private boolean tileOpen(BoardTile tile) {
        if (tile.isCompleted()) return false;
        if (tile.getSpecial() != null) return false;

        // Skip tiles that already have enough submissions (even if not yet marked complete)
        if (tile.getQuantity() > 1 && tile.getCurrentQty() >= tile.getQuantity()) return false;

        // For battleship, skip tiles that already have an attack result (hit, miss, or sunk)
        if ("battleship".equals(tile.getGameType()) && tile.getAttackResult() != null) return false;

        // For tile race, only match the tile the player is currently on
        if ("tilerace".equals(tile.getGameType()) && !tile.isCurrent()) return false;

        // For chip drop, only match available (unlocked) tiles
        if ("chipdrop".equals(tile.getGameType()) && !tile.isAvailable()) return false;

        return true;
    }

    /**
     * Kill-count tiles naming this boss.
     *
     * Deliberately not routed through {@link #matchesTile}, which would also accept a
     * tile whose wanted item happens to share the boss's name. A killcount message is
     * proof of a kill and nothing else.
     */
    private List<TileMatch> findKillCountMatches(String bossName) {
        List<TileMatch> matches = new ArrayList<>();
        if (activeBoard == null || activeBoard.getTiles() == null) {
            return matches;
        }

        String boss = bossName.toLowerCase().trim();
        for (BoardTile tile : activeBoard.getTiles()) {
            if (!tileOpen(tile)) continue;
            if (!tile.isAnyUnique()) continue;

            String target = tile.getMatchName();
            if (target == null || !target.toLowerCase().trim().equals(boss)) continue;

            matches.add(new TileMatch(tile.getKey(), tile.getName(), tile.getGameType(), tile.getTerritoryName()));
        }
        return matches;
    }

    private List<TileMatch> findMatches(String npcName, String itemName, int quantity) {
        List<TileMatch> matches = new ArrayList<>();
        if (activeBoard == null || activeBoard.getTiles() == null) {
            return matches;
        }

        for (BoardTile tile : activeBoard.getTiles()) {
            if (!tileOpen(tile)) continue;

            if (matchesTile(tile, npcName, itemName)) {
                matches.add(new TileMatch(tile.getKey(), tile.getName(), tile.getGameType(), tile.getTerritoryName()));
            }
        }
        return matches;
    }

    private boolean matchesTile(BoardTile tile, String npcName, String itemName) {
        // Check matchItems list first (generic tiles / presets / collect-all)
        List<String> matchItems = tile.getMatchItems();
        if (matchItems != null && !matchItems.isEmpty()) {
            String item = itemName.toLowerCase();
            for (String acceptable : matchItems) {
                if (acceptable != null && acceptable.toLowerCase().equals(item)) {
                    // For "collect all" tiles, only stop once every slot that accepts this
                    // item is already full (so x4 / OR-alternative slots keep matching).
                    if (tile.isMatchAll() && itemAlreadySatisfied(tile, item)) {
                        log.debug("[Birdhouse]     '{}' no longer needed for collect-all tile '{}'", itemName, tile.getName());
                        return false;
                    }
                    log.debug("[Birdhouse]     matchItems hit: '{}' in list for tile '{}'", itemName, tile.getName());
                    return true;
                }
            }
            return false;
        }

        String matchTarget = tile.getMatchName();
        if (matchTarget == null || matchTarget.isEmpty()) {
            return false;
        }

        String target = matchTarget.toLowerCase();
        String item = itemName.toLowerCase();
        String npc = npcName != null ? npcName.toLowerCase() : "";

        // Exact item name match
        if (target.equals(item)) return true;

        // "Boss - Item" format (e.g. "Zulrah - Tanzanite fang")
        if (target.contains(" - ")) {
            String[] parts = target.split(" - ", 2);
            if (npc.equals(parts[0].trim()) && item.equals(parts[1].trim())) return true;
        }

        // Boss name only match (any unique from this boss)
        if (target.equals(npc) && tile.isAnyUnique()) return true;

        return false;
    }

    // For a collect-all tile: is this item no longer needed? True only when every slot
    // that accepts the item has already reached its required quantity.
    private boolean itemAlreadySatisfied(BoardTile tile, String itemLower) {
        java.util.Map<String, Integer> counts = tile.getCollectedCounts();

        // Preferred path: slot (OR-group) definitions.
        if (tile.getMatchGroups() != null && !tile.getMatchGroups().isEmpty()) {
            for (BoardTile.MatchGroup g : tile.getMatchGroups()) {
                if (g.getItems() == null) continue;
                boolean contains = false;
                for (String it : g.getItems()) {
                    if (it != null && it.toLowerCase().equals(itemLower)) { contains = true; break; }
                }
                if (!contains) continue;
                int need = g.getQty() > 0 ? g.getQty() : 1;
                int have = 0;
                if (counts != null) {
                    for (String it : g.getItems()) {
                        Integer c = it == null ? null : counts.get(it.toLowerCase());
                        if (c != null) have += c;
                    }
                }
                if (have < need) return false; // this slot still needs the item
            }
            return true;
        }

        // Fallback: per-item quantities (flat collect-all tiles / older servers).
        int need = 1;
        if (tile.getItemQuantities() != null) {
            Integer q = tile.getItemQuantities().get(itemLower);
            if (q != null && q > 0) need = q;
        }
        int have = 0;
        if (counts != null) {
            Integer c = counts.get(itemLower);
            if (c != null) have = c;
        }
        if (counts == null && tile.getCollectedItems() != null) {
            for (String c : tile.getCollectedItems()) {
                if (c != null && c.toLowerCase().equals(itemLower)) { have = Math.max(have, 1); break; }
            }
        }
        return have >= need;
    }

    private void warnNotStarted(TileMatch match, String itemName) {
        // Straight through rather than via notifyInGame: this runs inside the loot
        // handler, so it is already on the client thread, and a warning that a drop was
        // not submitted should not be silenced by the submit-confirmation setting.
        client.addChatMessage(
            ChatMessageType.GAMEMESSAGE,
            "",
            "[Birdhouse] Event not started yet \u2014 screenshot this drop (" + itemName
                + ") so it can be submitted after the board is locked!",
            ""
        );
        overlay.setLastMatch(match.getTileName() + " (not started \u2014 screenshot!)", itemName);
    }

    /** @param killId the kill these items came from, or null when this is not a kill. */
    private void submitMatch(TileMatch match, String npcName, String itemName, int quantity, int itemId, String killId) {
        String playerName = client.getLocalPlayer().getName();

        ProofPayload payload = new ProofPayload();
        payload.setRoomCode(activeRoomCode);
        payload.setPlayerName(playerName);
        payload.setTileKey(match.getTileKey());
        payload.setTileName(match.getTileName());
        payload.setTerritoryName(match.getTerritoryName());
        payload.setGameType(match.getGameType());
        payload.setItemName(itemName);
        payload.setNpcName(npcName);
        payload.setQuantity(quantity);
        payload.setItemId(itemId);
        payload.setValue(stackValue(itemId, quantity));
        payload.setTimestamp(System.currentTimeMillis());
        payload.setKillId(killId);

        // A tile counting kills keeps one proof and counts up, so only the first kill's
        // screenshot is ever stored. Capturing the rest is pure waste, and on something
        // cannoned down several to the tick it is waste at a few frames a second, each
        // encoded and uploaded. The server says which tiles are running a tally, so this
        // needs no opinion about what a tile means.
        if (!config.includeScreenshot()) {
            log.info("[Birdhouse] Screenshots disabled in config, submitting without image");
            doSubmit(payload, null, match, itemName);
        } else if (tallyTiles.contains(match.getTileKey())) {
            log.debug("[Birdhouse] '{}' is counting kills; skipping the screenshot", match.getTileName());
            doSubmit(payload, null, match, itemName);
        } else {
            screenshotHelper.captureAsync(screenshot -> {
                if (screenshot == null || screenshot.length == 0) {
                    log.warn("[Birdhouse] Screenshot capture returned null/empty for '{}' - submitting without image", match.getTileName());
                }
                doSubmit(payload, screenshot, match, itemName);
            });
        }

        log.info("Drop matched tile '{}': {} from {}", match.getTileName(), itemName, npcName);
    }

    /** Grand Exchange value of a whole stack; 0 for untradeables and unknown ids. */
    private long stackValue(int itemId, int quantity) {
        // A kill credit has no item behind it, so there is nothing to price.
        if (itemId <= 0) return 0;
        try {
            long price = itemManager.getItemPrice(itemId);
            return Math.max(0L, price) * Math.max(0, quantity);
        } catch (Exception e) {
            return 0;
        }
    }

    private void doSubmit(ProofPayload payload, byte[] screenshot, TileMatch match, String itemName) {
        log.info("[Birdhouse] Submitting proof: tile='{}', item='{}', screenshot={} bytes", match.getTileName(), itemName, screenshot != null ? screenshot.length : 0);
        apiClient.submitProof(payload, screenshot).thenAccept(result -> {
            if (result.isOk()) {
                log.info("[Birdhouse] Proof submitted successfully for '{}'", match.getTileName());
                if (result.getKills() > 0) {
                    // The tile is banking kills against one proof, so from here it needs
                    // no more pictures. Kills already in flight may take a few more
                    // before this lands, which costs nothing but a handful of uploads.
                    tallyTiles.add(match.getTileKey());
                }
                if (!result.isDuplicate()) {
                    notifyInGame("[Birdhouse] Proof submitted: " + match.getTileName() + " (" + itemName + ")");
                }
                overlay.setLastMatch(match.getTileName(), itemName);
            } else {
                log.warn("[Birdhouse] Proof submission FAILED for '{}': {}", match.getTileName(), result.getMessage());
            }
        });
    }

    /**
     * Confirmation in the game chat that a drop went in.
     *
     * Has to be handed to the client thread. This runs in the submit callback, on an
     * HTTP thread, and addChatMessage from off the client thread does nothing — which
     * is why an automatic submission stayed silent while a manual one from the board
     * window, which already routed through clientThread, printed its line.
     */
    private void notifyInGame(String message) {
        if (!config.notifyOnSubmit()) {
            return;
        }
        clientThread.invoke(() -> client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, ""));
    }
}

package com.thebirdhouse.plugin;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Board items that arrive without a loot event.
 *
 * Auto-submission is driven entirely by RuneLite's loot tracker, which only reports NPC
 * kills and an explicit list of loot events — chests, reward crates, raid and minigame
 * pools. Everything a player gathers is invisible to it: a stardust mined off a shooting
 * star, a Molch pearl from aerial fishing, a salamander out of a net trap and an agility
 * ticket from the arena all simply materialise in the inventory. Tiles asking for those
 * could never complete on their own, and players reasonably read the silence as the board
 * being broken rather than as the drop being untrackable.
 *
 * The gap is closed the same way {@link ClueTracker} closes it for clue containers: diff
 * the inventory, and only credit a gain that is pinned to something the player
 * demonstrably did. Here the anchor is gathering experience in the same handful of ticks.
 * That single rule is what keeps this honest, because the ways of acquiring an item
 * dishonestly — withdrawing it from a bank, buying it off the Grand Exchange or from a
 * shop, taking it in a trade — award no experience at all and so can never clear it.
 *
 * Ground pickups are refused for the two reasons they are refused in ClueTracker: a
 * monster drop reaches the inventory via Take and would otherwise be paid for twice, and
 * without the rule a player could drop a board item and pick it back up for as many
 * credits as they had patience for.
 *
 * Nothing here decides what a gain is worth. Matching, per-game-type rules, quantity caps
 * and the not-started warning all belong to {@link DropMatcher}, and a gathered item is
 * handed to exactly the same path a drop takes.
 */
@Slf4j
@Singleton
public class GatheredTracker {

    // ClueTracker owns the inventory diff for Clue Trail rooms, including its own rules
    // about jars and which containers may be credited. Running both over one room would
    // mean two trackers bidding on the same inventory change.
    private static final String CLUE_TRAIL_GAME_TYPE = "spire";

    /**
     * Skills whose experience vouches for an item appearing out of nowhere.
     *
     * Gathering skills are the point of the exercise. The production skills are here
     * because a board tile is just as legitimately satisfied by making the item as by
     * finding it, and because their experience is equally impossible to fake through a
     * bank or the Grand Exchange.
     *
     * Combat is deliberately absent. Loot from a kill is the loot tracker's job, and
     * accepting combat experience as an anchor would credit inventory changes that happen
     * to coincide with a fight without adding a single tile the tracker cannot already
     * see.
     */
    private static final Set<Skill> EARNING = EnumSet.of(
        Skill.MINING, Skill.FISHING, Skill.WOODCUTTING, Skill.HUNTER,
        Skill.FARMING, Skill.THIEVING, Skill.AGILITY, Skill.FIREMAKING,
        Skill.RUNECRAFT, Skill.HERBLORE, Skill.CRAFTING, Skill.CONSTRUCTION,
        Skill.SAILING
    );

    /**
     * How long an experience drop vouches for.
     *
     * Wider than the tick ClueTracker allows itself, because that one is matching a
     * container against the gather that produced it, whereas an activity reward can lag
     * the experience that earned it — an arena ticket is dispensed around the tag, not on
     * it. Widening costs nothing in honesty: the acquisitions this is meant to exclude
     * award no experience whatsoever, so no window length lets them through.
     */
    private static final int ANCHOR_TICKS = 5;

    private static final int RECENT_TICKS = 1;

    /**
     * Containers whose movement means an item changed hands rather than being gathered.
     *
     * A withdrawal, a completed trade and a collected offer each move one of these in the
     * same tick as the inventory, which is far more direct evidence than the experience
     * anchor ever was. Shops are left out deliberately: the game has a separate container
     * per shop and there are several hundred of them, and a shop is not somewhere anyone
     * trains, so the exposure does not justify guessing at that list.
     */
    private static final Set<Integer> VAULTS;

    static {
        Set<Integer> vaults = new HashSet<>(Arrays.asList(
            InventoryID.BANK, InventoryID.TRADEOFFER, InventoryID.DUELOFFER
        ));
        vaults.addAll(Arrays.asList(
            InventoryID.GE_OFFER_0, InventoryID.GE_OFFER_1, InventoryID.GE_OFFER_2,
            InventoryID.GE_OFFER_3, InventoryID.GE_OFFER_4, InventoryID.GE_OFFER_5,
            InventoryID.GE_OFFER_6, InventoryID.GE_OFFER_7
        ));
        VAULTS = vaults;
    }

    @Inject
    private Client client;

    @Inject
    private ItemManager itemManager;

    @Inject
    private BirdhouseConfig config;

    @Inject
    private DropMatcher dropMatcher;

    /** Last known inventory as item id to quantity, so a change can be read as a diff. */
    private Map<Integer, Integer> lastInventory = new HashMap<>();

    /**
     * Whether a baseline has been taken. The first container change after a login or a
     * reset reports a full inventory against an empty map, which is every item you are
     * carrying looking like it was just acquired.
     */
    private boolean primed = false;

    private int lastEarnTick = Integer.MIN_VALUE;
    private Skill lastEarnSkill = null;

    /**
     * Experience last seen per skill, so a stat change can be read as earning or not.
     *
     * A drained level healing back reports as a stat change with the experience sitting
     * exactly where it was. Karil drains Agility, so a Barrows trip alone fires one of
     * those every time a point comes back.
     */
    private final Map<Skill, Integer> lastXp = new EnumMap<>(Skill.class);
    private int lastTakeTick = Integer.MIN_VALUE;

    /**
     * When a bank, trade or shop last moved, so goods changing hands can be told from a
     * gather.
     *
     * The experience anchor was meant to carry this on its own, on the reasoning that a
     * withdrawal earns none. That holds for mining and fishing, but Herblore, Crafting,
     * Construction and Runecraft are trained standing at a bank, so their experience is
     * arriving continuously at the exact moment withdrawals happen.
     */
    private int lastVaultTick = Integer.MIN_VALUE;
    private int lastLootTick = Integer.MIN_VALUE;
    private Set<String> lastLootItems = new HashSet<>();

    private final List<Gain> pending = new ArrayList<>();
    private int pendingTick = Integer.MIN_VALUE;
    private Skill pendingSkill = null;

    /** An item that appeared in the inventory. */
    static final class Gain {
        final int itemId;
        final String name;
        final int quantity;

        Gain(int itemId, String name, int quantity) {
            this.itemId = itemId;
            this.name = name;
            this.quantity = quantity;
        }
    }

    public void reset() {
        lastInventory = new HashMap<>();
        primed = false;
        lastEarnTick = Integer.MIN_VALUE;
        lastEarnSkill = null;
        lastXp.clear();
        lastTakeTick = Integer.MIN_VALUE;
        lastVaultTick = Integer.MIN_VALUE;
        lastLootTick = Integer.MIN_VALUE;
        lastLootItems = new HashSet<>();
        pending.clear();
        pendingTick = Integer.MIN_VALUE;
        pendingSkill = null;
    }

    private boolean inTrackedRoom() {
        if (!config.autoSubmitGathered()) return false;
        BoardData board = dropMatcher.getActiveBoard();
        return board != null
            && !CLUE_TRAIL_GAME_TYPE.equals(board.getGameType())
            && !dropMatcher.isEventOver();
    }

    @Subscribe
    public void onStatChanged(StatChanged event) {
        Skill skill = event.getSkill();
        if (!EARNING.contains(skill)) return;
        Integer seen = lastXp.put(skill, event.getXp());
        if (!earned(seen, event.getXp())) return;
        lastEarnTick = client.getTickCount();
        lastEarnSkill = skill;
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event) {
        String option = event.getMenuOption();
        if ("Take".equals(option) || "Take-all".equals(option)) {
            lastTakeTick = client.getTickCount();
        }
    }

    /** Remembers what the loot tracker already reported, so it is never paid for twice. */
    @Subscribe
    public void onLootReceived(LootReceived event) {
        lastLootTick = client.getTickCount();
        lastLootItems = new HashSet<>();
        for (ItemStack stack : event.getItems()) {
            String name = itemName(stack.getId());
            if (name != null) lastLootItems.add(name.toLowerCase());
        }
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event) {
        if (VAULTS.contains(event.getContainerId())) {
            lastVaultTick = client.getTickCount();
            return;
        }
        if (event.getContainerId() != InventoryID.INV) return;

        Map<Integer, Integer> current = snapshot(event.getItemContainer());
        Map<Integer, Integer> previous = lastInventory;
        lastInventory = current;

        if (!primed) {
            primed = true;
            return;
        }
        if (!inTrackedRoom()) return;

        int tick = client.getTickCount();
        if (!anchored(tick, lastEarnTick)) {
            // Nothing was being earned just now, so this came out of a bank, a shop, the
            // Grand Exchange, a trade or a reclaim rather than off a rock, a tree or a trap.
            return;
        }
        if (fromGround(tick, lastTakeTick)) {
            log.debug("[Birdhouse] Ignoring inventory gain picked up off the ground");
            return;
        }

        List<Gain> gains = gains(previous, current);
        if (gains.isEmpty()) return;

        // Held for a tick rather than submitted here. The loot tracker reports off this
        // same inventory change and the order two subscribers run in is undefined, so
        // asking now whether it has already claimed the item would be a coin flip.
        pending.addAll(gains);
        pendingTick = tick;
        pendingSkill = lastEarnSkill;
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        if (pending.isEmpty()) return;
        if (client.getTickCount() == pendingTick) return;

        List<Gain> due = new ArrayList<>(pending);
        Skill skill = pendingSkill;
        int found = pendingTick;
        pending.clear();
        pendingSkill = null;

        if (!inTrackedRoom()) return;

        // Asked here rather than as the change arrives, for the same reason the loot
        // tracker is: the order two container subscribers run in is undefined, so the
        // bank may not have reported yet at the moment the inventory does.
        if (changedHands(found, lastVaultTick)) {
            log.debug("[Birdhouse] Ignoring inventory gain that came out of a bank, trade or shop");
            return;
        }

        String source = label(skill);
        for (Gain gain : due) {
            if (alreadyReported(gain.name, found, lastLootTick, lastLootItems)) {
                log.debug("[Birdhouse] '{}' already reported by the loot tracker", gain.name);
                continue;
            }
            log.info("[Birdhouse] Gathered {} x{} ({})", gain.name, gain.quantity, source);
            dropMatcher.handleGatheredItem(source, gain.name, gain.itemId, gain.quantity);
        }
    }

    // ── Decisions, kept pure so they can be tested without a client ──────────────

    /**
     * Whether a stat change carried experience, given what the skill last sat at.
     *
     * A stat change on its own says nothing. A drained level healing back, a boost wearing
     * off and the burst that arrives at login all report one with the experience unmoved,
     * and each would otherwise open the window that is supposed to keep bank withdrawals,
     * trades and Grand Exchange collections out. The first sighting of a skill is the
     * baseline rather than a gain, so logging in never vouches for anything.
     */
    static boolean earned(Integer seen, int xp) {
        return seen != null && xp > seen;
    }

    /** Whether experience earned at {@code lastEarnTick} still vouches for {@code tick}. */
    static boolean anchored(int tick, int lastEarnTick) {
        if (lastEarnTick == Integer.MIN_VALUE) return false;
        return tick - lastEarnTick <= ANCHOR_TICKS && tick >= lastEarnTick;
    }

    /**
     * Whether a bank, trade or shop moved close enough to have been where the item came
     * from.
     *
     * This is the guard the experience anchor was assumed to provide and does not, since
     * the production skills are trained at a bank.
     */
    static boolean changedHands(int tick, int lastVaultTick) {
        if (lastVaultTick == Integer.MIN_VALUE) return false;
        return Math.abs(tick - lastVaultTick) <= RECENT_TICKS;
    }

    /** Whether the change is close enough to a Take to have come off the floor. */
    static boolean fromGround(int tick, int lastTakeTick) {
        if (lastTakeTick == Integer.MIN_VALUE) return false;
        return tick - lastTakeTick <= RECENT_TICKS;
    }

    /** Whether the loot tracker has already claimed this item around the same tick. */
    static boolean alreadyReported(String name, int foundTick, int lootTick, Set<String> lootItems) {
        if (name == null || lootItems == null || lootItems.isEmpty()) return false;
        if (lootTick == Integer.MIN_VALUE) return false;
        return lootTick >= foundTick - RECENT_TICKS && lootItems.contains(name.toLowerCase());
    }

    /** Items whose quantity went up, as ids paired with how many appeared. */
    static Map<Integer, Integer> gainedQuantities(Map<Integer, Integer> before, Map<Integer, Integer> after) {
        Map<Integer, Integer> gained = new HashMap<>();
        for (Map.Entry<Integer, Integer> e : after.entrySet()) {
            int delta = e.getValue() - before.getOrDefault(e.getKey(), 0);
            if (delta > 0) gained.put(e.getKey(), delta);
        }
        return gained;
    }

    static String label(Skill skill) {
        if (skill == null) return "Skilling";
        String name = skill.getName();
        if (name == null || name.isEmpty()) return "Skilling";
        return Character.toUpperCase(name.charAt(0)) + name.substring(1).toLowerCase();
    }

    // ── Client-facing helpers ────────────────────────────────────────────────────

    private List<Gain> gains(Map<Integer, Integer> before, Map<Integer, Integer> after) {
        List<Gain> list = new ArrayList<>();
        for (Map.Entry<Integer, Integer> e : gainedQuantities(before, after).entrySet()) {
            String name = itemName(e.getKey());
            if (name == null || name.isEmpty()) continue;
            list.add(new Gain(e.getKey(), name, e.getValue()));
        }
        return list;
    }

    private String itemName(int itemId) {
        try {
            ItemComposition comp = itemManager.getItemComposition(itemId);
            return comp == null ? null : comp.getName();
        } catch (Exception e) {
            return null;
        }
    }

    private Map<Integer, Integer> snapshot(ItemContainer container) {
        Map<Integer, Integer> counts = new HashMap<>();
        if (container == null) return counts;
        for (Item item : container.getItems()) {
            if (item == null || item.getId() < 0) continue;
            counts.merge(item.getId(), Math.max(1, item.getQuantity()), Integer::sum);
        }
        return counts;
    }
}

package com.thebirdhouse.plugin;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOpened;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * In-game verbs for The Impostor: Eliminate, Report body, Cut the lights.
 *
 * Offered only when the position ack or board poll says this player may use them.
 * The server still refuses anything that is not legal.
 */
@Slf4j
@Singleton
public class ImpostorActions {

    private static final String ELIMINATE = "Eliminate";
    private static final String REPORT = "Report body";
    private static final String LIGHTS = "Cut the lights";

    /**
     * Same Chebyshev reach the server uses in {@code canKill}. The side panel and
     * the right-click verb both stop at this number; the server is what actually
     * decides, so a forged click still fails if the pings are farther apart.
     */
    static final int KILL_RANGE_TILES = 8;

    @Inject
    private Client client;

    @Inject
    private ImpostorPositionTracker tracker;

    @Inject
    private BirdhouseApiClient apiClient;

    @Inject
    private DropMatcher dropMatcher;

    @Inject
    private ClientThread clientThread;

    /**
     * Eliminate, Report body and Cut the lights exist only while this client is attached
     * to a live Impostor round. A leftover role from an earlier game must not put those
     * options on a bingo board — or any other mode.
     */
    static boolean commandsAllowed(BoardData board) {
        return commandsAllowed(board, null);
    }

    /**
     * Prefer the phase from the position ack — that arrives within seconds of a deal.
     * The board poll is a minute behind, so gating only on it hid Eliminate for the
     * whole opening of the game.
     */
    static boolean commandsAllowed(BoardData board, String livePhase) {
        if (board == null || !"impostor".equals(board.getGameType())) {
            return false;
        }
        String phase = (livePhase != null && !livePhase.isEmpty()) ? livePhase : board.getPhase();
        return "round".equals(phase);
    }

    @Subscribe
    public void onClientTick(ClientTick event) {
        if (!commandsAllowed(dropMatcher.getActiveBoard(), tracker.getPhase())) {
            return;
        }
        if (!tracker.isBlackout() || tracker.isImpostor() || tracker.isDead()) {
            return;
        }
        maskMenuNames();
    }

    /**
     * Insert an Eliminate per player once the menu is fully built. Gating on PLAYER_FIRST_OPTION
     * missed the verb whenever Follow was not the first player row — Walk here,
     * plugin lookups and a custom left-click all skip that opcode.
     */
    @Subscribe
    public void onMenuOpened(MenuOpened event) {
        if (tracker.isBlackout() && !tracker.isImpostor() && !tracker.isDead()) {
            maskMenuNames();
        }
        if (tracker.isDead() || !tracker.isImpostor()) {
            return;
        }
        if (!commandsAllowed(dropMatcher.getActiveBoard(), tracker.getPhase())) {
            return;
        }
        String room = dropMatcher.getActiveRoomCode();
        if (room == null) {
            return;
        }
        for (String name : otherPlayerNames(event.getMenuEntries())) {
            insert(ELIMINATE, ColorUtil.wrapWithColorTag(name, Color.RED), () ->
                runAction(apiClient.impostorKill(room, name)));
        }
    }

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event) {
        if (tracker.isDead()) {
            return;
        }
        if (!commandsAllowed(dropMatcher.getActiveBoard(), tracker.getPhase())) {
            return;
        }
        String room = dropMatcher.getActiveRoomCode();
        if (room == null) {
            return;
        }

        if (REPORT.equals(event.getOption()) || LIGHTS.equals(event.getOption())
            || ELIMINATE.equals(event.getOption())) {
            return;
        }
        if ("Walk here".equals(event.getOption())) {
            if (tracker.isImpostor()) {
                insert(LIGHTS, "", () -> runAction(apiClient.impostorSabotage(room)));
            }
            WorldPoint tile = WorldPoint.fromScene(
                client.getTopLevelWorldView(),
                event.getActionParam0(),
                event.getActionParam1(),
                client.getTopLevelWorldView().getPlane());
            ImpostorBody body = tracker.bodyNear(tile.getX(), tile.getY(), tile.getPlane(), 8);
            if (body != null) {
                String label = body.getName() == null || body.getName().isEmpty() ? "a body" : body.getName();
                insert(REPORT, "<col=" + Integer.toHexString(Color.RED.getRGB() & 0xffffff) + ">" + label + "</col>",
                    () -> runAction(apiClient.impostorReport(room)));
            }
        }
    }

    private void maskMenuNames() {
        Player me = client.getLocalPlayer();
        String mine = me != null ? Text.removeTags(me.getName()) : null;
        Set<String> others = nearbyNames(me);
        if (others.isEmpty()) {
            return;
        }
        for (MenuEntry entry : client.getMenuEntries()) {
            if (ELIMINATE.equals(entry.getOption()) || REPORT.equals(entry.getOption())
                || LIGHTS.equals(entry.getOption())) {
                continue;
            }
            String raw = Text.removeTags(entry.getTarget());
            if (raw == null || raw.isEmpty() || "???".equals(raw)) {
                continue;
            }
            String core = playerName(raw);
            if (mine != null && mine.equalsIgnoreCase(core)) {
                continue;
            }
            if (namesPlayer(raw, core, others)) {
                entry.setTarget(ColorUtil.wrapWithColorTag("???", Color.WHITE));
            }
        }
    }

    private Set<String> nearbyNames(Player me) {
        Set<String> names = new HashSet<>();
        for (Player other : client.getPlayers()) {
            if (other == null || other == me || other.getName() == null) {
                continue;
            }
            names.add(Text.removeTags(other.getName()).toLowerCase());
        }
        return names;
    }

    static boolean namesPlayer(String raw, String core, Set<String> others) {
        if (core != null && !core.isEmpty() && others.contains(core.toLowerCase())) {
            return true;
        }
        if (raw == null) {
            return false;
        }
        String lower = raw.toLowerCase();
        for (String name : others) {
            if (!name.isEmpty() && lower.contains(name)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Every distinct player under the cursor, in menu order. Taking only the first
     * player row left a stack of crewmates on one tile reachable by whichever name
     * RuneLite happened to list first, with no way to aim at the others. Names are
     * de-duplicated so a player with several rows (Follow, Trade, a plugin lookup)
     * still contributes a single Eliminate.
     */
    private Collection<String> otherPlayerNames(MenuEntry[] entries) {
        if (entries == null) {
            return java.util.Collections.emptyList();
        }
        List<String> targets = new ArrayList<>();
        for (MenuEntry entry : entries) {
            if (entry != null && isPlayerMenu(entry.getType().getId())) {
                targets.add(entry.getTarget());
            }
        }
        Player me = client.getLocalPlayer();
        return distinctOtherNames(targets, me != null ? Text.removeTags(me.getName()) : null);
    }

    /**
     * The filtering half of {@link #otherPlayerNames}, split out so it can be
     * exercised without a live client.
     */
    static Collection<String> distinctOtherNames(List<String> playerTargets, String mine) {
        Set<String> names = new LinkedHashSet<>();
        if (playerTargets == null) {
            return names;
        }
        for (String target : playerTargets) {
            String name = playerName(target);
            if (name.isEmpty() || "???".equals(name)) {
                continue;
            }
            if (mine != null && mine.equalsIgnoreCase(name)) {
                continue;
            }
            names.add(name);
        }
        return names;
    }

    private static boolean isPlayerMenu(int type) {
        return type >= MenuAction.PLAYER_FIRST_OPTION.getId()
            && type <= MenuAction.PLAYER_EIGHTH_OPTION.getId();
    }

    static String playerName(String target) {
        if (target == null) {
            return "";
        }
        return Text.removeTags(target).replaceAll("(?i)\\s*\\(level-?\\d+\\)", "").trim();
    }

    private void insert(String option, String target, Runnable action) {
        MenuEntry entry = client.getMenu().createMenuEntry(-1);
        entry.setOption(option);
        entry.setTarget(target);
        entry.setType(MenuAction.RUNELITE);
        entry.onClick(e -> action.run());
    }

    /**
     * Chebyshev distance, same as the server. Used to decide who the side panel
     * offers — never as the kill itself.
     */
    static boolean withinKillRange(int x1, int y1, int plane1, int x2, int y2, int plane2) {
        if (plane1 != plane2) {
            return false;
        }
        return Math.max(Math.abs(x1 - x2), Math.abs(y1 - y2)) <= KILL_RANGE_TILES;
    }

    void runAction(java.util.concurrent.CompletableFuture<String> future) {
        future.thenAccept(error -> {
            if (error == null || error.isEmpty()) {
                return;
            }
            clientThread.invoke(() -> client.addChatMessage(
                ChatMessageType.GAMEMESSAGE, "",
                "<col=ff9040>" + error + "</col>",
                ""));
        });
    }
}

package com.thebirdhouse.plugin;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;

/**
 * Covers the name over each other player's head while the lights are out.
 *
 * The right-click menu was never enough: OSRS still writes the RSN above them, and
 * leaving clan chat does not stop that. This paints over the name so crew cannot read
 * who they just walked past. The impostor is exempt.
 */
@Singleton
public class ImpostorBlackoutOverlay extends Overlay {

    private static final Color SLAB = new Color(12, 12, 16, 230);
    private static final Color LABEL = Color.WHITE;

    @Inject
    private Client client;

    @Inject
    private ImpostorPositionTracker tracker;

    @Inject
    private DropMatcher dropMatcher;

    @Inject
    public ImpostorBlackoutOverlay() {
        setPosition(OverlayPosition.DYNAMIC);
        // GPU nameplates sit above widgets. ALWAYS_ON_TOP is the layer that
        // actually covers them; ABOVE_WIDGETS still left the RSN leaking out
        // the right of a too-small slab.
        setLayer(OverlayLayer.ALWAYS_ON_TOP);
        setPriority(OverlayPriority.HIGHEST);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!shouldMask(dropMatcher.getActiveBoard(), tracker.getPhase(), tracker.isBlackout(), tracker.isImpostor(), tracker.isDead())) {
            return null;
        }
        Player me = client.getLocalPlayer();
        FontMetrics metrics = graphics.getFontMetrics();
        for (Player other : client.getPlayers()) {
            if (other == null || other == me) {
                continue;
            }
            String name = Text.removeTags(other.getName());
            if (name == null || name.isEmpty()) {
                continue;
            }
            Point loc = other.getCanvasTextLocation(graphics, name, other.getLogicalHeight() + 40);
            if (loc == null) {
                continue;
            }
            paintMask(graphics, metrics, loc, name);
        }
        return null;
    }

    static boolean shouldMask(BoardData board, boolean blackout, boolean impostor, boolean dead) {
        return shouldMask(board, null, blackout, impostor, dead);
    }

    static boolean shouldMask(BoardData board, String livePhase, boolean blackout, boolean impostor, boolean dead) {
        return ImpostorActions.commandsAllowed(board, livePhase) && blackout && !impostor && !dead;
    }

    static Rectangle slabFor(FontMetrics metrics, Point loc, String name) {
        // GPU draws a larger font than the overlay's metrics, plus a combat /
        // iron / friend icon to the left of the RSN. The last slab was sized
        // to the overlay font and centered on it, so the real name sat in the
        // open to the right — "??? …gertem". Cover a wide band instead.
        int text = Math.max(metrics.stringWidth(name), metrics.stringWidth("???"));
        int width = Math.max(220, text + 96);
        int height = Math.max(28, metrics.getHeight() + 22);
        return new Rectangle(loc.getX() - width / 2 - 24, loc.getY() - height + 10, width, height);
    }

    private static void paintMask(Graphics2D graphics, FontMetrics metrics, Point loc, String name) {
        Rectangle slab = slabFor(metrics, loc, name);
        graphics.setColor(SLAB);
        graphics.fill(slab);
        graphics.setColor(LABEL);
        int x = loc.getX() - metrics.stringWidth("???") / 2;
        graphics.drawString("???", x, loc.getY());
    }
}

package com.thebirdhouse.plugin;

import lombok.Data;

/**
 * A corpse the server is willing to tell this client about — one zone, no killer, no uid.
 */
@Data
public class ImpostorBody {
    private int x;
    private int y;
    private int plane;
    private String name;
}

package com.thebirdhouse.plugin;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;

/**
 * Draws corpses the server has disclosed for this zone. There is no real body in OSRS;
 * everyone in the room has the plugin, so the plugin is the corpse.
 */
@Singleton
public class ImpostorBodyOverlay extends Overlay {

    private static final Color FILL = new Color(180, 0, 0, 80);
    private static final Color BORDER = new Color(220, 40, 40, 220);

    @Inject
    private Client client;

    @Inject
    private ImpostorPositionTracker tracker;

    @Inject
    public ImpostorBodyOverlay() {
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (tracker.isDead()) {
            return null;
        }
        for (ImpostorBody body : tracker.getBodies()) {
            if (body == null) {
                continue;
            }
            WorldPoint world = new WorldPoint(body.getX(), body.getY(), body.getPlane());
            LocalPoint local = LocalPoint.fromWorld(client.getTopLevelWorldView(), world);
            if (local == null) {
                continue;
            }
            Polygon tile = Perspective.getCanvasTilePoly(client, local);
            if (tile == null) {
                continue;
            }
            graphics.setColor(FILL);
            graphics.fill(tile);
            graphics.setColor(BORDER);
            graphics.draw(tile);
            String label = body.getName() == null || body.getName().isEmpty() ? "Body" : body.getName();
            Point text = Perspective.getCanvasTextLocation(client, graphics, local, label, 0);
            if (text != null) {
                graphics.setColor(Color.RED);
                graphics.drawString(label, text.getX(), text.getY());
            }
        }
        return null;
    }
}

package com.thebirdhouse.plugin;

import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import javax.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;

/**
 * Says, and keeps saying, that the player is out of the game.
 *
 * A chat line is the wrong shape for this on its own. It scrolls away in seconds, and it will
 * scroll away while the player is still mid-fight and not reading chat — leaving somebody who
 * has been eliminated with no standing indication of it, still doing tasks that no longer
 * count, still on a voice call they are supposed to be quiet on.
 *
 * Honours {@code showOverlay}, the same switch as the tile-progress box. The side panel
 * still says they are out if they hide this.
 */
public class ImpostorDeathOverlay extends OverlayPanel {

    private final ImpostorPositionTracker tracker;
    private final BirdhouseConfig config;

    @Inject
    public ImpostorDeathOverlay(ImpostorPositionTracker tracker, BirdhouseConfig config) {
        this.tracker = tracker;
        this.config = config;

        // Top centre, because it is competing with a fight for attention and has to win.
        // Everything else this plugin draws sits top left and can be politely ignored; this
        // cannot. No priority is set: it governs ordering against other overlays rather than
        // prominence, the position is doing the work here, and the enum that would express it
        // is deprecated.
        setPosition(OverlayPosition.TOP_CENTER);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!config.showOverlay() || !tracker.isDead()) {
            return null;
        }

        panelComponent.getChildren().add(TitleComponent.builder()
            .text("ELIMINATED")
            .color(Color.RED)
            .build());

        // The instruction, repeated, because it is the part that matters and the part a player
        // in the middle of an argument on voice is most likely to let slip.
        panelComponent.getChildren().add(LineComponent.builder()
            .left("Stay muted")
            .build());

        panelComponent.getChildren().add(LineComponent.builder()
            .left("Nothing counts")
            .build());

        return super.render(graphics);
    }
}

package com.thebirdhouse.plugin;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Objects;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

/**
 * Reports where the player is standing during a round of The Impostor.
 *
 * The mode used to run on an abstract map: you picked a room from a dropdown and the game
 * took your word for it. This replaces that with the real one, so "where were you" is a
 * question about where the player actually stood. Everything downstream — which named
 * place that is, how long they were there, who could therefore have seen them — is decided
 * by the server. This class knows only how to read a coordinate and when to send it.
 *
 * WHAT IT DELIBERATELY DOES NOT DO. It does not know what a zone is, does not filter
 * positions by whether they look interesting, and never reads anybody else's. Those are
 * all server-side policy, which can be redeployed in a minute; anything moved in here
 * could only change as fast as the Plugin Hub reviews a release, and the zone boundaries
 * this feature rests on have never been checked by a person standing in them.
 *
 * WHY THERE ARE TWO THREADS. The position is read on the client thread, in
 * {@link #onGameTick}, and stashed in a volatile field for the scheduler to pick up — the
 * same split {@link SessionTracker} uses for the world number, and for the same reason:
 * reading client state off the client thread is the kind of thing that works until it
 * doesn't. The scheduler never touches the client.
 */
@Slf4j
@Singleton
public class ImpostorPositionTracker {

    /**
     * How often the send decision is considered. Deliberately faster than the send cadence
     * itself, which the server dictates and can change at runtime — a fixed-rate task at
     * the send interval would have to be cancelled and rebuilt every time that happened.
     */
    private static final long POLL_INTERVAL_MS = 1000;

    /** Used until the server states otherwise, which it does on the first accepted send. */
    private static final long DEFAULT_TICK_MS = 10_000;
    private static final long DEFAULT_KEEPALIVE_MS = 60_000;

    /**
     * Consecutive failures before this gives up until the round changes.
     *
     * Failures here are nearly unreachable — the gate below needs a board that only a
     * working token could have fetched — but "nearly" plus a timer is how a client ends up
     * posting into the void for a whole evening.
     */
    private static final int MAX_FAILURES = 3;

    @Inject
    private Client client;

    @Inject
    private BirdhouseConfig config;

    @Inject
    private BirdhouseApiClient apiClient;

    /** Holds the board the panel polls, which is where the game type and phase come from. */
    @Inject
    private DropMatcher dropMatcher;

    /** For the chat line, which has to be written on the client thread or it is dropped. */
    @Inject
    private ClientThread clientThread;

    /** For the flash, respecting whatever the player already chose about notifications. */
    @Inject
    private Notifier notifier;

    private final ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor();
    private ScheduledFuture<?> task;

    /** Written on the client thread, read on the scheduler thread. Null means "do not send". */
    private volatile Sample latest;

    // Scheduler-thread state. Not volatile: nothing else touches it.
    private Sample lastSent;
    private long lastSentAt;
    private String lastKey;
    private int failures;

    // Written from HTTP callbacks, read on the scheduler thread.
    private volatile long tickMs = DEFAULT_TICK_MS;
    private volatile long keepaliveMs = DEFAULT_KEEPALIVE_MS;
    private volatile String stoppedKey;

    /** The last zone the server named, purely so a log line can say something useful. */
    private volatile String zone;
    private volatile String rsn;

    /**
     * Told they are out. Volatile because the HTTP callback sets it and the client thread
     * reads it every frame to draw the notice.
     */
    private volatile boolean dead;

    public void start() {
        stop();
        task = scheduler.scheduleAtFixedRate(this::poll, POLL_INTERVAL_MS, POLL_INTERVAL_MS, TimeUnit.MILLISECONDS);
    }

    public void stop() {
        if (task != null) {
            task.cancel(false);
            task = null;
        }
        latest = null;
        lastSent = null;
        lastKey = null;
        stoppedKey = null;
        failures = 0;
        zone = null;
        dead = false;
        role = null;
        phase = null;
        meeting = false;
        blackout = false;
        bodies = java.util.Collections.emptyList();
        nearbyNames = java.util.Collections.emptyList();
    }

    /**
     * Forget everything about where we were and what the server last said, without tearing
     * down the scheduler.
     *
     * Needed on logout because {@link #onGameTick} is the only thing that clears a stale
     * sample, and it stops firing the moment the player leaves. Left alone, the last
     * position of the evening would keep being resent on the keepalive — reporting somebody
     * as standing in the sewers long after they closed the client, which is the false alibi
     * the server's absence handling exists to prevent.
     *
     * The stop flag goes with it, which matters when the player has just switched the
     * feature on: a refusal from an earlier round would otherwise keep them silent until
     * the next phase change, and the cost of being wrong is one request that gets refused
     * again.
     */
    public void clearPosition() {
        latest = null;
        lastSent = null;
        stoppedKey = null;
        failures = 0;
        zone = null;
        // Cleared so a relog re-hears it. The server re-asserts a death, so this costs one
        // repeated notification to somebody who is dead and ought to be reminded of it —
        // better than a ghost who logged back in and found the notice gone.
        dead = false;
        role = null;
        phase = null;
        meeting = false;
        blackout = false;
        bodies = java.util.Collections.emptyList();
        nearbyNames = java.util.Collections.emptyList();
    }

    /**
     * Own role, in-zone bodies, meeting and blackout — written from the HTTP callback,
     * read on the client thread by overlays and menus.
     */
    private volatile String role;
    private volatile String phase;
    private volatile boolean meeting;
    private volatile boolean blackout;
    private volatile java.util.List<ImpostorBody> bodies = java.util.Collections.emptyList();

    /**
     * Other players standing within {@link ImpostorActions#KILL_RANGE_TILES}. The side
     * panel's Eliminate list is this and nothing else — a name that is not here cannot
     * be clicked, and a name that is still has to pass the server's own range check.
     */
    private volatile java.util.List<String> nearbyNames = java.util.Collections.emptyList();

    @Subscribe
    public void onGameTick(GameTick event) {
        applyBoard(dropMatcher.getActiveBoard());
        refreshNearby();
        if (!config.shareImpostorPosition() || !shouldSample(dropMatcher.getActiveBoard())) {
            latest = null;
            return;
        }
        if (client.getGameState() != GameState.LOGGED_IN) {
            latest = null;
            return;
        }
        Player me = client.getLocalPlayer();
        WorldPoint where = me != null ? me.getWorldLocation() : null;
        if (where == null) {
            latest = null;
            return;
        }
        // Reported exactly as the client gives it, instance flag included and coordinates
        // unresolved. See PositionPayload#instance for why resolving them would be wasted
        // work rather than diligence.
        if (me.getName() != null) {
            rsn = me.getName();
        }
        latest = new Sample(where.getX(), where.getY(), where.getPlane(),
            client.getTopLevelWorldView().isInstance());
    }

    /**
     * Whether the plugin should be reporting position for this board at all.
     *
     * A phase of anything but {@code round} means no: the lobby, a meeting, the vote and
     * the reveal all want people talking rather than being measured. Older servers send no
     * phase at all, which reads as "no round" and switches the feature off rather than on,
     * because a plugin that reported through a game the server was not expecting it in
     * would be collecting positions nobody asked for.
     */
    static boolean roundIsRunning(BoardData board) {
        return board != null
            && "impostor".equals(board.getGameType())
            && "round".equals(board.getPhase());
    }

    /**
     * Whether to send coordinates, not just a status ping.
     *
     * The lobby is included because deal refuses anyone without a fresh sample. Meetings
     * still go out as status-only — people are arguing, not being measured.
     */
    static boolean shouldSample(BoardData board) {
        if (board == null || !"impostor".equals(board.getGameType())) {
            return false;
        }
        String phase = board.getPhase();
        return phase == null || phase.isEmpty() || "lobby".equals(phase) || "round".equals(phase);
    }

    /**
     * The board poll is slower than a position ack but it always names this player's
     * role. Used when an ack is late so Eliminate does not wait on a ping.
     */
    public void applyBoard(BoardData board) {
        if (board == null || !"impostor".equals(board.getGameType())) {
            return;
        }
        if (board.getRole() != null && !board.getRole().isEmpty()) {
            role = board.getRole();
        }
        // A stale lobby board must not pin us there after the deal. Take round /
        // meeting / done from the poll; only fill lobby when we have no phase yet.
        phase = mergePhase(phase, board.getPhase());
        if (Boolean.TRUE.equals(board.getDead())) {
            announceDeath();
        }
    }

    /**
     * Prefer a live phase from the poll over a leftover lobby, without letting a
     * minute-old lobby overwrite a fresh ack that already said the round had started.
     */
    static String mergePhase(String live, String fromBoard) {
        if (fromBoard == null || fromBoard.isEmpty()) {
            return live;
        }
        if ("round".equals(fromBoard) || "meeting".equals(fromBoard)
            || "done".equals(fromBoard) || "reveal".equals(fromBoard)) {
            return fromBoard;
        }
        return live == null || live.isEmpty() ? fromBoard : live;
    }

    /**
     * Whether to keep talking to the server at all, which is a weaker question than whether a
     * round is running, and has to be.
     *
     * A kill lands when the round closes — the same instant the phase stops being
     * {@code round}. Gate the sending on {@link #roundIsRunning} and the plugin falls silent
     * at precisely the moment the server has something to tell it, so the victim finds out
     * they are dead at the start of the *next* round: after the meeting they most needed to
     * keep quiet through. Today it happens to work, because the board this reads is up to a
     * minute stale and the plugin therefore keeps ticking through a round that has already
     * ended. Relying on a cache being out of date is not a design.
     *
     * So sending continues for as long as the game is live, and the server decides. It refuses
     * anything outside a round with a stop, before storing it — see the position handler,
     * where the liveness check deliberately sits above that refusal.
     *
     * The cost is one refused request per phase change per player, and coordinates that go
     * over the wire during meetings and are discarded rather than never being sent. That is a
     * real weakening of "only while a round is running" and it is worth it: the alternative is
     * a mode where dying arrives late, which is the one place lateness does damage.
     */
    static boolean gameIsLive(BoardData board) {
        if (board == null || !"impostor".equals(board.getGameType())) {
            return false;
        }
        String phase = board.getPhase();
        if ("done".equals(phase) || "reveal".equals(phase)) {
            return false;
        }
        if ("finished".equals(board.getStatus())) {
            return false;
        }
        // The lobby has to be live before anyone is dealt: that is how they ready up.
        return true;
    }

    /**
     * What a stop applies to.
     *
     * Keyed on the room and the phase together so a refusal expires by itself: the server
     * says stop, the phase moves on to the meeting and then into the next round, and the
     * key no longer matches. Without this, one stale board arriving mid-transition would
     * silence the plugin for the rest of the game.
     */
    static String stateKey(String roomCode, String phase) {
        return roomCode + "|" + phase;
    }

    /**
     * Whether this sample is worth sending yet.
     *
     * Two reasons to send: the player has moved, or they have not moved for long enough
     * that silence would be ambiguous. The second is the one that matters and the one a
     * send-on-change-only design would miss — the server accumulates time in a place, so
     * it has to be able to tell somebody standing still killing moss giants apart from
     * somebody who closed the client. Both look identical from the far end of a quiet
     * connection, and guessing wrong either invents an alibi or steals an honest one.
     */
    static boolean dueToSend(Sample last, Sample now, long sinceLastSendMs, long tickMs, long keepaliveMs) {
        if (now == null) {
            return false;
        }
        if (sinceLastSendMs < tickMs) {
            return false;
        }
        if (last == null) {
            return true;
        }
        if (!last.equals(now)) {
            return true;
        }
        return sinceLastSendMs >= keepaliveMs;
    }

    private void poll() {
        try {
            send();
        } catch (RuntimeException e) {
            // A throw here would kill the scheduled task silently and take the feature with
            // it for the rest of the session.
            log.debug("Position poll failed: {}", e.getMessage());
        }
    }

    private void send() {
        BoardData board = dropMatcher.getActiveBoard();
        String room = dropMatcher.getActiveRoomCode();
        String phase = board != null ? board.getPhase() : null;
        String key = stateKey(room, phase);

        // A new round, or a new room, starts from nothing: the server has wiped its own
        // record, so the first sample of a round must always go even from somebody who has
        // not moved an inch since the last one. Tracked on every poll rather than only
        // while a round runs, so the round/meeting/round transition is actually observed.
        if (!Objects.equals(key, lastKey)) {
            lastKey = key;
            lastSent = null;
            failures = 0;
        }

        if (!config.shareImpostorPosition() || !gameIsLive(board) || room == null) {
            return;
        }
        if (key.equals(stoppedKey) || failures >= MAX_FAILURES) {
            return;
        }

        long since = System.currentTimeMillis() - lastSentAt;

        // Between rounds: ask, without saying where we are. The only thing worth hearing here
        // is that we have been killed, and the stop that comes back with the server's refusal
        // means this costs one request per phase rather than one every tick.
        if (!shouldSample(board)) {
            if (since < tickMs) {
                return;
            }
            lastSent = null;
            lastSentAt = System.currentTimeMillis();
            apiClient.reportPosition(PositionPayload.statusOnly(room))
                .thenAccept(ack -> onAck(key, null, ack));
            return;
        }

        Sample now = latest;
        // During blackout the victim only hears they are dead on the next ping.
        // Standing still would wait out the keepalive (a minute) — longer than the
        // lights stay out. Tick instead, so the death lands while names are still hidden.
        long keep = blackout ? tickMs : keepaliveMs;
        if (!dueToSend(lastSent, now, since, tickMs, keep)) {
            return;
        }

        lastSent = now;
        lastSentAt = System.currentTimeMillis();
        PositionPayload payload = now.payload(room);
        if (rsn != null) {
            payload.setPlayerName(rsn);
        }
        apiClient.reportPosition(payload).thenAccept(ack -> onAck(key, now, ack));
    }

    /**
     * Apply whatever the server said about the sample we just sent.
     *
     * Runs on an HTTP callback thread, so it only touches the volatile fields and the one
     * scheduler-owned field it has a good reason to: a sample the server did not keep must
     * not be remembered as sent, or the keepalive would be the only thing that ever
     * resent it.
     */
    private void onAck(String key, Sample sent, PositionAck ack) {
        if (ack == null) {
            failures++;
            forget(sent);
            return;
        }
        failures = 0;

        if (ack.getTick() != null && ack.getTick() > 0) {
            tickMs = ack.getTick() * 1000L;
        }
        if (ack.getKeepalive() != null && ack.getKeepalive() > 0) {
            keepaliveMs = ack.getKeepalive() * 1000L;
        }

        // Before the stop, which arrives with it and would otherwise return first.
        if (ack.isDead()) {
            announceDeath();
        }

        if (ack.getRole() != null) {
            role = ack.getRole();
        }
        if (ack.getPhase() != null) {
            phase = ack.getPhase();
        }
        meeting = ack.isMeeting();
        blackout = ack.isBlackout();
        if (ack.getBodies() != null) {
            bodies = ack.getBodies();
        }

        if (ack.isStop()) {
            stoppedKey = key;
            zone = null;
            log.debug("Position reporting stopped for {}", key);
            return;
        }
        if (ack.isThrottled()) {
            forget(sent);
            return;
        }
        zone = ack.getZone();
    }

    /**
     * Tell the player they are out, once.
     *
     * THE ORDER OF THE WORDS IS THE FEATURE. Everybody is on voice chat, and the honest
     * reaction to a screen flash mid-fight is to say something — which tells the room that a
     * kill just happened and roughly where, and that is most of what the meeting was for. So
     * the instruction comes before the news, because it has to land in the quarter second
     * before somebody reacts, and the news is no use to them anyway.
     *
     * The notifier rather than a hand-rolled flash: it honours whatever the player already
     * chose about notifications, and a plugin that forces a flash on somebody who switched
     * them off is a plugin they uninstall.
     *
     * Idempotent because the server re-asserts a death on each phase change — deliberately,
     * so a missed one still arrives — and the second telling should be silent.
     */
    private void announceDeath() {
        if (dead) {
            return;
        }
        dead = true;
        notifier.notify("Say nothing. You have been eliminated.");
        // addChatMessage does nothing off the client thread. Same hop as DropMatcher and
        // AchievementTracker make, and for the same reason.
        clientThread.invoke(() -> client.addChatMessage(
            ChatMessageType.GAMEMESSAGE, "",
            "<col=ff0000>Say nothing.</col> You have been eliminated. "
                + "Nothing you do from here counts. Stay muted and keep watching.",
            ""));
        log.debug("Player eliminated");
    }

    /** Whether the player has been told they are out, for the overlay that keeps saying so. */
    public boolean isDead() {
        return dead;
    }

    public boolean isImpostor() {
        return "impostor".equals(role);
    }

    /** The phase the server last named, or null before the first ack. */
    public String getPhase() {
        return phase;
    }

    public boolean isMeeting() {
        return meeting;
    }

    public boolean isBlackout() {
        return blackout;
    }

    public java.util.List<ImpostorBody> getBodies() {
        return bodies;
    }

    /** Other players within kill range right now. Empty when logged out. */
    public java.util.List<String> getNearbyNames() {
        return nearbyNames;
    }

    private void refreshNearby() {
        if (client.getGameState() != GameState.LOGGED_IN) {
            nearbyNames = java.util.Collections.emptyList();
            return;
        }
        Player me = client.getLocalPlayer();
        WorldPoint here = me != null ? me.getWorldLocation() : null;
        if (here == null) {
            nearbyNames = java.util.Collections.emptyList();
            return;
        }
        String mine = me.getName() != null ? net.runelite.client.util.Text.removeTags(me.getName()) : null;
        java.util.List<String> names = new java.util.ArrayList<>();
        for (Player other : client.getPlayers()) {
            if (other == null || other == me || other.getName() == null) {
                continue;
            }
            WorldPoint there = other.getWorldLocation();
            if (there == null) {
                continue;
            }
            if (!ImpostorActions.withinKillRange(
                here.getX(), here.getY(), here.getPlane(),
                there.getX(), there.getY(), there.getPlane())) {
                continue;
            }
            String name = net.runelite.client.util.Text.removeTags(other.getName());
            if (name.isEmpty() || "???".equals(name)) {
                continue;
            }
            if (mine != null && mine.equalsIgnoreCase(name)) {
                continue;
            }
            names.add(name);
        }
        nearbyNames = java.util.Collections.unmodifiableList(names);
    }

    public ImpostorBody bodyAt(int x, int y, int plane) {
        return bodyNear(x, y, plane, 0);
    }

    /**
     * A corpse on or next to this tile. Exact-tile matching hid Report body whenever
     * the click landed one square off the overlay, or the stored corpse tile was a
     * ping behind the death.
     */
    public ImpostorBody bodyNear(int x, int y, int plane, int range) {
        ImpostorBody best = null;
        int bestDist = Integer.MAX_VALUE;
        int allow = Math.max(0, range);
        for (ImpostorBody b : bodies) {
            if (b == null || b.getPlane() != plane) {
                continue;
            }
            int dist = Math.max(Math.abs(b.getX() - x), Math.abs(b.getY() - y));
            if (dist <= allow && dist < bestDist) {
                best = b;
                bestDist = dist;
            }
        }
        return best;
    }

    /**
     * Drop the memory of a sample the server never recorded, so the next poll resends it
     * rather than waiting out the keepalive on a position that was never stored.
     */
    private void forget(Sample sent) {
        if (lastSent == sent) {
            lastSent = null;
        }
    }

    /** The zone the server last placed us in, or null. Exposed for logging and the panel. */
    public String getZone() {
        return zone;
    }

    /**
     * One reading of the player's position.
     *
     * Immutable and compared by value, because "has it changed" is the whole question the
     * send decision asks. The plane and the instance flag are part of that: moving between
     * floors of Draynor Manor is movement, and stepping into an instance takes you off the
     * board entirely, which the server needs to hear about promptly.
     */
    static final class Sample {
        private final int x;
        private final int y;
        private final int plane;
        private final boolean instance;

        Sample(int x, int y, int plane, boolean instance) {
            this.x = x;
            this.y = y;
            this.plane = plane;
            this.instance = instance;
        }

        PositionPayload payload(String roomCode) {
            return new PositionPayload(roomCode, x, y, plane, instance);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) {
                return true;
            }
            if (!(o instanceof Sample)) {
                return false;
            }
            Sample other = (Sample) o;
            return x == other.x && y == other.y && plane == other.plane && instance == other.instance;
        }

        @Override
        public int hashCode() {
            return Objects.hash(x, y, plane, instance);
        }

        @Override
        public String toString() {
            return "(" + x + "," + y + "," + plane + (instance ? ",instance" : "") + ")";
        }
    }
}

package com.thebirdhouse.plugin;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

/**
 * In-game verbs for The Impostor that do not depend on the right-click menu.
 *
 * Eliminate still has to pass the server's 8-tile check. This panel only lists
 * people already standing that close, so a click is not a claim — it is a request
 * the server can still refuse.
 */
@Singleton
public class ImpostorSidePanel extends JPanel {

    private static final Color COLOR_MUTED = new Color(160, 160, 160);
    private static final Color COLOR_DEAD = new Color(255, 90, 90);
    private static final Color COLOR_IMPOSTOR = new Color(220, 70, 70);

    @Inject
    private ImpostorPositionTracker tracker;

    @Inject
    private ImpostorActions actions;

    @Inject
    private DropMatcher dropMatcher;

    @Inject
    private BirdhouseApiClient apiClient;

    private final JLabel statusLabel = line();
    private final JLabel taskLabel = line();
    private final JLabel hintLabel = line();
    private final JPanel verbs = new JPanel();
    private final Timer nearbyTimer;

    private String lastFingerprint = "";

    public ImpostorSidePanel() {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(new EmptyBorder(0, 0, 8, 0));
        setAlignmentX(Component.LEFT_ALIGNMENT);

        JLabel title = new JLabel("The Impostor");
        title.setForeground(Color.WHITE);
        title.setFont(uiFont(Font.BOLD, 14f));
        title.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(title);

        statusLabel.setFont(uiFont(Font.BOLD, 13f));
        add(statusLabel);
        add(taskLabel);
        add(hintLabel);

        verbs.setLayout(new BoxLayout(verbs, BoxLayout.Y_AXIS));
        verbs.setBackground(ColorScheme.DARK_GRAY_COLOR);
        verbs.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(verbs);

        nearbyTimer = new Timer(1000, e -> rebuild());
        nearbyTimer.setRepeats(true);
        setVisible(false);
    }

    void onBoard(BoardData board) {
        SwingUtilities.invokeLater(() -> {
            boolean live = board != null && "impostor".equals(board.getGameType());
            setVisible(live);
            if (live) {
                if (!nearbyTimer.isRunning()) {
                    nearbyTimer.start();
                }
                rebuild();
            } else {
                nearbyTimer.stop();
                lastFingerprint = "";
            }
        });
    }

    void stop() {
        nearbyTimer.stop();
    }

    private void rebuild() {
        BoardData board = dropMatcher.getActiveBoard();
        String room = dropMatcher.getActiveRoomCode();
        if (board == null || !"impostor".equals(board.getGameType()) || room == null) {
            setVisible(false);
            nearbyTimer.stop();
            return;
        }

        boolean dead = tracker.isDead();
        boolean impostor = tracker.isImpostor();
        boolean round = ImpostorActions.commandsAllowed(board, tracker.getPhase());
        boolean blackout = tracker.isBlackout();
        boolean meeting = tracker.isMeeting();
        List<String> nearby = impostor && round && !dead
            ? tracker.getNearbyNames()
            : List.of();
        String task = currentTask(board);
        String fingerprint = String.join("|",
            Boolean.toString(dead), Boolean.toString(impostor), Boolean.toString(round),
            Boolean.toString(blackout), Boolean.toString(meeting),
            tracker.getPhase() == null ? "" : tracker.getPhase(),
            task, String.join(",", nearby));
        if (fingerprint.equals(lastFingerprint)) {
            return;
        }
        lastFingerprint = fingerprint;

        if (dead) {
            setWrapped(statusLabel, "You are out. Stay muted.");
            statusLabel.setForeground(COLOR_DEAD);
            setWrapped(taskLabel, " ");
            setWrapped(hintLabel, "Nothing you do from here counts.");
            hintLabel.setForeground(COLOR_MUTED);
            verbs.removeAll();
            revalidate();
            repaint();
            return;
        }

        if (meeting) {
            setWrapped(statusLabel, "Meeting — vote on the website");
            statusLabel.setForeground(new Color(255, 180, 80));
            setWrapped(taskLabel, task.isEmpty() ? " " : task);
            setWrapped(hintLabel, " ");
            verbs.removeAll();
            revalidate();
            repaint();
            return;
        }

        if (impostor) {
            setWrapped(statusLabel, "You are the impostor");
            statusLabel.setForeground(COLOR_IMPOSTOR);
        } else {
            setWrapped(statusLabel, "You are crew");
            statusLabel.setForeground(new Color(120, 200, 255));
        }
        setWrapped(taskLabel, task.isEmpty() ? " " : task);
        taskLabel.setForeground(Color.WHITE);

        verbs.removeAll();
        if (!round) {
            setWrapped(hintLabel, "Waiting for the round to start.");
            hintLabel.setForeground(COLOR_MUTED);
            revalidate();
            repaint();
            return;
        }

        if (impostor) {
            if (nearby.isEmpty()) {
                setWrapped(hintLabel, "Stand within 8 tiles of someone to eliminate them. The server checks.");
                hintLabel.setForeground(COLOR_MUTED);
            } else {
                setWrapped(hintLabel, "Next to you — eliminate still has to land on the server.");
                hintLabel.setForeground(COLOR_MUTED);
                for (String name : nearby) {
                    verbs.add(verb("Eliminate " + name, COLOR_IMPOSTOR, () -> {
                        if (!confirm("Eliminate " + name + "?",
                            "They have to be standing next to you. A ping from both of you is what decides it, not this button.")) {
                            return;
                        }
                        actions.runAction(apiClient.impostorKill(room, name));
                    }));
                }
            }
            verbs.add(Box.createVerticalStrut(4));
            verbs.add(verb("Cut the lights", Color.WHITE, () ->
                actions.runAction(apiClient.impostorSabotage(room))));
        } else {
            setWrapped(hintLabel, blackout
                ? "Lights out. Names are hidden."
                : "Report a body when you find one, or call everyone in.");
            hintLabel.setForeground(COLOR_MUTED);
        }

        verbs.add(verb("Report body", new Color(255, 140, 140), () -> {
            if (!confirm("Report a body?",
                "You have to be standing near where they died.")) {
                return;
            }
            actions.runAction(apiClient.impostorReport(room));
        }));
        verbs.add(verb("Call a meeting", new Color(255, 200, 120), () -> {
            if (!confirm("Call a meeting?",
                "This pulls everyone in and opens the vote.")) {
                return;
            }
            actions.runAction(apiClient.impostorMeeting(room));
        }));

        revalidate();
        repaint();
    }

    private JButton verb(String label, Color fg, Runnable action) {
        JButton button = new JButton(label);
        button.setAlignmentX(Component.LEFT_ALIGNMENT);
        button.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
        button.setForeground(fg);
        button.setFont(uiFont(Font.PLAIN, 12f));
        button.setFocusPainted(false);
        button.addActionListener(e -> action.run());
        return button;
    }

    private boolean confirm(String title, String message) {
        return JOptionPane.showConfirmDialog(
            this, message, title, JOptionPane.YES_NO_OPTION) == JOptionPane.YES_OPTION;
    }

    private static String currentTask(BoardData board) {
        if (board.getTiles() == null || board.getTiles().isEmpty()) {
            return "";
        }
        BoardTile tile = board.getTiles().get(0);
        if (tile == null || tile.getName() == null) {
            return "";
        }
        if (tile.getQuantity() > 0) {
            return tile.getName() + "  " + tile.getCurrentQty() + "/" + tile.getQuantity();
        }
        return tile.getName();
    }

    private static JLabel line() {
        JLabel label = new JLabel(" ");
        label.setForeground(COLOR_MUTED);
        label.setFont(uiFont(Font.PLAIN, 12f));
        label.setAlignmentX(Component.LEFT_ALIGNMENT);
        // BoxLayout ignores wrap unless the label is width-capped.
        label.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, Integer.MAX_VALUE));
        return label;
    }

    /**
     * The RuneScape bitmap font ghosts its last letters when Swing draws it in
     * the sidebar. DefaultFont is what the rest of the panel already uses for
     * anything that has to be readable at 225px.
     */
    private static Font uiFont(int style, float size) {
        return FontManager.getDefaultFont().deriveFont(style, size);
    }

    private static void setWrapped(JLabel label, String text) {
        if (text == null || text.isBlank()) {
            label.setText(" ");
            return;
        }
        label.setText("<html><div style='width:190px'>" + escapeHtml(text) + "</div></html>");
    }

    private static String escapeHtml(String text) {
        return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    /** Exposed for tests — the panel never lists anyone outside this set. */
    static List<String> namesInRange(List<String> nearby) {
        return nearby == null ? new ArrayList<>() : new ArrayList<>(nearby);
    }

    static boolean sameTargets(List<String> a, List<String> b) {
        return Objects.equals(a, b);
    }
}

package com.thebirdhouse.plugin;

import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;

/**
 * Meeting and blackout notices. Death has its own overlay; this one is for the two
 * things that change how you play while you are still alive.
 */
@Singleton
public class ImpostorStatusOverlay extends OverlayPanel {

    @Inject
    private ImpostorPositionTracker tracker;

    @Inject
    private BirdhouseConfig config;

    @Inject
    public ImpostorStatusOverlay() {
        setPosition(OverlayPosition.TOP_CENTER);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!config.showOverlay() || tracker.isDead()) {
            return null;
        }
        if (tracker.isMeeting()) {
            panelComponent.getChildren().add(TitleComponent.builder()
                .text("MEETING")
                .color(Color.ORANGE)
                .build());
            panelComponent.getChildren().add(LineComponent.builder()
                .left("Get on voice. Vote on the website.")
                .build());
            return super.render(graphics);
        }
        if (tracker.isBlackout()) {
            panelComponent.getChildren().add(TitleComponent.builder()
                .text("LIGHTS OUT")
                .color(Color.WHITE)
                .build());
            panelComponent.getChildren().add(LineComponent.builder()
                .left("You cannot see who is standing next to you.")
                .build());
            return super.render(graphics);
        }
        return null;
    }
}

package com.thebirdhouse.plugin;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.loottracker.LootReceived;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.HashMap;
import java.util.Map;

/**
 * Kill-count tiles for bosses whose loot is not booked against them.
 *
 * A kill-count tile is satisfied by a loot event whose source name matches, which works
 * for anything that dies and drops. It silently fails for the bosses that hand out their
 * rewards through something else: the loot tracker books Wintertodt's crates as "Supply
 * crate (Wintertodt)" and Tempoross's pool as "Reward pool (Tempoross)", so a tile asking
 * for "Wintertodt" never sees a thing. The kill is real, the game announces it, and the
 * counter goes up — it just never reaches the board.
 *
 * That announcement is the signal used here. The same message already confirms kills for
 * the leaderboard, so the pattern is shared rather than rewritten.
 *
 * Most bosses announce a count *and* drop loot, which would credit the tile twice. A
 * credit is held for a tick and dropped if the loot tracker named the same source, which
 * covers the ordinary case without a wasted upload. Nothing behind that catches what this
 * misses: the server collapses the rolls that shared a {@link ProofPayload#killId}, and an
 * announcement carries an id of its own precisely because it is a separate kill.
 */
@Slf4j
@Singleton
public class KillCountTracker {

    /** How long a loot event's source name suppresses a matching killcount message. */
    private static final int RECENT_TICKS = 2;

    @Inject
    private Client client;

    @Inject
    private BirdhouseConfig config;

    @Inject
    private DropMatcher dropMatcher;

    /** Lowercased loot source to the tick it last arrived on. */
    private final Map<String, Integer> lootSourceTicks = new HashMap<>();

    private String pendingBoss = null;
    private int pendingTick = Integer.MIN_VALUE;

    public void reset() {
        lootSourceTicks.clear();
        pendingBoss = null;
        pendingTick = Integer.MIN_VALUE;
    }

    @Subscribe
    public void onLootReceived(LootReceived event) {
        String name = event.getName();
        if (name == null || name.isEmpty()) return;
        lootSourceTicks.put(name.toLowerCase(), client.getTickCount());
    }

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        if (!config.autoSubmitDrops()) return;
        if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM) return;

        String boss = KillCounts.bossFrom(event.getMessage());
        if (boss == null) return;

        // Held for a tick rather than credited here. A boss that drops loot fires both
        // signals on the same tick and the order two subscribers run in is undefined, so
        // asking now whether the loot already claimed the kill would be a coin flip.
        pendingBoss = boss;
        pendingTick = client.getTickCount();
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        if (pendingBoss == null) return;
        if (client.getTickCount() == pendingTick) return;

        String boss = pendingBoss;
        int announced = pendingTick;
        pendingBoss = null;

        if (creditedByLoot(boss, announced, lootSourceTicks)) {
            log.debug("[Birdhouse] '{}' kill already credited from its loot", boss);
            return;
        }

        log.info("[Birdhouse] Kill count announced for '{}'", boss);
        dropMatcher.handleKillCount(boss);
    }

    /**
     * Whether the loot tracker already named this source around the same tick.
     *
     * Kept pure so the double-credit rule can be tested without a client. Wintertodt is
     * the case that must come through: its loot arrives under a different name, so
     * nothing here suppresses it.
     */
    static boolean creditedByLoot(String boss, int announcedTick, Map<String, Integer> lootTicks) {
        if (boss == null || lootTicks == null || lootTicks.isEmpty()) return false;
        Integer seen = lootTicks.get(boss.toLowerCase());
        if (seen == null) return false;
        return Math.abs(announcedTick - seen) <= RECENT_TICKS;
    }
}

package com.thebirdhouse.plugin;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The game's own "your X count is: N" message.
 *
 * Some bosses never produce loot the tracker can attribute to them. Wintertodt and
 * Tempoross hand out crates and reward pools booked under those names rather than the
 * boss's, so a kill-count tile naming the boss sees nothing at all — even though the game
 * announced the kill in chat and incremented a counter for it.
 *
 * Shared by the leaderboard, which uses it to confirm kills whose loot lies, and by
 * {@link KillCountTracker}, which uses it to credit kill-count tiles. One copy, because
 * two hand-maintained versions of a pattern this fiddly would drift.
 */
final class KillCounts {

    /**
     * Mirrors RuneLite's own ChatCommandsPlugin killcount pattern, which has absorbed
     * years of per-boss phrasing quirks ("subdued", "completion count for", raid
     * "completed" counts). The trailing colour tag is optional only so the pattern stays
     * testable against plain strings.
     */
    static final Pattern KILLCOUNT_PATTERN = Pattern.compile(
        "Your (?:completion count for |subdued |completed )?(?:<col=[0-9a-f]{6}>)?"
            + "(?<boss>.+?)(?:</col>)? "
            + "(?:(?:kill|harvest|lap|completion|success) )?(?:count )?"
            + "is: ?(?:<col=[0-9a-f]{6}>)?(?<kc>[0-9,]+)"
    );

    private KillCounts() {
    }

    /** The boss named by a killcount message, or null if the message is not one. */
    static String bossFrom(String message) {
        if (message == null || message.isEmpty()) return null;
        Matcher matcher = KILLCOUNT_PATTERN.matcher(message);
        if (!matcher.find()) return null;
        String boss = matcher.group("boss");
        return boss == null || boss.isEmpty() ? null : boss;
    }
}

package com.thebirdhouse.plugin;

import java.io.InputStream;
import java.util.Properties;

/**
 * Which build this is, read from a resource the Gradle build stamps.
 *
 * Every request carries it. Without it a bug report cannot be answered without first
 * asking the reporter which version they are on and taking their word for it, and a
 * server-side log of a misbehaving submission says nothing about whether the fix for it
 * had already shipped.
 */
final class PluginVersion {

    /** What to report when the resource is missing, so a request is never blocked by it. */
    private static final String UNKNOWN = "unknown";

    static final String VERSION = read();

    private PluginVersion() {
    }

    private static String read() {
        try (InputStream in = PluginVersion.class.getResourceAsStream("/birdhouse.properties")) {
            if (in == null) return UNKNOWN;
            Properties props = new Properties();
            props.load(in);
            String version = props.getProperty("version");
            return version == null || version.trim().isEmpty() ? UNKNOWN : version.trim();
        } catch (Exception e) {
            // Reporting a version is a convenience for diagnosis and never worth failing
            // a submission over.
            return UNKNOWN;
        }
    }
}

package com.thebirdhouse.plugin;

import lombok.Data;

/**
 * The server's answer to a position report, which is mostly an instruction about what to
 * do next rather than a result.
 *
 * The cadence lives on that side on purpose. Ten seconds is a guess at the right sampling
 * rate and the co-presence threshold it feeds has never been tuned against real players,
 * so both will move — and a number baked into this class would move only as fast as the
 * Plugin Hub reviews a release. Everything here is therefore read from the response and
 * only defaulted when the field is missing.
 */
@Data
public class PositionAck {

    private boolean ok;

    /** The named place the server decided we are standing in, or null for off the board. */
    private String zone;

    /** Seconds to wait before considering another send. */
    private Integer tick;

    /** Seconds after which to send again even if we have not moved. */
    private Integer keepalive;

    /**
     * The room does not want position: the round is over, the game is not an impostor
     * game, or real tasks are switched off. Stop until something changes.
     */
    private boolean stop;

    /**
     * The sample arrived too soon and was discarded. Not a refusal — the room still wants
     * position, so this must not be treated as {@link #stop}.
     */
    private boolean throttled;

    /**
     * You are out of the game.
     *
     * This ack is the only channel the mode has into the client that runs faster than a
     * minute, and dying is the news that cannot wait one: until the player is told, they are
     * visibly still fighting something, which tells the room more than the meeting was
     * supposed to.
     *
     * Never says who. That is not squeamishness — a victim who knew would give it away in the
     * meeting whether they meant to or not, and they are the one person in the room who
     * cannot be asked to argue their way out of it.
     *
     * Arrives with {@link #stop}, since a dead player's position is nobody's evidence.
     */
    private boolean dead;

    /** Your own role, or null before the deal. Nobody else's. */
    private String role;

    /** Lobby, round, meeting, reveal or done — fresher than the 60s board poll. */
    private String phase;

    /** A meeting is open — get on voice. */
    private boolean meeting;

    /** Names are hidden. Impostors never see this as true. */
    private boolean blackout;

    /** Bodies in the zone you are standing in, and nowhere else. */
    private java.util.List<ImpostorBody> bodies;
}

package com.thebirdhouse.plugin;

import lombok.Data;

/**
 * Where the player is standing, sent during a round of The Impostor.
 *
 * Raw world coordinates and nothing else. The plugin deliberately does not know what a
 * zone is: the server owns the table that turns a coordinate into a named place, because
 * a wrong bounding box is then a deploy on their side rather than a Plugin Hub review and
 * a wait for every clanmate to update. Sending a region id or a place name from here
 * would move that decision into the half that is expensive to change.
 */
@Data
public class PositionPayload {

    private String roomCode;
    private int x;
    private int y;
    private int plane;

    /**
     * Whether the player is inside instanced content.
     *
     * The coordinates are sent exactly as the client reports them even when this is true,
     * which looks careless and is not. Instanced regions reuse coordinates, so the usual
     * move would be to resolve the real position — but the server's rule is that anyone
     * inside an instance is in no zone at all, so it throws the coordinates away and reads
     * only this flag. Resolving them would be work in aid of a value nobody looks at.
     */
    private boolean instance;

    /** In-game RSN, so Eliminate can match a right-click name to a site display name. */
    private String playerName;

    /**
     * "Nothing to report — is there anything I should know?"
     *
     * The mode has to be able to tell a player they are dead, and a kill lands at the instant
     * a round closes, when there is by definition no round to report a position for. Rather
     * than keep sending coordinates outside a round so that the answer has something to ride
     * on, this says plainly that there is no position in this request and the fields below are
     * not to be read.
     *
     * The coordinates are zeroed rather than merely ignored, because "the server promises not
     * to look" is a weaker guarantee than never having sent them — and this feature carries an
     * IP warning and a documented promise that location leaves the client only while a round is
     * running. Keeping that promise exactly is worth one boolean.
     */
    private boolean statusOnly;

    public PositionPayload(String roomCode, int x, int y, int plane, boolean instance) {
        this.roomCode = roomCode;
        this.x = x;
        this.y = y;
        this.plane = plane;
        this.instance = instance;
    }

    /** A request that carries no location at all, only the question. */
    public static PositionPayload statusOnly(String roomCode) {
        PositionPayload p = new PositionPayload(roomCode, 0, 0, 0, false);
        p.statusOnly = true;
        return p;
    }
}

