package com.thebirdhouse.plugin;

import lombok.Data;

/**
 * Payload sent to The Birdhouse backend when submitting a drop proof.
 */
@Data
public class ProofPayload {
    private String roomCode;
    private String playerName;
    private String tileKey;
    private String tileName;
    // Territory War proofs are reviewed by territory, not by the drop that took it, so the
    // backend stores this alongside the tile name for the approval screen.
    private String territoryName;
    private String gameType;
    private String itemName;
    private String npcName;
    private int quantity;
    // Grand Exchange value of the whole stack. Sent because the backend has no price data
    // of its own, and Clue Trail ranks players partly on the value of what they open.
    private long value;
    private int itemId;
    private long timestamp;
    // True only for proofs the player submitted by hand from the board window. The backend
    // routes these to admin review instead of auto-approving them, because nothing
    // witnessed the drop.
    private boolean manual;
    // Identifies the single kill this proof came out of, shared by every item in the same
    // drop. A kill-count tile counts kills, but the plugin submits per item, so Zulrah
    // handing over four things at once would otherwise read as four kills. The backend
    // used to collapse those by ignoring repeats within ten seconds, which also swallowed
    // genuine kills of anything that dies faster than that. Matching on this instead
    // collapses exactly the rolls that shared a kill and nothing else. Null for gathered
    // items, which are not kills.
    private String killId;
}

package com.thebirdhouse.plugin;

import lombok.Value;

/**
 * Outcome of a proof submission.
 *
 * The backend answers a rejected proof with HTTP 200 and a {@code reason} in the body
 * (mismatched item, hidden tile, event not started), so a bare success flag on the HTTP
 * status is not enough to tell a player why nothing happened.
 */
@Value
public class ProofResult {

    boolean ok;
    boolean duplicate;
    String message;

    /**
     * Kills banked on this tile so far, or 0 when the submission was not a kill.
     *
     * A kill-count tile keeps one proof per player and counts up, rather than filing a
     * proof per kill, so only the first kill's screenshot is worth anything. This is how
     * the client learns a tally is open and stops capturing for that tile.
     */
    int kills;

    static ProofResult accepted() {
        return new ProofResult(true, false, null, 0);
    }

    static ProofResult accepted(int kills) {
        return new ProofResult(true, false, null, kills);
    }

    static ProofResult duplicate(String message) {
        return new ProofResult(true, true, message, 0);
    }

    static ProofResult rejected(String message) {
        return new ProofResult(false, false, message, 0);
    }
}

package com.thebirdhouse.plugin;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.ui.DrawManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Consumer;
import javax.imageio.ImageIO;

@Slf4j
@Singleton
public class ScreenshotHelper {

    @Inject
    private DrawManager drawManager;

    @Inject
    private Client client;

    /**
     * Request a screenshot on the next rendered frame.
     * The callback is invoked asynchronously with the JPEG bytes (or null on failure).
     * This does NOT block the calling thread.
     */
    public void captureAsync(Consumer<byte[]> callback) {
        try {
            drawManager.requestNextFrameListener(image -> {
                byte[] result = encodeImage(image, "DrawManager");
                if (result != null) {
                    callback.accept(result);
                } else {
                    log.warn("[Birdhouse] DrawManager capture failed, trying canvas fallback");
                    byte[] fallback = captureFromCanvas();
                    callback.accept(fallback);
                }
            });
        } catch (Exception e) {
            log.error("[Birdhouse] Failed to request screenshot frame, trying canvas fallback", e);
            byte[] fallback = captureFromCanvas();
            callback.accept(fallback);
        }
    }

    private byte[] captureFromCanvas() {
        try {
            Canvas canvas = client.getCanvas();
            if (canvas == null) {
                log.warn("[Birdhouse] Canvas is null");
                return null;
            }

            int w = canvas.getWidth();
            int h = canvas.getHeight();
            if (w <= 0 || h <= 0) {
                log.warn("[Birdhouse] Canvas has invalid size: {}x{}", w, h);
                return null;
            }

            BufferedImage img = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);
            Graphics2D g = img.createGraphics();
            canvas.paint(g);
            g.dispose();

            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            boolean written = ImageIO.write(img, "jpg", baos);
            if (!written || baos.size() == 0) {
                log.warn("[Birdhouse] Canvas fallback: ImageIO.write failed");
                return null;
            }

            byte[] bytes = baos.toByteArray();
            log.info("[Birdhouse] Canvas fallback screenshot: {} bytes ({}x{})", bytes.length, w, h);
            return bytes;
        } catch (Exception e) {
            log.error("[Birdhouse] Canvas fallback failed", e);
            return null;
        }
    }

    private byte[] encodeImage(Image image, String source) {
        try {
            if (image == null) {
                log.warn("[Birdhouse] {} frame was null", source);
                return null;
            }

            int w = image.getWidth(null);
            int h = image.getHeight(null);
            if (w <= 0 || h <= 0) {
                log.warn("[Birdhouse] {} has invalid dimensions: {}x{}", source, w, h);
                return null;
            }

            BufferedImage rgb = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);
            Graphics2D g = rgb.createGraphics();
            g.drawImage(image, 0, 0, null);
            g.dispose();

            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            boolean written = ImageIO.write(rgb, "jpg", baos);
            if (!written || baos.size() == 0) {
                log.warn("[Birdhouse] {} ImageIO.write failed (written={})", source, written);
                return null;
            }

            byte[] bytes = baos.toByteArray();
            log.info("[Birdhouse] {} screenshot captured: {} bytes ({}x{})", source, bytes.length, w, h);
            return bytes;
        } catch (Exception e) {
            log.error("[Birdhouse] {} encode failed", source, e);
            return null;
        }
    }
}

package com.thebirdhouse.plugin;

import lombok.Data;

/**
 * Session lifecycle event sent to The Birdhouse backend.
 */
@Data
public class SessionEvent {
    private String type; // "login", "logout", "heartbeat"
    private String playerName;
    private long timestamp;
    private long durationMs; // Only set on logout

    // Team status rides along on the session write that already happens rather than
    // getting a reporting loop of its own. shareStatus is sent every time, including
    // when false, because that is what tells the server to clear a world it already
    // stored — switching the toggle off has to take effect, not just stop updating.
    private boolean shareStatus;
    private int world;

    public SessionEvent(String type, String playerName, long timestamp) {
        this.type = type;
        this.playerName = playerName;
        this.timestamp = timestamp;
    }
}

package com.thebirdhouse.plugin;

import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

/**
 * Tracks player session time and reports to The Birdhouse backend.
 * Sends heartbeats every 5 minutes so the server knows the player is active, and
 * flushes accumulated activity on its own faster cadence.
 */
@Slf4j
@Singleton
public class SessionTracker {

    private static final long HEARTBEAT_INTERVAL_MS = 5 * 60 * 1000; // 5 minutes

    // The activity flush used to ride the heartbeat, which meant kill counts only
    // reached the board in five-minute steps. That is invisible on a leaderboard but
    // very visible in The Delve, where kills ARE the currency: you kill a boss and the
    // supply counter sits still long enough to look broken.
    //
    // It gets its own faster cadence because a flush is now cheap. flush() returns
    // early when nothing has accumulated, so an idle client still sends nothing, and
    // the server reads only the flushing player's roster entry rather than the whole
    // clan's — so the cost of a flush no longer scales with event size.
    private static final long FLUSH_INTERVAL_MS = 60 * 1000; // 1 minute

    @Inject
    private BirdhouseApiClient apiClient;

    @Inject
    private ActivityTracker activityTracker;

    @Inject
    private BirdhouseConfig config;

    private final ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor();
    private ScheduledFuture<?> heartbeatTask;
    private ScheduledFuture<?> flushTask;
    private String currentPlayer;
    private long sessionStart;

    /**
     * Notified once the server has actually been told about a session change.
     *
     * The team status panel does not know its own state — it reads presence back from the
     * server. So it cannot be refreshed on the login event: the login write goes out a
     * few ticks later, once the client can say who we are, and asynchronously after that.
     * Refreshing any earlier re-reads exactly the state we are about to change, and the
     * panel then showed us offline until the next poll came round.
     */
    private volatile Runnable onReported = () -> {};

    /** Pushed in by the plugin, which owns the panel this has no business knowing about. */
    public void setSessionReportedListener(Runnable listener) {
        onReported = listener != null ? listener : () -> {};
    }

    private void report(SessionEvent e) {
        Runnable listener = onReported;
        apiClient.reportSession(e).thenRun(listener);
    }

    // Pushed in from the plugin's event handlers rather than read from the client here,
    // because the heartbeat runs on this scheduler thread and reading client state off
    // the client thread is exactly the kind of thing that works until it doesn't.
    private volatile int world;

    /**
     * Stamp the session-wide extras onto every event we send.
     *
     * The world goes out even when sharing is off — the server drops it in that case,
     * and sending zero instead would be a second way to say the same thing.
     */
    private SessionEvent event(String type, String playerName, long timestamp) {
        SessionEvent e = new SessionEvent(type, playerName, timestamp);
        e.setShareStatus(config.showTeamStatus());
        e.setWorld(world);
        return e;
    }

    /**
     * Note the world the player is now on.
     *
     * A hop is reported immediately instead of waiting for the next heartbeat, because
     * a world up to five minutes out of date is worse than none: a teammate hops to
     * meet you and finds you gone. This is the only extra write the feature adds, and
     * it happens a handful of times a session rather than on a timer.
     */
    public void setWorld(int newWorld) {
        if (newWorld <= 0 || newWorld == world) {
            return;
        }
        world = newWorld;
        if (currentPlayer != null && config.showTeamStatus()) {
            reportNow();
        }
    }

    /**
     * Push the current sharing state without waiting for the next heartbeat, so turning
     * the toggle off clears the stored world promptly rather than up to five minutes later.
     */
    public void onStatusSharingChanged() {
        if (currentPlayer != null) {
            reportNow();
        }
    }

    private void reportNow() {
        String name = currentPlayer;
        if (name == null) {
            return;
        }
        scheduler.execute(() -> report(event("heartbeat", name, System.currentTimeMillis())));
    }

    public void startSession(String playerName) {
        if (currentPlayer != null && currentPlayer.equals(playerName)) {
            return; // Already tracking this player
        }

        endSession(); // Clean up any existing session

        currentPlayer = playerName;
        sessionStart = System.currentTimeMillis();

        // Start each session with a clean activity slate so nothing carries over.
        activityTracker.reset();

        report(event("login", playerName, sessionStart));

        // The periodic heartbeat deliberately does not notify: it repeats a state the
        // panel has already read, so waking the poll for it would be a request per beat
        // that can only ever confirm what is on screen.
        heartbeatTask = scheduler.scheduleAtFixedRate(
            () -> apiClient.reportSession(event("heartbeat", playerName, System.currentTimeMillis())),
            HEARTBEAT_INTERVAL_MS,
            HEARTBEAT_INTERVAL_MS,
            TimeUnit.MILLISECONDS
        );

        flushTask = scheduler.scheduleAtFixedRate(
            activityTracker::flush,
            FLUSH_INTERVAL_MS,
            FLUSH_INTERVAL_MS,
            TimeUnit.MILLISECONDS
        );

        log.info("Session started for {}", playerName);
    }

    public void endSession() {
        if (currentPlayer == null) return;

        if (heartbeatTask != null) {
            heartbeatTask.cancel(false);
            heartbeatTask = null;
        }
        if (flushTask != null) {
            flushTask.cancel(false);
            flushTask = null;
        }

        // Flush any remaining activity before the session closes.
        activityTracker.flush();

        long duration = System.currentTimeMillis() - sessionStart;
        SessionEvent event = event("logout", currentPlayer, System.currentTimeMillis());
        event.setDurationMs(duration);
        report(event);

        log.info("Session ended for {} ({}m)", currentPlayer, duration / 60000);
        currentPlayer = null;
        // Logging out doesn't put you on world 0, and a stale world must not be
        // re-reported by the next session's login before its first hop.
        world = 0;
    }
}

package com.thebirdhouse.plugin;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.List;

/**
 * Who on your team is online, and what world they're on.
 *
 * A view only, fed by the same poller as the chat panel so having it in both the
 * sidebar and the pop-out window costs one request rather than two.
 *
 * Deliberately shows teammates who are not sharing rather than hiding them, so the
 * list stays a full team roster and a blank status reads as "they haven't switched it
 * on" instead of "they're offline". The server decides what a viewer is allowed to
 * see; nothing here filters, because a client-side filter protects nobody.
 */
public class TeamStatusPanel extends JPanel {

    private static final Color COLOR_ONLINE = new Color(110, 200, 110);
    private static final Color COLOR_OFFLINE = new Color(120, 120, 120);
    private static final Color COLOR_MUTED = new Color(150, 150, 150);
    private static final Color COLOR_ERROR = new Color(255, 120, 120);
    private static final Color COLOR_SELF = new Color(120, 200, 255);

    private final int wrapWidth;
    private final JPanel listPanel;
    private final JLabel titleLabel;
    private final JLabel summaryLabel;

    public TeamStatusPanel(int wrapWidth) {
        this.wrapWidth = wrapWidth;

        setLayout(new BorderLayout(0, 4));
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        titleLabel = new JLabel("Team Status");
        titleLabel.setForeground(Color.WHITE);
        titleLabel.setFont(FontManager.getDefaultFont().deriveFont(Font.BOLD, 14f));
        titleLabel.setBorder(new EmptyBorder(0, 2, 2, 2));
        add(titleLabel, BorderLayout.NORTH);

        listPanel = new JPanel();
        listPanel.setLayout(new BoxLayout(listPanel, BoxLayout.Y_AXIS));
        listPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        listPanel.setBorder(new EmptyBorder(4, 4, 4, 4));

        JScrollPane scroll = new JScrollPane(listPanel,
            ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
            ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        scroll.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
        scroll.getVerticalScrollBar().setUnitIncrement(12);
        scroll.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        add(scroll, BorderLayout.CENTER);

        summaryLabel = new JLabel(" ");
        summaryLabel.setForeground(COLOR_MUTED);
        summaryLabel.setFont(FontManager.getDefaultFont().deriveFont(12f));
        summaryLabel.setBorder(new EmptyBorder(1, 2, 0, 2));
        add(summaryLabel, BorderLayout.SOUTH);

        showNote("Loading\u2026", COLOR_MUTED);
    }

    /** Hand over the current roster. */
    public void setPresence(PresenceData presence) {
        if (presence == null) {
            showNote("Status unavailable \u2014 still trying.", COLOR_ERROR);
            return;
        }

        String team = presence.getTeamName();
        titleLabel.setText(team != null ? "Team Status \u2014 " + team : "Team Status");

        if (presence.getTeamId() == null) {
            showNote("This game has no teams, so there is no team to show.", COLOR_MUTED);
            return;
        }

        // The read is reciprocal, so the server returns nothing until the player's own
        // sharing has registered. Saying so beats an empty list that looks broken.
        if (!presence.isSharing()) {
            showNote("Waiting for your own status to register \u2014 log in to the game and "
                + "this should fill in within a minute.", COLOR_MUTED);
            return;
        }

        List<PresenceMember> members = presence.getMembers();
        if (members == null || members.isEmpty()) {
            showNote("No teammates yet.", COLOR_MUTED);
            return;
        }

        // Rebuilt on every poll unlike the chat thread, because there is no scroll
        // position or typed text to lose here and a "did anything change" comparison
        // would have to cover worlds and relative times anyway.
        listPanel.removeAll();
        int online = 0;
        for (PresenceMember m : members) {
            if (m.isOnline()) {
                online++;
            }
            listPanel.add(memberRow(m));
            listPanel.add(Box.createRigidArea(new Dimension(0, 2)));
        }
        listPanel.revalidate();
        listPanel.repaint();

        summaryLabel.setForeground(COLOR_MUTED);
        summaryLabel.setText(online + " of " + members.size() + " online");
    }

    /** Status could not be loaded, or there is nothing to load. */
    public void showNote(String message, Color color) {
        listPanel.removeAll();
        JLabel note = new JLabel(BoardRenderer.wrapHtml(
            BoardRenderer.escapeHtml(message), wrapWidth, "left"));
        note.setForeground(color != null ? color : COLOR_MUTED);
        note.setFont(FontManager.getDefaultFont().deriveFont(12f));
        note.setAlignmentX(Component.LEFT_ALIGNMENT);
        listPanel.add(note);
        listPanel.revalidate();
        listPanel.repaint();
        summaryLabel.setText(" ");
    }

    private JPanel memberRow(PresenceMember m) {
        JPanel row = new JPanel(new BorderLayout(4, 0));
        row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        row.setAlignmentX(Component.LEFT_ALIGNMENT);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));

        JLabel dot = new JLabel("\u25CF");
        dot.setForeground(m.isOnline() ? COLOR_ONLINE : COLOR_OFFLINE);
        dot.setFont(FontManager.getDefaultFont().deriveFont(12f));
        row.add(dot, BorderLayout.WEST);

        String name = m.getName() != null ? m.getName() : "?";
        JLabel nameLabel = new JLabel(name);
        nameLabel.setForeground(m.isSelf() ? COLOR_SELF : Color.WHITE);
        nameLabel.setFont(FontManager.getDefaultFont().deriveFont(12f));
        row.add(nameLabel, BorderLayout.CENTER);

        JLabel status = new JLabel(statusText(m));
        status.setForeground(m.isOnline() ? COLOR_ONLINE : COLOR_OFFLINE);
        status.setFont(FontManager.getDefaultFont().deriveFont(12f));
        status.setHorizontalAlignment(SwingConstants.RIGHT);
        row.add(status, BorderLayout.EAST);

        row.setToolTipText(name + " \u2014 " + tooltip(m));
        return row;
    }

    /**
     * The right-hand column: a world when there is one, otherwise why there isn't.
     *
     * Kept short because the sidebar is 225px wide and the name has to fit too. The
     * tooltip carries the long version.
     */
    private static String statusText(PresenceMember m) {
        if (!m.isSharing()) {
            return "\u2014";
        }
        if (m.isOnline()) {
            Integer world = m.getWorld();
            return world != null ? "W" + world : "online";
        }
        return since(m.getLastSeen());
    }

    private static String tooltip(PresenceMember m) {
        if (!m.isSharing()) {
            return "not sharing their status";
        }
        if (m.isOnline()) {
            Integer world = m.getWorld();
            return world != null ? "logged in on world " + world : "logged in";
        }
        long seen = m.getLastSeen();
        return seen > 0 ? "last seen " + since(seen) : "not seen this event";
    }

    /**
     * A coarse "how long ago", which is all this is good for: the client heartbeats
     * every five minutes, so anything finer than that would be inventing precision.
     */
    private static String since(long timestamp) {
        if (timestamp <= 0) {
            return "offline";
        }
        long minutes = (System.currentTimeMillis() - timestamp) / 60000;
        if (minutes < 0) {
            return "offline";
        }
        if (minutes < 60) {
            return Math.max(minutes, 1) + "m ago";
        }
        long hours = minutes / 60;
        if (hours < 24) {
            return hours + "h ago";
        }
        return (hours / 24) + "d ago";
    }
}

package com.thebirdhouse.plugin;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.http.api.item.ItemPrice;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import java.awt.Image;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Pictures for board tiles, from the cheapest source that has one.
 *
 * A tile whose match rule names a real item gets the client's own sprite for it. That
 * costs nothing, needs no network, arrives instantly and looks like the game rather
 * than like a web page, so it is always preferred. Only when no item can be resolved
 * does this fall back to the picture the host attached on the site, which is a genuine
 * download and is therefore fetched once and kept for the rest of the session, and only
 * from the handful of hosts listed below.
 *
 * Every cache here is unbounded on purpose: it is keyed by the tiles of the boards a
 * player actually opened, which is tens of entries, and it must survive the board
 * rebuild that happens on every poll or the fallback images would be re-fetched every
 * minute.
 */
@Slf4j
@Singleton
public class TileIcons {

    /** Item sprites are ~36x32; drawn at native size they stay crisp. */
    private static final int REMOTE_ICON_SIZE = 32;
    private static final long MAX_REMOTE_BYTES = 2L * 1024 * 1024;

    /**
     * Hosts a tile picture may be downloaded from, matched exactly or as a subdomain.
     *
     * A tile's picture is a URL chosen by whoever built the board, and the site accepts
     * a pasted link without re-hosting it. Downloading one tells whatever server is
     * behind it the player's IP address, so a board must not be able to aim the client
     * at a host of its choosing: these are the three places the site's own pictures
     * come from, being our storage, our site, and the wiki it autofills from. A tile
     * pointing anywhere else keeps its item sprite and loses only the fallback picture.
     */
    private static final Set<String> ALLOWED_IMAGE_HOSTS = Collections.unmodifiableSet(
        new HashSet<>(Arrays.asList(
            "thebirdhouse.games",
            "runescape.wiki",
            "firebasestorage.googleapis.com",
            "storage.googleapis.com")));

    private final ItemManager itemManager;
    private final OkHttpClient httpClient;

    /** Item name (lowercased) to id, with {@link Optional#empty()} as a negative cache. */
    private final Map<String, Optional<Integer>> itemIds = new ConcurrentHashMap<>();
    private final Map<String, ImageIcon> remoteIcons = new ConcurrentHashMap<>();
    private final Set<String> remoteInFlight = ConcurrentHashMap.newKeySet();

    @Inject
    public TileIcons(ItemManager itemManager, OkHttpClient httpClient) {
        this.itemManager = itemManager;
        this.httpClient = httpClient;
    }

    /**
     * Give this label the best icon available for the tile, if any.
     *
     * Returns whether anything will be drawn, so a caller can lay the cell out for text
     * only rather than leaving a hole where an icon never arrives.
     */
    boolean apply(BoardTile tile, JLabel target) {
        if (tile == null) {
            return false;
        }

        Integer itemId = resolveItemId(tile);
        if (itemId != null) {
            AsyncBufferedImage sprite = itemManager.getImage(itemId);
            if (sprite != null) {
                // addTo repaints the label itself once the sprite finishes loading.
                sprite.addTo(target);
                return true;
            }
        }

        String raw = tile.getImage();
        if (raw == null || raw.trim().isEmpty()) {
            return false;
        }

        HttpUrl url = allowedImageUrl(raw);
        if (url == null) {
            return false;
        }

        String key = url.toString();
        ImageIcon cached = remoteIcons.get(key);
        if (cached != null) {
            target.setIcon(cached);
            return true;
        }

        fetchRemote(url, key, target);
        // The icon lands later, but the cell should still reserve room for it.
        return true;
    }

    // ===== NATIVE ITEM SPRITES =====

    /**
     * The item id behind a tile, or null when nothing about it names a real item.
     *
     * Tile names are player-authored flavour ("Any Raid Purple", "PET!"), so the match
     * rule is what actually names items and is tried first. Only an exact name match
     * counts: {@link ItemManager#search} is a substring search, so "Shards" would
     * otherwise happily return the first of a hundred unrelated items.
     */
    private Integer resolveItemId(BoardTile tile) {
        for (String candidate : candidateNames(tile)) {
            Optional<Integer> id = itemIds.computeIfAbsent(candidate.toLowerCase(), this::lookupItem);
            if (id.isPresent()) {
                return id.get();
            }
        }
        return null;
    }

    /** Item names this tile could plausibly be represented by, best first. */
    private Set<String> candidateNames(BoardTile tile) {
        Set<String> names = new LinkedHashSet<>();
        addAll(names, tile.getMatchItems());
        if (tile.getMatchGroups() != null) {
            for (BoardTile.MatchGroup group : tile.getMatchGroups()) {
                addAll(names, group.getItems());
            }
        }
        addAll(names, tile.getRequiredItems());
        if (tile.getMatchName() != null && !tile.getMatchName().trim().isEmpty()) {
            String matchName = tile.getMatchName().trim();
            // "Boss - Item" rules name the item after the separator.
            int sep = matchName.indexOf(" - ");
            names.add(sep >= 0 ? matchName.substring(sep + 3).trim() : matchName);
        }
        // Bounty tiles are often just named after the item ("Dragon warhammer") with
        // no separate match list, so the label itself is worth a last try.
        if (tile.getName() != null && !tile.getName().trim().isEmpty()) {
            names.add(tile.getName().trim());
        }
        return names;
    }

    private static void addAll(Set<String> target, List<String> source) {
        if (source == null) {
            return;
        }
        for (String value : source) {
            if (value != null && !value.trim().isEmpty()) {
                target.add(value.trim());
            }
        }
    }

    private Optional<Integer> lookupItem(String lowerName) {
        try {
            List<ItemPrice> results = itemManager.search(lowerName);
            if (results == null) {
                return Optional.empty();
            }
            for (ItemPrice result : results) {
                if (result.getName() != null && result.getName().equalsIgnoreCase(lowerName)) {
                    return Optional.of(result.getId());
                }
            }
        } catch (RuntimeException e) {
            log.debug("[Birdhouse] Item lookup failed for '{}': {}", lowerName, e.getMessage());
        }
        return Optional.empty();
    }

    // ===== HOST-SUPPLIED IMAGES =====

    /**
     * The address to download this picture from, or null to leave the tile alone.
     *
     * Plain HTTP is refused along with unknown hosts: every picture the site produces is
     * served over TLS, so allowing http would only ever expose what the player is looking
     * at to their network without making any real tile work.
     */
    private static HttpUrl allowedImageUrl(String raw) {
        HttpUrl url = HttpUrl.parse(raw.trim());
        if (url == null || !"https".equals(url.scheme())) {
            return null;
        }

        String host = url.host().toLowerCase(Locale.ROOT);
        for (String allowed : ALLOWED_IMAGE_HOSTS) {
            if (host.equals(allowed) || host.endsWith("." + allowed)) {
                return url;
            }
        }

        log.debug("[Birdhouse] Ignoring tile image from unapproved host '{}'", host);
        return null;
    }

    /**
     * Most of these are wiki URLs the site filled in automatically, so the bytes usually
     * come from the wiki rather than from our own storage. Either way it happens once per
     * URL per session, and a failure is silent: a missing picture is not worth a
     * complaint in the player's chat.
     */
    private void fetchRemote(HttpUrl url, String key, JLabel target) {
        if (!remoteInFlight.add(key)) {
            return;
        }

        Request request = new Request.Builder().url(url).build();

        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                remoteInFlight.remove(key);
                log.debug("[Birdhouse] Tile image fetch failed: {}", e.getMessage());
            }

            @Override
            public void onResponse(Call call, Response response) {
                try (ResponseBody body = response.body()) {
                    if (!response.isSuccessful() || body == null || body.contentLength() > MAX_REMOTE_BYTES) {
                        return;
                    }
                    ImageIcon icon = scale(readImage(body));
                    if (icon == null) {
                        return;
                    }
                    remoteIcons.put(key, icon);
                    SwingUtilities.invokeLater(() -> {
                        target.setIcon(icon);
                        target.revalidate();
                        target.repaint();
                    });
                } catch (IOException | RuntimeException e) {
                    log.debug("[Birdhouse] Tile image decode failed: {}", e.getMessage());
                } finally {
                    remoteInFlight.remove(key);
                }
            }
        });
    }

    private static BufferedImage readImage(ResponseBody body) throws IOException {
        try (InputStream in = body.byteStream()) {
            return ImageIO.read(in);
        }
    }

    private static ImageIcon scale(BufferedImage image) {
        if (image == null || image.getWidth() <= 0 || image.getHeight() <= 0) {
            return null;
        }
        double factor = Math.min(
            REMOTE_ICON_SIZE / (double) image.getWidth(),
            REMOTE_ICON_SIZE / (double) image.getHeight());
        if (factor >= 1.0) {
            return new ImageIcon(image);
        }
        int w = Math.max(1, (int) Math.round(image.getWidth() * factor));
        int h = Math.max(1, (int) Math.round(image.getHeight() * factor));
        return new ImageIcon(image.getScaledInstance(w, h, Image.SCALE_SMOOTH));
    }

    /** Dropped when the plugin stops so a long session doesn't hold images forever. */
    void clear() {
        remoteIcons.clear();
        remoteInFlight.clear();
        itemIds.clear();
    }
}

