package com.thebirdhouse.plugin;

import com.thebirdhouse.plugin.ImpostorPositionTracker.Sample;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

/**
 * When a position is worth sending, and when the plugin should not be sending at all.
 *
 * Both halves are here because both have a failure mode that is invisible from in game.
 * Sending too little makes an honest player look absent, which in this mode means their
 * alibi quietly stops existing. Sending at all outside a round means collecting a record
 * of where somebody was during a game that is not running, which is the one thing the
 * feature promises not to do.
 */
public class ImpostorPositionTrackerTest {

    private static final long TICK = 10_000;
    private static final long KEEPALIVE = 60_000;

    private static Sample at(int x, int y) {
        return new Sample(x, y, 0, false);
    }

    private static BoardData board(String gameType, String phase) {
        BoardData b = new BoardData();
        b.setGameType(gameType);
        b.setPhase(phase);
        b.setStarted(true);
        return b;
    }

    // ── Whether to report at all ─────────────────────────────────────────────────

    @Test
    public void anImpostorRoundIsReported() {
        assertTrue(ImpostorPositionTracker.roundIsRunning(board("impostor", "round")));
    }

    @Test
    public void everyOtherPhaseIsNot() {
        // The lobby, the meeting, the vote and the reveal are all for talking. Measuring
        // people through them would collect positions the game has no use for.
        for (String phase : new String[]{"lobby", "meeting", "reveal", "done"}) {
            assertFalse(phase, ImpostorPositionTracker.roundIsRunning(board("impostor", phase)));
        }
    }

    // ── Whether to keep talking to the server at all ─────────────────────────────
    //
    // A weaker question than whether a round is running, and it has to be. A kill lands when
    // the round closes, which is the same instant the phase stops being "round" — so a plugin
    // that goes silent on the phase falls silent at exactly the moment the server has something
    // to tell it, and the victim learns they are dead after the meeting they should have kept
    // quiet through.

    @Test
    public void aLiveGameIsStillWorthTalkingToOutsideARound() {
        for (String phase : new String[]{"round", "meeting", "lobby"}) {
            assertTrue(phase, ImpostorPositionTracker.gameIsLive(board("impostor", phase)));
        }
    }

    @Test
    public void theLobbyIsLiveSoPeopleCanReadyUp() {
        BoardData notStarted = board("impostor", "lobby");
        notStarted.setStarted(false);
        assertTrue(ImpostorPositionTracker.gameIsLive(notStarted));
        assertTrue(ImpostorPositionTracker.shouldSample(notStarted));
    }

    @Test
    public void aFinishedGameIsNotLive() {
        assertFalse(ImpostorPositionTracker.gameIsLive(board("impostor", "done")));
        assertFalse(ImpostorPositionTracker.gameIsLive(board("impostor", "reveal")));
    }

    @Test
    public void theLobbyAndARoundAreSampled() {
        assertTrue(ImpostorPositionTracker.shouldSample(board("impostor", "lobby")));
        assertTrue(ImpostorPositionTracker.shouldSample(board("impostor", "round")));
        assertFalse(ImpostorPositionTracker.shouldSample(board("impostor", "meeting")));
    }

    @Test
    public void anotherGameTypeIsNeverLiveEither() {
        assertFalse(ImpostorPositionTracker.gameIsLive(board("bingo", "round")));
        assertFalse(ImpostorPositionTracker.gameIsLive(null));
    }

    @Test
    public void locationLeavesTheClientOnlyDuringARound() {
        // The two gates in one assertion, because the relationship between them IS the design:
        // keep asking for as long as the game is live, but only ever say where you are while a
        // round is running. Anything that made these agree would either lose the death or start
        // sending coordinates through meetings.
        BoardData meeting = board("impostor", "meeting");
        assertTrue("the plugin must keep asking through a meeting",
            ImpostorPositionTracker.gameIsLive(meeting));
        assertFalse("the plugin must not report a position through a meeting",
            ImpostorPositionTracker.shouldSample(meeting));
    }

    @Test
    public void aStatusOnlyRequestCarriesNoLocation() {
        PositionPayload p = PositionPayload.statusOnly("ABC123");

        assertTrue(p.isStatusOnly());
        assertEquals("ABC123", p.getRoomCode());
        // Zeroed rather than merely ignored by the far end: never having sent a coordinate is a
        // stronger promise than the server agreeing not to look at one.
        assertEquals(0, p.getX());
        assertEquals(0, p.getY());
        assertEquals(0, p.getPlane());
        assertFalse(p.isInstance());
    }

    @Test
    public void aRealPositionIsNotMarkedStatusOnly() {
        assertFalse(at(3200, 9860).payload("ABC123").isStatusOnly());
    }

    @Test
    public void anotherGameTypeIsNeverReported() {
        // A bingo player has this plugin too, and nothing about a bingo board should ever
        // start a position loop.
        assertFalse(ImpostorPositionTracker.roundIsRunning(board("bingo", "round")));
        assertFalse(ImpostorPositionTracker.roundIsRunning(board("tilerace", null)));
    }

    @Test
    public void aServerThatSendsNoPhaseIsTreatedAsNoRound() {
        // Older backends omit the field. Defaulting the other way would have the plugin
        // reporting into a server that was never expecting it.
        assertFalse(ImpostorPositionTracker.roundIsRunning(board("impostor", null)));
        assertFalse(ImpostorPositionTracker.roundIsRunning(null));
    }

    // ── When to send ─────────────────────────────────────────────────────────────

    @Test
    public void nothingIsSentBeforeTheTickHasElapsed() {
        // Even having moved. The server dictates the rate, and beating it just costs
        // requests that get throttled at the far end.
        assertFalse(ImpostorPositionTracker.dueToSend(at(3200, 9860), at(3201, 9861), 4_000, TICK, KEEPALIVE));
    }

    @Test
    public void theFirstSampleOfARoundAlwaysGoes() {
        // The server has wiped its record, so a player who has not moved since the last
        // round still has to establish where they are starting from.
        assertTrue(ImpostorPositionTracker.dueToSend(null, at(3200, 9860), TICK, TICK, KEEPALIVE));
    }

    @Test
    public void movingSendsOnTheNextTick() {
        assertTrue(ImpostorPositionTracker.dueToSend(at(3200, 9860), at(3204, 9862), TICK, TICK, KEEPALIVE));
    }

    @Test
    public void standingStillSaysNothingUntilTheKeepalive() {
        // The economy of the whole feature: a stationary player costs one request a minute
        // rather than six.
        Sample still = at(3200, 9860);
        assertFalse(ImpostorPositionTracker.dueToSend(still, at(3200, 9860), TICK, TICK, KEEPALIVE));
        assertFalse(ImpostorPositionTracker.dueToSend(still, at(3200, 9860), 45_000, TICK, KEEPALIVE));
    }

    @Test
    public void standingStillStillChecksInEventually() {
        // The reason send-on-change alone is not enough. Silence has to mean "gone", so
        // somebody who is present and motionless must keep saying so — otherwise the server
        // cannot tell them from a closed client, and their time in the zone is either
        // credited to a player who left or stolen from one who stayed.
        Sample still = at(3200, 9860);
        assertTrue(ImpostorPositionTracker.dueToSend(still, at(3200, 9860), KEEPALIVE, TICK, KEEPALIVE));
        assertTrue(ImpostorPositionTracker.dueToSend(still, at(3200, 9860), KEEPALIVE + 5_000, TICK, KEEPALIVE));
    }

    @Test
    public void nothingIsSentWithoutASample() {
        // Logged out, or the player has not loaded yet.
        assertFalse(ImpostorPositionTracker.dueToSend(at(3200, 9860), null, KEEPALIVE, TICK, KEEPALIVE));
        assertFalse(ImpostorPositionTracker.dueToSend(null, null, KEEPALIVE, TICK, KEEPALIVE));
    }

    @Test
    public void aServerRetunedCadenceIsHonoured() {
        // The rate is the server's to change, so the same movement is due or not depending
        // only on what it last said. A twenty-second tick means a ten-second-old move waits.
        assertFalse(ImpostorPositionTracker.dueToSend(at(3200, 9860), at(3204, 9862), 10_000, 20_000, KEEPALIVE));
        assertTrue(ImpostorPositionTracker.dueToSend(at(3200, 9860), at(3204, 9862), 20_000, 20_000, KEEPALIVE));
    }

    // ── What counts as having moved ──────────────────────────────────────────────

    @Test
    public void aChangeOfFloorIsMovement() {
        // Draynor Manor is three floors and all of them are the manor, so this does not
        // change the zone — but it is still movement, and the server times zones by sample,
        // so a silent floor change would stretch the previous reading over it.
        assertNotEquals(new Sample(3108, 3355, 0, false), new Sample(3108, 3355, 2, false));
    }

    @Test
    public void steppingIntoAnInstanceIsMovement() {
        // The most important one to report promptly: inside an instance the player is off
        // the board entirely, witnessing nothing and witnessed by nobody. Coordinates are
        // reused by instances, so without the flag they would look co-located with anyone
        // standing at the same spot in the real world.
        assertNotEquals(new Sample(3200, 9860, 0, false), new Sample(3200, 9860, 0, true));
        assertTrue(ImpostorPositionTracker.dueToSend(
            new Sample(3200, 9860, 0, false), new Sample(3200, 9860, 0, true), TICK, TICK, KEEPALIVE));
    }

    @Test
    public void theSamePlaceIsTheSameSample() {
        assertEquals(at(3200, 9860), at(3200, 9860));
        assertEquals(at(3200, 9860).hashCode(), at(3200, 9860).hashCode());
    }

    // ── Expiring a refusal ───────────────────────────────────────────────────────

    @Test
    public void aStopAppliesToOneRoomAndPhase() {
        // Keyed rather than a bare boolean so a refusal expires by itself. The server says
        // stop during a round, the phase moves to the meeting and back into the next round,
        // and the key no longer matches — so one stale board arriving mid-transition cannot
        // silence the plugin for the rest of the evening.
        String stopped = ImpostorPositionTracker.stateKey("AB12CD", "round");

        assertEquals(stopped, ImpostorPositionTracker.stateKey("AB12CD", "round"));
        assertNotEquals(stopped, ImpostorPositionTracker.stateKey("AB12CD", "meeting"));
        assertNotEquals(stopped, ImpostorPositionTracker.stateKey("ZZ99ZZ", "round"));
    }

    @Test
    public void aStaleLobbyBoardDoesNotPinThePhaseAfterTheDeal() {
        assertEquals("round", ImpostorPositionTracker.mergePhase("lobby", "round"));
        assertEquals("round", ImpostorPositionTracker.mergePhase("round", "lobby"));
        assertEquals("meeting", ImpostorPositionTracker.mergePhase("round", "meeting"));
        assertEquals("lobby", ImpostorPositionTracker.mergePhase(null, "lobby"));
    }

    @Test
    public void aRoomWithNoPhaseStillHasADistinctKey() {
        // The key is computed on every poll, including when there is no board at all, so it
        // has to survive nulls rather than throwing inside the scheduler.
        assertNotEquals(
            ImpostorPositionTracker.stateKey(null, null),
            ImpostorPositionTracker.stateKey("AB12CD", "round"));
    }

    // ── The payload ──────────────────────────────────────────────────────────────

    @Test
    public void thePayloadCarriesTheCoordinatesAndNothingInterpreted() {
        // The plugin must not be able to name a place. If a zone could be supplied from
        // here, every bounding box on the server would be decorative.
        PositionPayload p = new Sample(3113, 9843, 0, false).payload("AB12CD");

        assertEquals("AB12CD", p.getRoomCode());
        assertEquals(3113, p.getX());
        assertEquals(9843, p.getY());
        assertEquals(0, p.getPlane());
        assertFalse(p.isInstance());
    }

    @Test
    public void anInstancedSampleKeepsItsRawCoordinates() {
        // Deliberately unresolved: the server discards the position when the flag is set, so
        // resolving it would be work in aid of a value nobody reads.
        PositionPayload p = new Sample(2000, 5000, 1, true).payload("AB12CD");

        assertTrue(p.isInstance());
        assertEquals(2000, p.getX());
        assertEquals(5000, p.getY());
        assertEquals(1, p.getPlane());
    }
}

package com.thebirdhouse.plugin;

import org.junit.Test;

import java.util.HashMap;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Crediting a kill-count tile from the game's own announcement.
 *
 * A kill-count tile is normally satisfied by a loot event named after the boss, which
 * quietly fails for the bosses that pay out through something else — the tracker books
 * Wintertodt's crates as "Supply crate (Wintertodt)", so a tile asking for "Wintertodt"
 * saw nothing at all despite the kill being real and announced.
 *
 * The risk in reading the announcement instead is the opposite one: most bosses both
 * announce and drop, and crediting each would double every kill. These pin the parse and
 * the rule that decides which announcements are already accounted for.
 */
public class KillCountTrackerTest {

    private static Map<String, Integer> loot(String name, int tick) {
        Map<String, Integer> m = new HashMap<>();
        m.put(name.toLowerCase(), tick);
        return m;
    }

    // ── Reading the message ──────────────────────────────────────────────────────

    @Test
    public void wintertodtIsSubdued() {
        // The phrasing this whole change exists for.
        assertEquals("Wintertodt", KillCounts.bossFrom("Your subdued Wintertodt count is: 41"));
    }

    @Test
    public void anOrdinaryBossIsKilled() {
        assertEquals("Vorkath", KillCounts.bossFrom("Your Vorkath kill count is: 312"));
    }

    @Test
    public void temporossIsAnOrdinaryCount() {
        assertEquals("Tempoross", KillCounts.bossFrom("Your Tempoross kill count is: 8"));
    }

    @Test
    public void raidsAnnounceACompletion() {
        assertEquals("Chambers of Xeric",
            KillCounts.bossFrom("Your completed Chambers of Xeric count is: 27"));
    }

    @Test
    public void theGauntletAnnouncesACompletionCount() {
        assertEquals("Corrupted Gauntlet",
            KillCounts.bossFrom("Your completion count for Corrupted Gauntlet is: 5"));
    }

    @Test
    public void countsSurviveColourTags() {
        assertEquals("Zulrah",
            KillCounts.bossFrom("Your <col=ff0000>Zulrah</col> kill count is: <col=ff0000>1,024"));
    }

    @Test
    public void aLapCountIsACount() {
        assertEquals("Ardougne Rooftop Course",
            KillCounts.bossFrom("Your Ardougne Rooftop Course lap count is: 150"));
    }

    @Test
    public void ordinaryChatIsNotAKillCount() {
        assertNull(KillCounts.bossFrom("Your bank is full."));
        assertNull(KillCounts.bossFrom("Oh dear, you are dead!"));
        assertNull(KillCounts.bossFrom(""));
        assertNull(KillCounts.bossFrom(null));
    }

    // ── Not crediting the same kill twice ────────────────────────────────────────

    @Test
    public void aBossThatDroppedLootIsNotCreditedAgain() {
        // Vorkath announces a count and drops loot under its own name. The loot already
        // credited the tile, so the announcement must not.
        assertTrue(KillCountTracker.creditedByLoot("Vorkath", 500, loot("Vorkath", 500)));
    }

    @Test
    public void theSuppressionToleratesATickEitherWay() {
        assertTrue(KillCountTracker.creditedByLoot("Vorkath", 502, loot("Vorkath", 500)));
        assertTrue(KillCountTracker.creditedByLoot("Vorkath", 498, loot("Vorkath", 500)));
    }

    @Test
    public void anEarlierKillDoesNotSuppressALaterOne() {
        // Second Vorkath of the trip: the loot from the first is long gone.
        assertFalse(KillCountTracker.creditedByLoot("Vorkath", 600, loot("Vorkath", 500)));
    }

    @Test
    public void wintertodtIsCreditedBecauseItsLootIsNamedDifferently() {
        // The entire point. The crate arrives as "Supply crate (Wintertodt)", which never
        // matches the boss, so nothing suppresses the announcement.
        Map<String, Integer> lootTicks = loot("Supply crate (Wintertodt)", 500);
        assertFalse(KillCountTracker.creditedByLoot("Wintertodt", 500, lootTicks));
    }

    @Test
    public void temporossIsCreditedForTheSameReason() {
        assertFalse(KillCountTracker.creditedByLoot("Tempoross", 500, loot("Reward pool (Tempoross)", 500)));
    }

    @Test
    public void anotherBossesLootSuppressesNothing() {
        assertFalse(KillCountTracker.creditedByLoot("Wintertodt", 500, loot("Vorkath", 500)));
    }

    @Test
    public void noLootAtAllSuppressesNothing() {
        assertFalse(KillCountTracker.creditedByLoot("Wintertodt", 500, new HashMap<>()));
        assertFalse(KillCountTracker.creditedByLoot("Wintertodt", 500, null));
        assertFalse(KillCountTracker.creditedByLoot(null, 500, loot("Vorkath", 500)));
    }

    @Test
    public void suppressionIsCaseInsensitive() {
        assertTrue(KillCountTracker.creditedByLoot("VORKATH", 500, loot("vorkath", 500)));
    }
}

package com.thebirdhouse.plugin;

import com.google.gson.Gson;
import okhttp3.OkHttpClient;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Reading the backend's answer to a submitted proof.
 *
 * A kill-count tile keeps one proof per player and counts up rather than filing a proof
 * per kill, so only the first kill's screenshot is ever stored. The running count in the
 * response is how the client learns a tally is open and stops capturing for that tile —
 * on something cannoned down several to the tick, that is the difference between a few
 * frames a second being encoded and uploaded and none at all.
 *
 * The count must never be mistaken for anything else, and its absence must never be
 * mistaken for a failure: plenty of servers and every other kind of proof omit it.
 */
public class ProofResponseTest {

    private final BirdhouseApiClient client =
        new BirdhouseApiClient(new OkHttpClient(), new Gson());

    @Test
    public void readsTheRunningKillCount() {
        ProofResult r = client.interpretProofResponse(200, "{\"ok\":true,\"kills\":3472}");
        assertTrue(r.isOk());
        assertEquals(3472, r.getKills());
    }

    @Test
    public void theFirstKillOfATallyReportsOne() {
        ProofResult r = client.interpretProofResponse(200, "{\"ok\":true,\"kills\":1}");
        assertTrue(r.isOk());
        assertEquals(1, r.getKills());
    }

    @Test
    public void anOrdinaryDropCarriesNoCount() {
        ProofResult r = client.interpretProofResponse(200, "{\"ok\":true,\"proofId\":\"abc\"}");
        assertTrue(r.isOk());
        assertEquals("a tile with no tally keeps screenshotting", 0, r.getKills());
    }

    @Test
    public void anOlderServerThatSaysNothingIsStillAccepted() {
        ProofResult r = client.interpretProofResponse(200, "{}");
        assertTrue(r.isOk());
        assertEquals(0, r.getKills());
    }

    @Test
    public void anEmptyBodyIsStillAccepted() {
        ProofResult r = client.interpretProofResponse(200, "");
        assertTrue(r.isOk());
        assertEquals(0, r.getKills());
    }

    @Test
    public void aNonsenseCountDoesNotThrowAwayTheProof() {
        // Losing the submission over a field that only saves screenshots would be a
        // bad trade.
        ProofResult r = client.interpretProofResponse(200, "{\"ok\":true,\"kills\":\"lots\"}");
        assertTrue(r.isOk());
        assertEquals(0, r.getKills());
    }

    @Test
    public void aDuplicateCarriesNoCount() {
        // A collapsed twin changed nothing, so it must not be read as opening a tally.
        ProofResult r = client.interpretProofResponse(200, "{\"ok\":true,\"duplicate\":true}");
        assertTrue(r.isOk());
        assertTrue(r.isDuplicate());
        assertEquals(0, r.getKills());
    }

    @Test
    public void aRefusedProofIsStillRefused() {
        ProofResult r = client.interpretProofResponse(
            200, "{\"success\":false,\"reason\":\"That region is still locked\"}");
        assertFalse(r.isOk());
        assertEquals("That region is still locked", r.getMessage());
        assertEquals(0, r.getKills());
    }

    @Test
    public void anErrorStatusIsRejectedWhateverTheBodySays() {
        ProofResult r = client.interpretProofResponse(500, "{\"ok\":true,\"kills\":10}");
        assertFalse(r.isOk());
        assertEquals(0, r.getKills());
    }
}
